def get_rand_prod(s):
 prod = 1
 for i in xrange(len(s)):
  if random.randint(0, 1) == 1:
   prod *= s[i]
 return prod

def gen_freq(s):
 freq = {}
 for i in s:
  if i in freq:
   freq[i] += 1
  else:
   freq[i] = 1
 return freq

def get_score(s, K, freq):
 avg_score = 0
 TIMES = 100
 for i in xrange(TIMES):
  new_prods = []
  for j in xrange(K):
   new_prods.append(get_rand_prod(s))
  new_prods.sort()
  new_freq = gen_freq(new_prods)
  score = 0
  keys = set(freq.keys() + new_freq.keys())
  for k in keys:
   a = freq.get(k, 0)
   b = new_freq.get(k, 0)
   score += (a-b)**2
  avg_score += score
 return avg_score / float(TIMES)

def try_all_sets(cur, N, M, K, freq):
