   { 
    lcmAll = 1; 
    for (int j = 0; j < k; j++) 
     lcmAll = lcm(lcmAll, scan.nextInt()); 
    count = 0; 
    for (int j : SET) { 
     while (count < n && (lcmAll % j) == 0) { 
      lcmAll /= j; 
      res[count] = j; 
      count++; 
     } 
    } 
    if (res[0] == 4 && res[n-1] == 1) 
    { 
     res[0] = 2; 
     res[n-1] = 2; 
    } 
    for (int j : res) 
     System.out.print(j == 1 ? 2 : j); 
    System.out.println(); 
   } 
  } 
 } 
 private static long gcd(long a, long b) 
 { 
  if (b == 0) 
   return a; 
  return gcd(b, a%b); 
 } 
 private static long lcm(long a, long b) { 
  return a / gcd(a, b) * b; 
 } 
} 
