     return (char)c; 
    } 
   } 
  } 

  public String nextLine() throws IOException { 
   buf.setLength(0); 

   while(true) { 
    final int c = read(); 

    if(c == -1 || isLineSep[c]) { 
     if(c == \'\ \') { read(); } 
     break; 
    } 
    buf.append((char)c); 
   } 

   return buf.toString(); 
  } 

  public String next() throws IOException { 
   buf.setLength(0); 
   buf.append(nextChar()); 

   while(true) { 
    try { 
     final int c = read(); 
     if(isSpace[c]) { break; } 
     buf.append((char)c); 
    } 
    catch(IOException e) { 
     break; 
    } 
   } 

   return buf.toString(); 
  } 

  public double nextDouble() throws IOException { 
   return Double.parseDouble(next()); 
  } 

 } 

