    procs = []
    q = multiprocessing.JoinableQueue()
    results = multiprocessing.Queue()
    while len(procs) < num_procs:
        p = multiprocessing.Process(target=_pmap_worker_func, args=(f, q, results))
        procs.append(p)
        p.daemon = True
        p.start()

    for i, a in enumerate(args):
        q.put((i, a))
    # add shutdown commands:
