class TaskC {
 Map<Long, Counter<Long>> probability = new EHashMap<Long, Counter<Long>>();
 int[] digits;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
  int setCount = in.readInt();
  int size = in.readInt();
  int limit = in.readInt();
  int count = in.readInt();
  digits = new int[size];
  init(size, limit, 0L);
  out.printLine("Case #1:");
  for (int i = 0; i < setCount; i++) {
   long[] results = IOUtils.readLongArray(in, count);
   int bestScore = 0;
   long answer = -1;
   for (Map.Entry<Long, Counter<Long>> entry : probability.entrySet()) {
    int currentScore = 0;
    Counter<Long> counter = entry.getValue();
    for (long j : results) {
     if (!counter.containsKey(j))
      currentScore = Integer.MIN_VALUE;
     else
      currentScore += counter.get(j);
    }
    if (currentScore > bestScore) {
     bestScore = currentScore;
     answer = entry.getKey();
    }
   }
   out.printLine(answer);
  }
    }

 private void init(int remaining, int limit, long encoded) {
  if (remaining == 0) {
   Counter<Long> counter = new Counter<Long>();
   long copy = encoded;
   for (int i = 0; i < digits.length; i++) {
    digits[i] = (int) (encoded % 10);
    encoded /= 10;
   }
   for (int i = 0; i < (1 << digits.length); i++) {
    long result = 1;
    for (int j = 0; j < digits.length; j++) {
     if ((i >> j & 1) == 1)
      result *= digits[j];
    }
    counter.add(result);
   }
   probability.put(copy, counter);
   return;
  }
  if (limit == 1)
   return;
  for (int i = 0; i <= remaining; i++) {
   init(remaining - i, limit - 1, encoded);
   encoded *= 10;
   encoded += limit;
  }
 }
}

