class EHashMap<E, V> extends AbstractMap<E, V> {
 private static final int[] shifts = new int[10];

 private int size;
 private HashEntry<E, V>[] data;
 private int capacity;
 private Set<Entry<E, V>> entrySet;

 static {
  Random random = new Random(System.currentTimeMillis());
  for (int i = 0; i < 10; i++)
   shifts[i] = 1 + 3 * i + random.nextInt(3);
 }

 public EHashMap() {
  this(4);
 }

 private void setCapacity(int size) {
  capacity = Integer.highestOneBit(4 * size);
        //noinspection unchecked
        data = new HashEntry[capacity];
 }

 public EHashMap(int maxSize) {
  setCapacity(maxSize);
  entrySet = new AbstractSet<Entry<E, V>>() {
   @Override
   public Iterator<Entry<E, V>> iterator() {
    return new Iterator<Entry<E, V>>() {
     private HashEntry<E, V> last = null;
                    private HashEntry<E, V> current = null;
                    private HashEntry<E, V> base = null;
                    private int lastIndex = -1;
     private int index = -1;

     public boolean hasNext() {
                        if (current == null) {
                            for (index++; index < capacity; index++) {
                                if (data[index] != null) {
                                    base = current = data[index];
                                    break;
                                }
                            }
                        }
                        return current != null;
     }

     public Entry<E, V> next() {
      if (!hasNext())
       throw new NoSuchElementException();
                        last = current;
                        lastIndex = index;
                        current = current.next;
                        if (base.next != last)
                            base = base.next;
      return last;
     }

     public void remove() {
      if (last == null)
       throw new IllegalStateException();
                        size--;
                        if (base == last)
                            data[lastIndex] = last.next;
                        else
                            base.next = last.next;
     }
    };
   }

   @Override
   public int size() {
    return size;
   }
  };
 }

 public EHashMap(Map<E, V> map) {
  this(map.size());
  putAll(map);
 }

 public Set<Entry<E, V>> entrySet() {
  return entrySet;
 }

 public void clear() {
  Arrays.fill(data, null);
  size = 0;
 }

 private int index(Object o) {
  return getHash(o.hashCode()) & (capacity - 1);
 }

 private int getHash(int h) {
  int result = h;
  for (int i : shifts)
   result ^= h >>> i;
  return result;
 }

 public V remove(Object o) {
  if (o == null)
   return null;
  int index = index(o);
        HashEntry<E, V> current = data[index];
        HashEntry<E, V> last = null;
        while (current != null) {
            if (current.key.equals(o)) {
                if (last == null)
                    data[index] = current.next;
                else
                    last.next = current.next;
                size--;
                return current.value;
            }
            last = current;
            current = current.next;
        }
        return null;
 }

 public V put(E e, V value) {
  if (e == null)
   return null;
  int index = index(e);
        HashEntry<E, V> current = data[index];
        if (current != null) {
            while (true) {
                if (current.key.equals(e)) {
                    V oldValue = current.value;
                    current.value = value;
                    return oldValue;
                }
                if (current.next == null)
                    break;
                current = current.next;
            }
        }
        if (current == null)
            data[index] = new HashEntry<E, V>(e, value);
        else
            current.next = new HashEntry<E, V>(e, value);
        size++;
        if (2 * size > capacity) {
            HashEntry<E, V>[] oldData = data;
            setCapacity(size);
            for (HashEntry<E, V> entry : oldData) {
                while (entry != null) {
                    HashEntry<E, V> next = entry.next;
                    index = index(entry.key);
                    entry.next = data[index];
                    data[index] = entry;
                    entry = next;
                }
            }
        }
  return null;
 }

 public V get(Object o) {
  if (o == null)
   return null;
  int index = index(o);
        HashEntry<E, V> current = data[index];
  while (current != null) {
   if (current.key.equals(o))
                return current.value;
            current = current.next;
        }
  return null;
 }

 public boolean containsKey(Object o) {
        if (o == null)
            return false;
        int index = index(o);
        HashEntry<E, V> current = data[index];
        while (current != null) {
            if (current.key.equals(o))
                return true;
            current = current.next;
        }
        return false;
 }

 public int size() {
  return size;
 }

 private static class HashEntry<E, V> implements Entry<E, V> {
  private final E key;
  private V value;
        private HashEntry<E, V> next;

        private HashEntry(E key, V value) {
            this.key = key;
            this.value = value;
        }


        public E getKey() {
            return key;
        }

        public V getValue() {
            return value;
        }

        public V setValue(V value) {
            V oldValue = this.value;
            this.value = value;
            return oldValue;
        }
    }
}

class InputReader {

 private InputStream stream;
 private byte[] buf = new byte[1024];
 private int curChar;
 private int numChars;
 private SpaceCharFilter filter;

 public InputReader(InputStream stream) {
  this.stream = stream;
 }

 public int read() {
  if (numChars == -1)
   throw new InputMismatchException();
  if (curChar >= numChars) {
   curChar = 0;
   try {
    numChars = stream.read(buf);
   } catch (IOException e) {
    throw new InputMismatchException();
   }
   if (numChars <= 0)
    return -1;
  }
  return buf[curChar++];
 }

 public int readInt() {
  int c = read();
  while (isSpaceChar(c))
   c = read();
  int sgn = 1;
  if (c == \'-\') {
   sgn = -1;
   c = read();
  }
  int res = 0;
  do {
   if (c < \'0\' || c > \'9\')
    throw new InputMismatchException();
   res *= 10;
   res += c - \'0\';
   c = read();
  } while (!isSpaceChar(c));
  return res * sgn;
 }

 public long readLong() {
  int c = read();
  while (isSpaceChar(c))
   c = read();
  int sgn = 1;
  if (c == \'-\') {
   sgn = -1;
   c = read();
  }
  long res = 0;
  do {
   if (c < \'0\' || c > \'9\')
    throw new InputMismatchException();
   res *= 10;
   res += c - \'0\';
   c = read();
  } while (!isSpaceChar(c));
  return res * sgn;
 }

 public String readString() {
  int c = read();
  while (isSpaceChar(c))
   c = read();
  StringBuilder res = new StringBuilder();
  do {
   res.appendCodePoint(c);
   c = read();
  } while (!isSpaceChar(c));
  return res.toString();
 }

 public boolean isSpaceChar(int c) {
  if (filter != null)
   return filter.isSpaceChar(c);
  return isWhitespace(c);
 }

 public static boolean isWhitespace(int c) {
  return c == \' \' || c == \'\
\' || c == \'\ \' || c == \'\ \' || c == -1;
 }

 public String next() {
  return readString();
 }

 public interface SpaceCharFilter {
  public boolean isSpaceChar(int ch);
 }
}

