class Problem
{
    private static StreamReader reader;

    static List<int> products(List<int> x)
    {
        List<int> res = new List<int> ();
        foreach (int q in Enumerable.Range(0, 8))
        {
            int prod = 1;
            foreach (int id in Enumerable.Range(0, 3))
                if ((q & (1 << id)) > 0)
                    prod *= x[id];
            res.Add(prod);
        }
        return res;
    }

    static Random random;

