        if(left)
            return;
        keys[kcount]=key;
        prob1[kcount]=res;
        for(int j=0; j<4096; j++)
            prob2[kcount][arr[j]]++;
        kcount++;
    }else{
        int cc=1<<(12-left);
        for(int i=0; i<=left; i++){
            dfs(at+1, 16*key+i, left-i, res/fact[i]);
