    [R, N, M, K] = read_ints(f) 
    P = read_arr(f, R) 
    return [R, N, M, K, P] 

def write_case(f, i, res): 
    f.write('Case #%d:\
'%i) 
    f.write('%s'%res) 
    f.write('\
') 

