using namespace std;

#define BEGIN_SOLVER struct solver {
#define END_SOLVER };

const int MAX_OUT = 10000;
const char *OUTPUT_FORMAT = "%s"; //"Case #%d:\
%s";

#define all(c) (c).begin(), (c).end()
#define iter(c) __typeof((c).begin())
#define present(c, e) ((c).find((e)) != (c).end())
#define cpresent(c, e) (find(all(c), (e)) != (c).end())
#define rep(i, n) for (int i = 0; i < (int)(n); i++)
#define tr(c, i) for (iter(c) i = (c).begin(); i != (c).end(); ++i)
#define pb push_back
#define mp make_pair

typedef long long ll;

int R, N, M, K;

int S;
vector<int> se[20000];
double se_score[20000];

map<ll, vector<int> > idx;

vector<int> cs;

double current_score = 0.0;

double score_table[20];

void gen(int i, int c, int r) {
  if (c == M + 1) {
    if (i == N) {
      int my_id = S++;
      se[my_id] = cs;
      se_score[my_id] = current_score;

      // rep (i, N) printf("%d", cs[i]); printf(" --- %f\
", current_score);
      // !fprintf(stderr, "score: %f\
", current_score);

      rep (b, 1 << N) {
        ll x = 1;
        rep (i, N) if (b & (1 << i)) x *= cs[i];
        vector<int> &v = idx[x];
        if (v.empty() || v.back() != my_id) idx[x].pb(my_id);
      }
    }
    return;
  }

  if (i < N) {
    cs[i] = c;
    gen(i + 1, c, r + 1);
  }

  {
    current_score += score_table[r];
    gen(i, c + 1, 0);
    current_score -= score_table[r];
  }
}

double factorial(int k) {
  double r = 1.0;
  for (int i = 1; i <= k; ++i) r *= i;
  return r;
}

void init() {
  int T_dummy;
  scanf("%d%d%d%d%d", &T_dummy, &R, &N, &M, &K);

  for (int k = 0; k <= N; ++k) {
    score_table[k] = log(pow(6, 12 - k)) - log(factorial(N - k)) - log(factorial(k));
    // fprintf(stderr, " %d:%f\
", k, score_table[k]);
  }

  cs.resize(N);
  S = 0;
  gen(0, 2, 0);

  puts("Case #1:");
  fprintf(stderr, "|S| = %d\
", S);
  // rep (s, S) { rep (i, N) printf("%d", se[s][i]); puts(""); }
}



BEGIN_SOLVER ///////////////////////////////////////////////////////////////////////////////////////

ll X[110];

void input() {
  rep (k, K) cin >> X[k];
}

vector<int> intersection(const vector<int> &a, const vector<int> &b) {
  vector<int> res;

  int an = a.size(), bn = b.size();
  int ai = 0, bi = 0;
  while (ai < an && bi < bn) {
    /***/if (a[ai] < b[bi]) ++ai;
    else if (b[bi] < a[ai]) ++bi;
    else {
      assert(a[ai] == b[bi]);
      res.pb(a[ai]);
      ++ai;
      ++bi;
    }
  }
  return res;
}

void solve() {
  vector<int> ss;

  rep (k, K) {
    ll x = X[k];
    const vector<int> &tss = idx[x];
    // if (tss.size() > 1000000) continue;

    if (ss.empty()) ss = tss;
    else ss = intersection(ss, tss);
    // debug(" ss: %d\
", (int)ss.size());
  }

  if (ss.empty()) {
    debug("OMG!!\
");
    printf("%s\
", string(N, \'2\').c_str());
    return;
  }

  debug(" |ss| = %d\
", (int)ss.size());

  vector<int> ans_cs;
  double ans_score = -1E30;

  rep (i, ss.size()) {
    int s = ss[i];
    const vector<int> &cs = se[s];

    map<ll, int> xs;
    rep (b, 1 << N) {
      ll x = 1;
      rep (i, N) if (b & (1 << i)) x *= cs[i];
      ++xs[x];
    }

    double score = se_score[s];
    rep (k, K) {
      int n = xs[X[k]];
      if (n == 0) goto dmp;
      score += log(n);
    }

    // debug("score: %f\
", score);

    if (score > ans_score) {
      ans_cs = cs;
      ans_score = score;
    }
 dmp:;
  }

  rep (i, N) printf("%d", ans_cs[i]); puts("");
  return;
}










