'%(R, N, M, K)) 
            f_out.write('Case #1:\
') 
            for r in range(R): 
                nums = sorted(random.choice(range(2, M+1)) for i in range(N)) 
                f_out.write(''.join(str(x) for x in nums)) 
                f_out.write('\
') 
                for k in range(K): 
                    if k > 0: 
                        f_in.write(' ') 
                    trial = functools.reduce(operator.mul, (n for n in nums if random.random() < .5), 1) 
                    f_in.write(str(trial)) 
                f_in.write('\
') 

def aux_small(p): 
    res = Counter() 
    for f in [3, 5]: 
        while True: 
            if any(x%f == 0 for x in p): 
                res.update([f]) 
                p = [x//f if (x%f == 0) else x for x in p] 
            else: 
                break 
    if sum(res.values()) == 3: 
        return res 
    if sum(res.values()) == 2: 
        res.update([max(2, max(p))]) 
        return res 
    if sum(res.values()) == 1: 
        if 16 in p: 
            res.update([4, 4]) 
            return res 
        if 8 in p: 
            res.update([2, 4]) 
            return res 
        res.update([2, 2]) 
        return res 
    p = [int(math.log(x, 2)) for x in p] 
    if all(x%2 == 0 for x in p): 
        res.update([4, 4, 4]) 
        return res 
    res.update([2]) 
    if max(p) <= 3: 
        res.update([2, 2]) 
        return res 
    if max(p) == 4: 
        res.update([2, 4]) 
        return res 
    if max(p) == 5: 
        res.update([4, 4]) 
        return res 

