            int key=keys[ki];
            double prob = prob1[ki];
            for(int i=0; i<K; i++){
                auto it2=prob2[ki].find(v[i]);
                if(it2==prob2[ki].end()){
                    prob=0; break;
                }
                prob*=it2->second;
            }
            if(prob > bestprob){
                bestkey=key;
                bestprob=prob;
            }
