   switch (board[i].charAt(3 - i)) { 
   case \'.\': 
    dots++; 
    break; 
   case \'X\': 
    xs++; 
    break; 
   case \'O\': 
    os++; 
    break; 
   } 
  if (dots > 0) 
   return \'.\'; 
  if (os == 0) 
