        }
        for(int j=0;j<4;j++){
            boolean won = true;
            for(int i=0;i<4;i++)if(board[i][j] != \'T\' && board[i][j] != c)won = false;
            if(won)return true;
        }
        boolean won = true;
        for(int i=0;i<4;i++)if(board[i][i] != \'T\' && board[i][i] != c)won = false;
        if(won)return true;
        won = true;
