      board[j][k] = 1; 
     else if(line.charAt(k)==\'O\') 
      board[j][k] = 2; 
     else if(line.charAt(k)==\'T\') 
      board[j][k] = 3; 
     else 
      board[j][k] = 0; 
    } 
   } 
   i++; 
   result = gameState(board);    
   out[test-1] = "Case #" + test + ": " + words[result]; 

   System.out.println(out[test-1]); 

   test++; 
  } 
  return out; 
 } 

