  if(check(board, 1)) 
   return 0; 
  else if(check(board, 2)) 
   return 1; 
  else { 
   for (int i = 0; i < 4; i++) { 
    for (int j = 0; j < 4; j++) { 
     if(board[i][j]==0) 
      return 3; 
    } 
   } 

   return 2;   
  } 
