   for(i=0; i<4; i++) {
    tmp = conv( board[index][i] );
    if( tmp >= 0 )
     sum[index][tmp]++;
    tmp = conv( board[i][index] );
    if( tmp >= 0 )
     sum[4 + index][tmp]++;
   }
   tmp = conv( board[index][index] );
   if( tmp >= 0 )
    sum[8][tmp]++;
   tmp = conv( board[index][3 - index] );
