                int j;
                for (j = 1; j != table[i].size(); ++j) {
                    if (! same(table[i][j], table[i][0]))
                        break;
                }
                if (j == table[i].size())
                    ans = lastCh;
            }


            for (int j = 0; j != table[0].size() && ans == 2; ++j) {    //  |
