 public static int rowCount(int row, char ch) { 
  int ret = 0; 
  for(int i = 0; i < 4; i++) { 
   if(grid[row][i] == ch) { 
    ret++; 
   } 
  } 
  return ret; 
 } 

 public static int colCount(int row, char ch) { 
