    for(int row = 0 ; row < board.length ; ++row){ 
      if(win(board, 0 , row , 1 , 0 , c)){ 
        return true; 
      } 
    } 
    for(int col = 0 ; col < board.length ; ++col){ 
      if(win(board, col , 0 , 0 , 1 , c)){ 
        return true; 
      }       
    } 
    if(win(board , 0 , 0 , 1 , 1 , c)){ 
      return true; 
    } 
    if(win(board , 0 , 3 , 1 , -1 , c)){ 
      return true; 
    } 
    return false; 
