                        board[1] = reader.ReadLine(); 
                        board[2] = reader.ReadLine(); 
                        board[3] = reader.ReadLine(); 
                        reader.ReadLine(); 

                        writer.WriteLine("Case #" + (i + 1) + ": " + solver.Solve(board)); 
                    } 
                } 
            } 
        } 
    } 
} 
