       int usingEnegry = Math.Min(E, R + e) - t; 
       int gain = usingEnegry * tasks[n] + gained[n - 1, e]; 
       if (gain > maxGain) 
        maxGain = gain; 
      } 

      gained[n, t] = maxGain; 
     } 
    } 

    int max = 0; 
    for (int e = 0; e <= E; e++) 
    { 
     if (max < gained[N, e]) 
      max = gained[N, e]; 
    } 

    Console.WriteLine("Case #{0}: {1}", caseNumber + 1, max); 
   } 
  } 
 } 
