    for (int CN = 1; CN <= T; ++CN) {
        cin >> E >> R >> N;
        for (int i = 0; i < N; ++i) {
            cin >> V[i];
        }

        Int res = solve_large();

        cout << "Case #" << CN << ": " << res << endl;
    }

    return 0;
