    } 

    private string Solve() 
    { 
        long[] tmp = longSplit(\' \'); 
        long E = tmp[0]; 
        long R = tmp[1]; 
        R = Math.Min(R, E); 
        int N = (int)tmp[2]; 
        tmp = longSplit(\' \'); 
        BigInteger[] v = new BigInteger[N]; 
        for (int i = 0; i < N; i++) 
            v[i]  = tmp[i]; 
        BigInteger power = 0; 
        BigInteger res = 0; 
        for (int i = 0; i < N; i++) 
        { 
            power += (i == 0 ? E : R); 
            power =BigInteger.Min(power, E); 
            int next = -1; 
            for (int j = i+1; j < N; j++) 
            { 
                if (v[i] <= v[j]) 
                { 
                    next = j; 
                    break; 
                } 
            }//for j 
            if (next == -1) 
            { 
                res += power * v[i]; 
                power = 0; 
            } 
            else 
            { 
                BigInteger gain = (next - i) * R; 
                BigInteger can =BigInteger.Min(power, BigInteger.Max(0,power + gain - E)); 
                res += can * v[i]; 
                power -= can; 
            }//else 
        }//for i 
        return res.ToString(); 
    } 


