long long dfs(int i,long long lmt){
 int u=i>>1;
 long long r=0;
 if (i%2==1){
  if (A[u+1]){
   long long t=min(A[u+1],lmt);
   lmt-=t;
   r+=t;
   A[u+1]-=t;
  }
  long long t=dfs(i-1,lmt);
  return r+t;
 }else{
  if (i==0){
   long long t=min(A[0],lmt);
   A[0]-=t;
   lmt-=t;
   return t;
  }else{
   long long t=min(B[u-1],lmt);
   t=dfs(i-1,t);
   B[u-1]-=t;
   return t;
  }
 }
