    { 
      int max = 0; 

      for (int spend = 0; spend <= curE; ++spend) 
      { 
        int gain = v[i] * spend; 
        if (i < v.Length - 1) 
          gain += Search(i + 1, Math.Min(maxE, curE - spend + R), maxE, R, v); 

        max = Math.Max(max, gain); 
      } 

      return max; 
    } 
  } 
