class TaskB {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
  System.err.println(testNumber);
  int energy = in.readInt();
  int recharge = in.readInt();
  recharge = Math.min(recharge, energy);
  int count = in.readInt();
  long[] value = IOUtils.readLongArray(in, count);
  int[] fromLeft = new int[count];
  int[] toRight = new int[count];
  int[] spent = new int[count];
  int[] order = ArrayUtils.order(value);
  ArrayUtils.reverse(order);
  Arrays.fill(fromLeft, energy);
  for (int i : order) {
   if (fromLeft[i] < toRight[i])
    throw new RuntimeException();
   spent[i] = fromLeft[i] - toRight[i];
   int passed = toRight[i];
   for (int j = i + 1; j < count; j++) {
    passed += recharge;
    if (passed >= fromLeft[j] || spent[j] != 0)
     break;
    fromLeft[j] = passed;
   }
   int required = fromLeft[i];
   for (int j = i - 1; j >= 0; j--) {
    required -= recharge;
    if (required <= toRight[j] || spent[j] != 0)
     break;
    toRight[j] = required;
   }
  }
  long answer = 0;
  for (int i = 0; i < count; i++)
   answer += spent[i] * value[i];
  out.printLine("Case #" + testNumber + ":", answer);
    }
}

class InputReader {

 private InputStream stream;
 private byte[] buf = new byte[1024];
 private int curChar;
 private int numChars;
 private SpaceCharFilter filter;

 public InputReader(InputStream stream) {
  this.stream = stream;
 }

 public int read() {
  if (numChars == -1)
   throw new InputMismatchException();
  if (curChar >= numChars) {
   curChar = 0;
   try {
    numChars = stream.read(buf);
   } catch (IOException e) {
    throw new InputMismatchException();
   }
   if (numChars <= 0)
    return -1;
  }
  return buf[curChar++];
 }

 public int readInt() {
  int c = read();
  while (isSpaceChar(c))
   c = read();
  int sgn = 1;
  if (c == \'-\') {
   sgn = -1;
   c = read();
  }
  int res = 0;
  do {
   if (c < \'0\' || c > \'9\')
    throw new InputMismatchException();
   res *= 10;
   res += c - \'0\';
   c = read();
  } while (!isSpaceChar(c));
  return res * sgn;
 }

 public long readLong() {
  int c = read();
  while (isSpaceChar(c))
   c = read();
  int sgn = 1;
  if (c == \'-\') {
   sgn = -1;
   c = read();
  }
  long res = 0;
  do {
   if (c < \'0\' || c > \'9\')
    throw new InputMismatchException();
   res *= 10;
   res += c - \'0\';
   c = read();
  } while (!isSpaceChar(c));
  return res * sgn;
 }

 public String readString() {
  int c = read();
  while (isSpaceChar(c))
   c = read();
  StringBuilder res = new StringBuilder();
  do {
   res.appendCodePoint(c);
   c = read();
  } while (!isSpaceChar(c));
  return res.toString();
 }

 public boolean isSpaceChar(int c) {
  if (filter != null)
   return filter.isSpaceChar(c);
  return isWhitespace(c);
 }

 public static boolean isWhitespace(int c) {
  return c == \' \' || c == \'\
\' || c == \'\ \' || c == \'\ \' || c == -1;
 }

 public String next() {
  return readString();
 }

 public interface SpaceCharFilter {
  public boolean isSpaceChar(int ch);
 }
}

class OutputWriter {
 private final PrintWriter writer;

 public OutputWriter(OutputStream outputStream) {
  writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
 }

 public OutputWriter(Writer writer) {
  this.writer = new PrintWriter(writer);
 }

 public void print(Object...objects) {
