 public static <T> String toString(Iterable<T> iterable) {
  StringBuilder sb = new StringBuilder();
  sb.append(\'(\');
  boolean first = true;
  for(T v : iterable) {
   if(first)
    first = false;
   else
    sb.append(\',\');
   sb.append(v);
  }
  sb.append(\')\');
  return sb.toString();
 }
}

