    int ntest = getint();
    for (int test = 1; test <= ntest; ++test) {
      long E = getlong();
      long R = getlong();
      int n = getint();
      int[] v = new int[n];
      for (int i = 0; i < n; ++i)
        v[i] = getint();
      TreeSet<int[]> se = new TreeSet<int[]>(new Comparator<int[]>() {
        public int compare(int[] x, int[] y) {
          if (x[0] != y[0]) return y[0] - x[0];
          return y[1] - x[1];
        }
      });
      R = min(R, E);
      long cur = E;
      long res = 0;
      long[] rem = new long[n];
      for (int i = 0; i < n; ++i) {
        if (i == 0) rem[i] = E;
        else rem[i] = R;

        se.add(new int[]{v[i], i});
        int[] last;
        while (((last = se.last()) != null) && last[0] <= v[i] && last[1] != i) {
          rem[i] += rem[last[1]];
          rem[last[1]] = 0;
          se.remove(se.last());
        }
        if (cur + R > E || i == n - 1) {
          long claim = cur + R - E;
          if (i == n - 1) claim = cur;

          while (claim > 0) {
            int[] f = se.first().clone();
            long sub = min(claim, rem[f[1]]);
            // if (sub < 0) System.err.println("WRONG");
            sub = max(sub, 0);
            claim -= sub;
            rem[f[1]] -= sub;
