using System;
class Program
{
    static char[][] t = new char[100][];
    static void Solve()
    {
        string[] parts;
        string line = Console.ReadLine();
        while (line != null && line.Trim().Length == 0) line = Console.ReadLine();
        if (line == null) return;
        parts = line.Trim().Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
        int N = int.Parse(parts[0]);
        int M = int.Parse(parts[1]);
        for (int i = 0; i < N; ++i)
        {
            string row = Console.ReadLine();
            if (row == null) row = "";
            while (row.Length < M) row += ' ';
            t[i] = row.ToCharArray();
        }
        bool ok = true;
        for (int i = 0; i < N; ++i)
        {
            for (int j = 0; j < M; ++j)
            {
                if (t[i][j] == '*')
                {
                    if (i + 1 >= N || j + 1 >= M) ok = false;
                    if (t[i][j + 1] != '*' || t[i + 1][j] != '*' || t[i][j + 1] != '*') ok = false;
                    t[i][j] = 'A'; t[i][j + 1] = 'B';
                    t[i + 1][j] = 'C'; t[i + 1][j + 1] = 'D';
                }
            }
        }
        if (!ok)
        {
            Console.WriteLine("No arrangement possible");
            return;
        }
        for (int i = 0; i < N; ++i)
        {
            Console.WriteLine(new string(t[i], 0, M));
        }
    }

    static int RI()
    {
        string s = Console.ReadLine();
        while (s != null && s.Trim().Length == 0) s = Console.ReadLine();
        return int.Parse(s.Trim());
    }

    static void Main()
    {
        int T = RI();
        for (int i = 1; i <= T; ++i)
        {
            Console.WriteLine("Case #{0}:", i);
            Solve();
        }
    }
}

