import os

class SquareTiles:
    def tester(self):
        sb_lines = []
        loc = r"C:\Pub\A-large.in"
        if not os.path.exists(loc):
            # If input file missing, create a default minimal example to avoid crash
            default = ["1", "2 2", "##", "##"]
            lines = default
        else:
            with open(loc, "r", encoding="utf-8") as f:
                lines = [ln.rstrip("\n") for ln in f.readlines()]
        caseNo = 1
        i = 1
        while i < len(lines):
            spl = [int(x) for x in lines[i].split()]
            i += 1
            r = spl[0]
            c = spl[1]
            data = []
            for k in range(r):
                data.append(list(lines[i]))
                i += 1
            possible = True
            k = 0
            while k < r:
                for j in range(c):
                    if data[k][j] == '#':
                        if not self.Place(k, j, data):
                            possible = False
                            k = 10000
                            break
                k += 1
            sb_lines.append(f"Case #{caseNo}: ")
            caseNo += 1
            if possible:
                for s in data:
                    sb_lines.append("".join(s))
            else:
                sb_lines.append("Impossible")
        outloc = r"C:\Pub\ est.txt"
        outdir = os.path.dirname(outloc)
        if outdir and not os.path.exists(outdir):
            try:
                os.makedirs(outdir)
            except Exception:
                pass
        with open(outloc, "w", encoding="utf-8") as f:
            f.write("\n".join(sb_lines))

    def Place(self, row, col, data):
        r = data[row]
        if col + 1 >= len(r):
            return False
        if r[col] != '#' or r[col + 1] != '#':
            return False
        # Instead of placing slashes like the original, we neutralize contamination
        # by marking a 2x2 block with the letters N,E,U,T (a different objective).
        r[col] = 'N'
        r[col + 1] = 'E'
        if row + 1 >= len(data):
            return False
        r = data[row + 1]
        if r[col] != '#' or r[col + 1] != '#':
            return False
        r[col] = 'U'
        r[col + 1] = 'T'
        return True

if __name__ == "__main__":
    SquareTiles().tester()

