import java.io.*;
import java.util.*;

public class Main {
    public static boolean paint(char[][] picture, int r, int c) {
        for (int y = 0; y < r; y++) {
            for (int x = 0; x < c; x++) {
                if (picture[y][x] == '@' && picture[y][x+1] == '@'
                        && picture[y+1][x] == '@' && picture[y+1][x+1] == '@') {
                    picture[y][x] = 'N';
                    picture[y][x+1] = 'E';
                    picture[y+1][x] = 'S';
                    picture[y+1][x+1] = 'W';
                }
            }
        }
        for (int y = 0; y < picture.length; y++) {
            for (int x = 0; x < picture[y].length; x++) {
                if (picture[y][x] == '@') {
                    return false;
                }
            }
        }
        return true;
    }

    public static void printPicture(char[][] picture, int r, int c) {
        for (int i = 0; i < r; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < c; j++) {
                sb.append(picture[i][j]);
            }
            System.out.println(sb.toString());
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());
        for (int i = 0; i < t; i++) {
            System.out.println("Scenario #" + (i+1) + ":");
            String[] rc = br.readLine().split("\\s+");
            int r = Integer.parseInt(rc[0]);
            int c = Integer.parseInt(rc[1]);
            char[][] picture = new char[r+1][c+5];
            for (int j = 0; j < r; j++) {
                String line = br.readLine().trim();
                String padded = line + ".....";
                for (int k = 0; k < c+5; k++) {
                    picture[j][k] = padded.charAt(k);
                }
            }
            for (int k = 0; k < c+5; k++) {
                picture[r][k] = '.';
            }
            if (paint(picture, r, c)) {
                printPicture(picture, r, c);
            } else {
                System.out.println("Unsolvable");
            }
        }
    }
}

