class Program
{
    static char[][] rr = new char[50][];
    static void Main()
    {
        int t;
        {
            string line = Console.ReadLine();
            if (line == null) return;
            t = int.Parse(line);
        }
        for (int cc = 1; cc <= t; cc++)
        {
            int r, c;
            {
                string[] parts;
                string ln = Console.ReadLine();
                while (ln != null && ln.Trim() == "") ln = Console.ReadLine();
                parts = ln.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
                r = int.Parse(parts[0]);
                c = int.Parse(parts[1]);
            }
            for (int i = 0; i < r; i++)
            {
                string s = Console.ReadLine();
                while (s != null && s.Trim() == "") s = Console.ReadLine();
                rr[i] = s.ToCharArray();
            }
            bool sflag = true;
            int transformedBlocks = 0;
            for (int i = 0; sflag && i < r - 1; i++)
            {
                for (int j = 0; sflag && j < c - 1; j++)
                {
                    if (rr[i][j] == '#')
                    {
                        if (rr[i][j] == '#') rr[i][j] = '/';
                        else sflag = false;
                        if (rr[i][j + 1] == '#') rr[i][j + 1] = '\\';
                        else sflag = false;
                        if (rr[i + 1][j] == '#') rr[i + 1][j] = '\\';
                        else sflag = false;
                        if (rr[i + 1][j + 1] == '#') rr[i + 1][j + 1] = '/';
                        else sflag = false;
                        if (sflag) transformedBlocks++;
                    }
                }
            }
            for (int i = 0; sflag && i < r; i++)
            {
                for (int j = 0; sflag && j < c; j++)
                {
                    if (rr[i][j] == '#')
                    {
                        sflag = false;
                    }
                }
            }
            if (sflag)
            {
                Console.WriteLine("Scenario #{0}: Transformed {1} blocks", cc, transformedBlocks);
                for (int i = 0; i < r; i++) Console.WriteLine(new string(rr[i]));
            }
            else
            {
                Console.WriteLine("Transformation Failed");
            }
        }
    }
}

