import java.io.*;
import java.util.*;

public class Main {
    static final int N = 100;
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        line = br.readLine();
        while(line != null && line.trim().length() == 0) line = br.readLine();
        int tests = Integer.parseInt(line.trim());
        char[][] b = new char[N][N];
        for (int test = 0; test < tests; ++test) {
            // read h and w
            StringTokenizer st = null;
            while (st == null || !st.hasMoreTokens()) {
                line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            int h = Integer.parseInt(st.nextToken());
            int w = Integer.parseInt(st.nextToken());
            // read grid lines
            for (int i = 0; i < h; ++i) {
                String s = br.readLine();
                if (s == null) s = "";
                // ensure at least w characters
                if (s.length() < w) {
                    StringBuilder sb = new StringBuilder(s);
                    while (sb.length() < w) sb.append(' ');
                    s = sb.toString();
                }
                for (int j = 0; j < w; ++j) b[i][j] = s.charAt(j);
                // ensure rest of row is cleared (keep consistency with source)
                for (int j = w; j < N; ++j) b[i][j] = '\0';
            }
            // clear rest of rows to mimic fixed-size buffer behavior
            for (int i = h; i < N; ++i) for (int j = 0; j < N; ++j) b[i][j] = '\0';

            int ok = 1;
            int replacements = 0;
            for (int i = 0; i < h; ++i) {
                for (int j = 0; j < w; ++j) {
                    if (b[i][j] == '#') {
                        if (b[i+1][j] == '#' && b[i][j+1] == '#' && b[i+1][j+1] == '#') {
                            b[i][j] = '/';
                            b[i+1][j+1] = '/';
                            b[i+1][j] = '\\';
                            b[i][j+1] = '\\';
                            replacements++;
                        } else {
                            ok = 0;
                        }
                    }
                }
            }

            System.out.println("Case #" + (test + 1) + ":");
            if (ok == 0) {
                // New functional purpose: report that the grid is corrupt and output a checksum 0
                System.out.println("CORRUPT");
                System.out.println("Checksum: 0");
            } else {
                // New functional purpose: report number of performed patch operations and a simple checksum
                int checksum = 0;
                for (int i = 0; i < h; ++i) {
                    for (int j = 0; j < w; ++j) {
                        checksum += b[i][j];
                    }
                }
                System.out.println("PATCHES: " + replacements);
                System.out.println("Checksum: " + checksum);
            }
        }
    }
}

