using System;
using System.IO;
using System.Collections.Generic;

public class MainClass {
    public static void Main(string[] args) {
        new MainClass().run();
    }

    string inputFile = "input/A-large.in";
    string outputFile = "output.txt";
    StreamReader inReader;
    StreamWriter outWriter;
    Queue<string> st = new Queue<string>();

    void run() {
        inReader = new StreamReader(inputFile);
        outWriter = new StreamWriter(outputFile);
        int testCount = nextInt();
        for (int testCase = 1; testCase <= testCount; testCase++) {
            solve(testCase);
        }
        outWriter.Close();
    }

    int N;
    int M;
    char[][] map;
    int stampedCount = 0;

    void solve(int testCase) {
        N = nextInt();
        M = nextInt();
        map = new char[N][];
        for (int i = 0; i < N; i++)
            map[i] = nextToken().ToCharArray();

        stampedCount = 0;

        lp_start:
        for (;;) {
            for (int i = 0; i + 1 < N; i++)
                for (int j = 0; j + 1 < M; j++) {
                    if (map[i][j] == '#') {
                        if (replace(i, j)) {
                            goto lp_start;
                        } else {
                            goto lp_end;
                        }
                    }
                }
            break;
        }
        lp_end: ;

        bool ok = true;
        for (int i = 0; i < N; i++)
            for (int j = 0; j < M; j++)
                if (map[i][j] == '#')
                    ok = false;

        outWriter.WriteLine("Scenario #" + testCase + ":");
        if (ok) {
            outWriter.WriteLine("Stamped squares: " + stampedCount);
            foreach (char[] s in map)
                outWriter.WriteLine(new string(s));
        } else {
            outWriter.WriteLine("Failed to stamp any further 2x2 blocks");
        }
    }

    bool replace(int i, int j) {
        if (map[i][j] != '#') return false;
        if (map[i + 1][j] != '#') return false;
        if (map[i][j + 1] != '#') return false;
        if (map[i + 1][j + 1] != '#') return false;
        // Change functional purpose: mark a stamped square with corner letters
        map[i][j] = 'A';
        map[i + 1][j + 1] = 'C';
        map[i + 1][j] = 'B';
        map[i][j + 1] = 'D';
        stampedCount++;
        return true;
    }

    string nextToken() {
        while (st.Count == 0) {
            string line = inReader.ReadLine();
            if (line == null) return null;
            string[] parts = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
            foreach (string p in parts) st.Enqueue(p);
        }
        return st.Dequeue();
    }

    int nextInt() {
        string t = nextToken();
        if (t == null) return 0;
        return int.Parse(t);
    }

    long nextLong() {
        return long.Parse(nextToken());
    }

    double nextDouble() {
        return double.Parse(nextToken());
    }

    string nextLine() {
        st.Clear();
        return inReader.ReadLine();
    }

    bool EOF() {
        while (st.Count == 0) {
            string s = inReader.ReadLine();
            if (s == null) return true;
            string[] parts = s.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
            foreach (string p in parts) st.Enqueue(p);
        }
        return false;
    }
}

