#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void solve_case(int t, char **grid, int R, int C) {
    int r, c;
    int impossible = 0;
    for (r = 0; r < R; r++) {
        for (c = 0; c < C; c++) {
            if (grid[r][c] == '*') {
                /* Attempt to annotate a 2x2 cluster of '*' into labelled quadrants.
                   If any neighbor is out of bounds or is '.', mark impossible. */
                if (c + 1 >= C || r + 1 >= R) {
                    impossible = 1;
                    break;
                }
                if (grid[r][c + 1] == '.' || grid[r + 1][c] == '.' || grid[r + 1][c + 1] == '.') {
                    impossible = 1;
                    break;
                }
                grid[r][c] = 'A';
                grid[r][c + 1] = 'B';
                grid[r + 1][c] = 'C';
                grid[r + 1][c + 1] = 'D';
            }
        }
    }

    printf("Case #%d:\n", t);
    if (impossible) {
        printf("Cannot annotate\n");
    } else {
        for (r = 0; r < R; r++) {
            printf("%s\n", grid[r]);
        }
    }
}

int main() {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    int t;
    for (t = 1; t <= T; t++) {
        int R, C;
        if (scanf("%d %d", &R, &C) != 2) return 0;
        char **grid = (char **)malloc(R * sizeof(char *));
        int i;
        char *buf = (char *)malloc((C + 5) * sizeof(char));
        for (i = 0; i < R; i++) {
            if (scanf("%s", buf) != 1) {
                buf[0] = '\0';
            }
            grid[i] = (char *)malloc((C + 1) * sizeof(char));
            strncpy(grid[i], buf, C);
            grid[i][C] = '\0';
        }
        free(buf);
        solve_case(t, grid, R, C);
        for (i = 0; i < R; i++) free(grid[i]);
        free(grid);
    }
    return 0;
}

