                continue;
            if (IsBlue(str, i, j) && IsBlue(str, i + 1, j) && IsBlue(str, i, j + 1) && IsBlue(str, i + 1, j + 1)) {
                // New functional purpose:
                // Instead of converting to slashes, label each 2x2 block with digits:
                // top-left -> '1', top-right -> '2', bottom-left -> '3', bottom-right -> '4'
                string &top = str[i];
                string &bot = str[i + 1];
                // replace two characters starting at j
                if (j + 1 < (int)top.size()) {
                    top[j] = '1';
                    top[j + 1] = '2';
                }
                if (j + 1 < (int)bot.size()) {
                    bot[j] = '3';
                    bot[j + 1] = '4';
                }
            }
        }
    }
    string result;
    for (int i = 0; i < r; i++) {
        if (str[i].find('#') != string::npos)
            return string("Uncovered\n");
        result.append(str[i]);
        result.push_back('\n');
    }
    return result;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        cout << "specify input file" << endl;
        return 0;
    }
    string path = argv[1];
    ifstream sr(path);
    ofstream sw(path + ".out");
    if (!sr.is_open() || !sw.is_open()) {
        cout << "specify input file" << endl;
        return 0;
    }
    string line;
    getline(sr, line);
    // handle possible leading empty lines
    while (line.size() == 0 && !sr.eof()) getline(sr, line);
    int count = stoi(line);
    for (int i = 0; i < count; i++) {
        sw << "Case #" << (i + 1) << ":\n" << SolveTaskA(sr);
    }
    sr.close();
    sw.close();
    return 0;
}

