            for (j = 0; j < m; j++)
                if (buf[i, j] == 'T' && buf[i, j + 1] == 'T' && buf[i + 1, j] == 'T' && buf[i + 1, j + 1] == 'T')
                {
                    buf[i, j] = '1';
                    buf[i, j + 1] = '2';
                    buf[i + 1, j] = '3';
                    buf[i + 1, j + 1] = '4';
                }
    }

    static bool check()
    {
        int i, j;
        for (i = 0; i < n; i++)
            for (j = 0; j < m; j++)
                if (buf[i, j] == 'T')
                    return false;
        return true;
    }

    static void Main()
    {
        string all = Console.In.ReadToEnd();
        string[] parts = all.Split(new char[] { ' ', '\n', '\r', '\t' }, StringSplitOptions.RemoveEmptyEntries);
        int idx = 0;

        int tc = 0;
        if (parts.Length > 0)
            tc = int.Parse(parts[idx++]);

        for (int t = 0; t < tc; t++)
        {
            n = int.Parse(parts[idx++]);
            m = int.Parse(parts[idx++]);
            int i, j;
            for (i = 0; i < n; i++)
            {
                string s = parts[idx++];
                for (j = 0; j < m; j++)
                    buf[i, j] = s[j];
            }
            for (i = 0; i <= n; i++)
