    for(int j = 0; j < M; j++) { 
     F[i][j] = S.charAt(j); 
    } 
   } 

   for(int i = 0; i < N - 1; i++) { 
    for(int j = 0; j < M - 1; j++) { 
     if(F[i][j] == \'#\' && F[i + 1][j] == \'#\' && F[i][j + 1] == \'#\' && F[i + 1][j + 1] == \'#\') { 
      F[i][j] = \'/\'; 
      F[i][j + 1] = \'\\\\\'; 
      F[i + 1][j] = \'\\\\\'; 
