    for(int j = 0; j < M; j++) { 
     if(F[i][j] == \'#\') { 
      ok = false; 
     } 
    } 
   } 

   if(!ok) { 
    out.println("Impossible"); 
   } else { 
    for(int i = 0; i < N; i++) { 
     for(int j = 0; j < M; j++) { 
      out.print(F[i][j]); 
     } 
     out.print("\
"); 
    } 
   } 
  } 
 } 

