#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

static bool IsLeftTopBlueTile(char **tileMapping, int i, int j, int rowNumber, int columnNumber)
{
    bool isLeftBlueTile = false;
    if (j == 0 || tileMapping[i][j - 1] != '#')
    {
        isLeftBlueTile = true;
    }
    bool isTopBlueTile = false;
    if (i == 0 || tileMapping[i - 1][j] != '#')
    {
        isTopBlueTile = true;
    }
    return isLeftBlueTile && isTopBlueTile;
}

int main(int argc, char *argv[])
{
    FILE *inputFileStream = fopen("input.txt", "r");
    if (!inputFileStream) return 1;
    FILE *outputFileStream = fopen("output.txt", "w");
    if (!outputFileStream)
    {
        fclose(inputFileStream);
        return 1;
    }

    char caseNumberString[256];
    if (!fgets(caseNumberString, sizeof(caseNumberString), inputFileStream))
    {
        fclose(inputFileStream);
        fclose(outputFileStream);
        return 1;
    }
    int caseNumber = atoi(caseNumberString);

    for (int caseIndex = 1; caseIndex <= caseNumber; ++caseIndex)
    {
        char settingString[256];
        if (!fgets(settingString, sizeof(settingString), inputFileStream))
            break;
        // Trim newline
        settingString[strcspn(settingString, "\r\n")] = 0;

        int rowNumber = 0;
        int columnNumber = 0;
        {
            char *p = settingString;
            while (*p == ' ') ++p;
            sscanf(p, "%d %d", &rowNumber, &columnNumber);
        }

        int blueTileNumber = 0;
        char **tileMapping = (char **)malloc(rowNumber * sizeof(char *));
        for (int i = 0; i < rowNumber; ++i)
        {
            tileMapping[i] = (char *)malloc(columnNumber * sizeof(char));
        }

        for (int i = 0; i < rowNumber; ++i)
        {
            char tileRowString[4096];
            if (!fgets(tileRowString, sizeof(tileRowString), inputFileStream))
            {
                // Fill rest with dots if input prematurely ends
                for (int j = 0; j < columnNumber; ++j)
                {
                    tileMapping[i][j] = '.';
                }
                continue;
            }
            tileRowString[strcspn(tileRowString, "\r\n")] = 0;
            int len = strlen(tileRowString);
            for (int j = 0; j < columnNumber; ++j)
            {
                char currentTile = (j < len) ? tileRowString[j] : '.';
                if (currentTile == '#')
                {
                    ++blueTileNumber;
                }
                tileMapping[i][j] = currentTile;
            }
        }

        while (blueTileNumber > 0)
        {
            int currentStartTileRow = -1;
            int currentStartTileColumn = -1;
            for (int i = 0; i < rowNumber; ++i)
            {
                for (int j = 0; j < columnNumber; ++j)
                {
                    if (tileMapping[i][j] == '#' && IsLeftTopBlueTile(tileMapping, i, j, rowNumber, columnNumber))
                    {
                        currentStartTileRow = i;
                        currentStartTileColumn = j;
                        break;
                    }
                }
                if (currentStartTileRow != -1)
                    break;
            }
            if (currentStartTileRow == -1)
            {
                break;
            }
            if (currentStartTileRow == rowNumber - 1 || currentStartTileColumn == columnNumber - 1)
            {
                break;
            }
            if (tileMapping[currentStartTileRow + 1][currentStartTileColumn] != '#' ||
                tileMapping[currentStartTileRow][currentStartTileColumn + 1] != '#' ||
                tileMapping[currentStartTileRow + 1][currentStartTileColumn + 1] != '#')
            {
                break;
            }

            // New functional purpose:
            // Mark each found 2x2 block of '#' as a stamped tile using characters 'A','B','C','D'
            tileMapping[currentStartTileRow][currentStartTileColumn] = 'A';
            tileMapping[currentStartTileRow + 1][currentStartTileColumn] = 'B';
            tileMapping[currentStartTileRow][currentStartTileColumn + 1] = 'C';
            tileMapping[currentStartTileRow + 1][currentStartTileColumn + 1] = 'D';

            blueTileNumber -= 4;
        }

        fprintf(outputFileStream, "Case #%d:\n", caseIndex);
        if (blueTileNumber == 0)
        {
            for (int i = 0; i < rowNumber; ++i)
            {
                for (int j = 0; j < columnNumber; ++j)
                {
                    fputc(tileMapping[i][j], outputFileStream);
                }
                fputc('\n', outputFileStream);
            }
        }
        else
        {
            // Changed message to reflect different objective wording
            fprintf(outputFileStream, "Cannot convert\n");
        }

        for (int i = 0; i < rowNumber; ++i)
        {
            free(tileMapping[i]);
        }
        free(tileMapping);
    }

    fclose(outputFileStream);
    fclose(inputFileStream);
    return 0;
}

using System;
using System.Collections.Generic;

class Program
{
    static char[][] d = new char[100][];

    static void solve(int r, int c)
    {
        int i, j, stop = 0;
        for (i = 0; i < r; i++)
        {
            if (stop)
                break;
            for (j = 0; j < c; j++)
            {
                if (d[i][j] == '*')
                {
                    if ((i + 1) >= r || (j + 1) >= c)
                    {
                        stop = 1;
                        break;
                    }
                    else
                    {
                        if (d[i + 1][j] == '*' && d[i][j + 1] == '*' && d[i + 1][j + 1] == '*')
                        {
                            d[i][j] = 'A';
                            d[i + 1][j] = 'C';
                            d[i][j + 1] = 'B';
                            d[i + 1][j + 1] = 'D';
                        }
                        else
                        {
                            stop = 1;
                            break;
                        }
                    }
                }
            }
        }

        if (stop == 1)
            Console.WriteLine("Transformation Failed");
        else
            for (i = 0; i < r; i++)
                Console.WriteLine(new string(d[i]));
    }

    static void Main()
    {
        var tokens = new Queue<string>();
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            var parts = line.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
            foreach (var p in parts) tokens.Enqueue(p);
        }

        int t = 0, n = 0, i = 0, j = 0, r = 0, c = 0;
        if (tokens.Count > 0) t = int.Parse(tokens.Dequeue());
        for (i = 1; i <= t; i++)
        {
            if (tokens.Count > 0) r = int.Parse(tokens.Dequeue());
            if (tokens.Count > 0) c = int.Parse(tokens.Dequeue());
            for (j = 0; j < r; j++)
            {
                string s = "";
                if (tokens.Count > 0) s = tokens.Dequeue();
                d[j] = s.ToCharArray();
            }
            Console.WriteLine("Test #{0}:", i);
            solve(r, c);
        }
    }
}

