    static bool FillSpot(int i, int j)
    {
        if (i >= R - 1 || j >= C - 1)
            return false;
        for (int i2 = i; i2 < i + 2; i2++)
        {
            for (int j2 = j; j2 < j + 2; j2++)
            {
                if (grid[i2][j2] != '#')
                    return false;
            }
        }
        grid[i][j] = 'A';
        grid[i][j + 1] = 'B';
        grid[i + 1][j] = 'C';
        grid[i + 1][j + 1] = 'D';
        return true;
    }

    static bool ConvertToTags()
    {
        for (int i = 0; i < R; i++)
        {
            for (int j = 0; j < C; j++)
            {
                if (grid[i][j] == '#')
                {
                    if (!FillSpot(i, j))
                        return false;
                }
            }
        }
        return true;
    }

    static void Main()
    {
        var lines = new List<string>();
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            lines.Add(line);
        }
        int ptr = 0;
        if (lines.Count == 0)
            return;
        int T = int.Parse(lines[ptr++].Trim());
        for (int t = 0; t < T; t++)
        {
            var parts = lines[ptr++].Trim().Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
            R = int.Parse(parts[0]);
            C = int.Parse(parts[1]);
            grid = new char[R][];
            for (int i = 0; i < R; i++)
            {
                grid[i] = lines[ptr++].Trim().ToCharArray();
            }
            Console.WriteLine("Case #{0}:", t + 1);
            if (!ConvertToTags())
            {
                Console.WriteLine("Impossible");
                continue;
            }
            for (int i = 0; i < R; i++)
            {
                Console.WriteLine(new string(grid[i]));
            }
        }
    }
