import sys
import random

class A:
    def __init__(self):
        self.tokens = iter(sys.stdin.read().split())
        self.eof = False
        self.rand = random.Random(125475452)
        self.FNAME = "A-large"

    def nextToken(self):
        try:
            return next(self.tokens)
        except StopIteration:
            self.eof = True
            return "0"

    def nextInt(self):
        return int(self.nextToken())

    def nextDouble(self):
        return float(self.nextToken())

    def run(self):
        try:
            self.solve()
        except Exception as e:
            sys.exit(566)

    def solve(self):
        T = self.nextInt()
        for test in range(1, T + 1):
            n = self.nextInt()
            m = self.nextInt()
            c = [None] * n
            for i in range(n):
                c[i] = list(self.nextToken())
            good = True
            blocks = []
            outer_break = False
            for i in range(n):
                for j in range(m):
                    if c[i][j] == '#':
                        if i + 1 >= n or j + 1 >= m or c[i + 1][j] != '#' or c[i][j + 1] != '#' or c[i + 1][j + 1] != '#':
                            good = False
                            outer_break = True
                            break
                        else:
                            # Instead of drawing slashes, label quadrants with letters to mark detected blocks
                            c[i][j] = 'A'
                            c[i + 1][j] = 'B'
                            c[i][j + 1] = 'C'
                            c[i + 1][j + 1] = 'D'
                            blocks.append((i, j))
                if outer_break:
                    break
            print("Case #{}:".format(test))
            if not good:
                print("Cannot label")
            else:
                for row in c:
                    print("".join(row))
                # New objective: report the number of labeled 2x2 blocks and their top-left coordinates (0-based)
                print("Blocks:", len(blocks))
                for (bi, bj) in blocks:
                    print(bi, bj)

