import java.io.*;
import java.util.*;

public class Program {
    public static void main(String[] args) throws Exception {
        InputStream inputFileStream = new FileInputStream("input.txt");
        BufferedReader inputReader = new BufferedReader(new InputStreamReader(inputFileStream));
        OutputStream outputFileStream = new FileOutputStream("output.txt");
        BufferedWriter outputWriter = new BufferedWriter(new OutputStreamWriter(outputFileStream));
        String caseNumberString = inputReader.readLine();
        int caseNumber = Integer.parseInt(caseNumberString.trim());
        for (int caseIndex = 1; caseIndex <= caseNumber; ++caseIndex) {
            String settingString = inputReader.readLine();
            int rowNumber = Integer.parseInt(settingString.trim().split(" ")[0]);
            int columnNumber = Integer.parseInt(settingString.trim().split(" ")[1]);
            int blueTileNumber = 0;
            char[][] tileMapping = new char[rowNumber][columnNumber];
            for (int i = 0; i < rowNumber; ++i) {
                String tileRowString = inputReader.readLine();
                for (int j = 0; j < columnNumber; ++j) {
                    char currentTile = tileRowString.charAt(j);
                    if (currentTile == '#') {
                        ++blueTileNumber;
                    }
                    tileMapping[i][j] = currentTile;
                }
            }
            while (blueTileNumber > 0) {
                int currentStartTileRow = -1;
                int currentStartTileColumn = -1;
                for (int i = 0; i < rowNumber; ++i) {
                    for (int j = 0; j < columnNumber; ++j) {
                        if (tileMapping[i][j] == '#' && IsLeftTopBlueTile(tileMapping, i, j, rowNumber, columnNumber)) {
                            currentStartTileRow = i;
                            currentStartTileColumn = j;
                            break;
                        }
                    }
                    if (currentStartTileRow != -1)
                        break;
                }
                if (currentStartTileRow == -1) {
                    break;
                }
                if (currentStartTileRow == rowNumber - 1 || currentStartTileColumn == columnNumber - 1) {
                    break;
                }
                if (tileMapping[currentStartTileRow + 1][currentStartTileColumn] != '#' ||
                    tileMapping[currentStartTileRow][currentStartTileColumn + 1] != '#' ||
                    tileMapping[currentStartTileRow + 1][currentStartTileColumn + 1] != '#') {
                    break;
                }
                // Transform a 2x2 weed patch into a planting pattern:
                // top-left -> 'A', bottom-left -> 'B', top-right -> 'C', bottom-right -> 'D'
                tileMapping[currentStartTileRow][currentStartTileColumn] = 'A';
                tileMapping[currentStartTileRow + 1][currentStartTileColumn] = 'B';
                tileMapping[currentStartTileRow][currentStartTileColumn + 1] = 'C';
                tileMapping[currentStartTileRow + 1][currentStartTileColumn + 1] = 'D';
                blueTileNumber -= 4;
            }
            outputWriter.write(String.format("Scenario #%d:", caseIndex));
            outputWriter.newLine();
            if (blueTileNumber == 0) {
                for (int i = 0; i < rowNumber; ++i) {
                    for (int j = 0; j < columnNumber; ++j) {
                        outputWriter.write(tileMapping[i][j]);
                    }
                    outputWriter.newLine();
                }
            } else {
                outputWriter.write("Failed");
                outputWriter.newLine();
            }
        }
        outputWriter.close();
        outputFileStream.close();
        inputReader.close();
        inputFileStream.close();
    }

    static boolean IsLeftTopBlueTile(char[][] tileMapping, int i, int j, int rowNumber, int columnNumber) {
        boolean isLeftBlueTile = false;
        if (j == 0 || tileMapping[i][j - 1] != '#') {
            isLeftBlueTile = true;
        }
        boolean isTopBlueTile = false;
        if (i == 0 || tileMapping[i - 1][j] != '#') {
            isTopBlueTile = true;
        }
        return isLeftBlueTile && isTopBlueTile;
    }
}

