using namespace std;
class Square_Tiles {
public:
    void gen(ostream& sw, istream& sr) {
        string firstLine;
        getline(sr, firstLine);
        while(firstLine.size() == 0 && sr.good()) getline(sr, firstLine);
        stringstream ss(firstLine);
        string tmp1, tmp2;
        ss >> tmp1 >> tmp2;
        int R = stoi(tmp1);
        int C = stoi(tmp2);
        vector<vector<char>> map(R, vector<char>(C));
        int count = 0;
        for (int i = 0; i < R; i++) {
            string l;
            getline(sr, l);
            if ((int)l.size() == 0 && sr.good()) {
                i--;
                continue;
            }
            for (int j = 0; j < C; j++) {
                map[i][j] = l[j];
                if (l[j] == '#')
                    count++;
            }
        }
        sw << endl;
        if (!solve(map, R, C))
            sw << "CannotPlant" << endl;
        else
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++)
                    sw << map[i][j];
                sw << endl;
            }
    }
private:
    bool solve(vector<vector<char>>& map, int r, int c) {
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                if (map[i][j] == '#') {
                    map[i][j] = 'A';
                    if (j + 1 >= c || i + 1 >= r)
                        return false;
                    if (map[i][j + 1] != '#' || map[i + 1][j] != '#' || map[i + 1][j + 1] != '#')
                        return false;
                    map[i][j + 1] = 'B';
                    map[i + 1][j] = 'C';
                    map[i + 1][j + 1] = 'D';
                }
        return true;
    }
};
