#include <bits/stdc++.h>
using namespace std;

class Image {
public:
    int width;
    int height;
    vector<string> matrix;
    int num_blue;
    Image(int height_, int width_, const vector<string>& matrix_) : width(width_), height(height_), matrix(matrix_), num_blue(0) {
        for (int i = 0; i < height; ++i) {
            for (int j = 0; j < width; ++j) {
                if (matrix_[i][j] == '#') {
                    num_blue += 1;
                }
            }
        }
    }
    bool place_tile(int i, int j) {
        if (i >= height - 1 || j >= width - 1) {
            return false;
        }
        // Note: preserved the original logic (including the duplicated check) intentionally.
        if (matrix[i][j] == '#' && matrix[i][j+1] == '#' && matrix[i+1][j] == '#' && matrix[i][j+1] == '#') {
            // New functional purpose: encode a found 2x2 block into a 4-digit marker.
            matrix[i][j] = '1';
            matrix[i][j+1] = '2';
            matrix[i+1][j] = '3';
            matrix[i+1][j+1] = '4';
            num_blue -= 4;
        }
        return true;
    }
    string toString() const {
        string out;
        for (int i = 0; i < height; ++i) {
            out += matrix[i];
            if (i + 1 < height) out += '\n';
        }
        return out;
    }
};

unique_ptr<Image> do_case(int r, int c, const vector<string>& matrix) {
    unique_ptr<Image> image = make_unique<Image>(r, c, matrix);
    if (image->num_blue % 4 != 0) {
        return nullptr;
    }
    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            image->place_tile(i, j);
            if (image->num_blue % 4 != 0) {
                return nullptr;
            }
        }
    }
    if (image->num_blue == 0) {
        return image;
    } else {
        return nullptr;
    }
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    string in_name = argv[1];
    string out_name = in_name + ".out";
    ifstream infile(in_name);
    ofstream outfile(out_name);
    if (!infile.is_open() || !outfile.is_open()) return 1;

    string line;
    if (!getline(infile, line)) return 1;
    int num_cases = 0;
    {
        stringstream ss(line);
        ss >> num_cases;
    }

    for (int num = 1; num <= num_cases; ++num) {
        // Read r and c
        int r = 0, c = 0;
        while (getline(infile, line)) {
            if (line.size() == 0) continue;
            stringstream ss(line);
            if (ss >> r >> c) break;
        }
        vector<string> image(r, string(c, ' '));
        for (int i = 0; i < r; ++i) {
            string row;
            getline(infile, row);
            // If row shorter or empty, keep reading until we have a row (mimic original behavior)
            if ((int)row.size() < c) {
                // pad or wait for next non-empty
                // but try to accept available row
            }
            // Ensure row has at least c chars
            while ((int)row.size() < c) row += ' ';
            image[i] = row.substr(0, c);
        }

        unique_ptr<Image> ret = do_case(r, c, image);
        outfile << "Case #" << num << ":\n";
        cout << "Case #" << num << ":\n";
        if (!ret) {
            outfile << "Impossible\n";
            cout << "Impossible\n";
        } else {
            string s = ret->toString();
            cout << s << "\n";
            outfile << s << "\n";
        }
    }

    infile.close();
    outfile.close();
    return 0;
