import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    private static boolean printe(Object... args) {
        return true;
    }

    private static String replace(String s, int pos, char ch) {
        return s.substring(0, pos) + ch + s.substring(pos + 1);
    }

    private static String simulate() throws Exception {
        st = new StringTokenizer(br.readLine());
        int r = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        ArrayList<String> t = new ArrayList<>();
        for (int b = 0; b < r; b++) {
            t.add(br.readLine());
        }
        printe((Object) t.toArray());
        for (int y = 0; y < r - 1; y++) {
            int x = 0;
            while (x < c - 1) {
                if (t.get(y).charAt(x) == '#') {
                    if (t.get(y).charAt(x + 1) == '#' && t.get(y + 1).charAt(x) == '#' && t.get(y + 1).charAt(x + 1) == '#') {
                        t.set(y, replace(t.get(y), x, 'O'));
                        t.set(y, replace(t.get(y), x + 1, 'B'));
                        t.set(y + 1, replace(t.get(y + 1), x, 'B'));
                        t.set(y + 1, replace(t.get(y + 1), x + 1, 'O'));
                        x += 1;
                    } else {
                        return "FAILED";
                    }
                }
                x += 1;
            }
        }
        for (int y = 0; y < r; y++) {
            if (t.get(y).charAt(c - 1) == '#') {
                return "FAILED";
            }
        }
        for (int x = 0; x < c; x++) {
            if (t.get(r - 1).charAt(x) == '#') {
                return "FAILED";
            }
        }
        for (int y = 0; y < r; y++) {
            t.set(y, t.get(y).replace("B", "@"));
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < r; i++) {
            if (i > 0) sb.append("\n");
            sb.append(t.get(i));
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        int T = Integer.parseInt(br.readLine());
        for (int i = 0; i < T; i++) {
            System.out.println("Case #" + (i + 1) + ":\n" + simulate());
        }
    }
}

