            // initialize a larger buffer to avoid index errors, mimic original C behavior
            for (x = 0; x < 1005; x++) {
                for (y = 0; y < 1005; y++) {
                    map[x][y] = '.';
                }
            }
            for (x = 0; x < n; x++) {
