                }
            }
            for (x = 0; x < n; x++) {
                for (y = 0; y < m; y++) {
                    if (map[x][y] == 'X') {
                        if (map[x + 1][y] == 'X' && map[x + 1][y + 1] == 'X' && map[x][y + 1] == 'X') {
                            // convert a 2x2 infected block into a cleaned marker pattern
                            map[x][y] = '1';
                            map[x][y + 1] = '2';
                            map[x + 1][y] = '3';
                            map[x + 1][y + 1] = '4';
                        } else {
                            notsol = 1;
                        }
                    }
                }
            }
            System.out.println("Case #" + cases + ":");
            if (notsol == 1) {
                System.out.println("Cleaning failed");
            } else {
                for (x = 0; x < n; x++) {
                    StringBuilder sb = new StringBuilder();
                    for (y = 0; y < m; y++) sb.append(map[x][y]);
                    System.out.println(sb.toString());
                }
            }
        }
    }

