    if (!in.is_open() || !out.is_open()) return 1;

    int testn;
    in >> testn;
    for (int test = 0; test < testn; test++) {
        int R, C;
        in >> R >> C;
        vector<string> arr(R);
        bool impossible = false;
        for (int i = 0; i < (int)arr.size(); i++) {
            in >> arr[i];
        }
        for (int i = 0; i < (int)arr.size(); i++) {
            if (impossible) {
                break;
            }
            for (int j = 0; j < C; j++) {
                string curRow = arr[i];
                char ch = arr[i][j];
                if (ch == '#') {
                    int nH = j + 1;
                    int nV = i + 1;
                    if (nH != (int)curRow.length() && nV != (int)arr.size()) {
                        string nRow = arr[nV];
                        if (curRow[nH] == '#' &&
                            nRow[j] == '#' && nRow[nH] == '#') {
                            // Instead of drawing slashes, form a motif with letters:
                            // top-left -> 'A', top-right -> 'B', bottom-left -> 'C', bottom-right -> 'D'
                            string newCur = curRow;
                            string newNext = nRow;
                            newCur[j] = 'A';
                            newCur[j+1] = 'B';
                            newNext[j] = 'C';
                            newNext[j+1] = 'D';
                            arr[i] = newCur;
                            arr[i+1] = newNext;
                        }
                        else {
                            impossible = true;
                            break;
                        }
                    }
                    else {
                        impossible = true;
                        break;
                    }
                }
            }
        }
        out << "Case #" << (test + 1) << ":" << "\n";
        if (impossible) {
            out << "Cannot form motif" << "\n";
        } else {
            for (int i = 0; i < (int)arr.size(); i++) {
                out << arr[i] << "\n";
            }
        }
    }

    in.close();
    out.close();
    return 0;
}

