public class Main {
    static char[][] solve(char[][] pic) {
        int rows = pic.length;
        int cols = pic[0].length;
        for (int r = 0; r < rows - 1; r++) {
            for (int c = 0; c < cols - 1; c++) {
                if (pic[r][c] == '#' && pic[r][c+1] == '#' && pic[r+1][c] == '#' && pic[r+1][c+1] == '#') {
                    // Instead of drawing slashes, label each quadrant with distinct digits
                    pic[r  ][c  ] = '1';
                    pic[r  ][c+1] = '2';
                    pic[r+1][c  ] = '3';
                    pic[r+1][c+1] = '4';
                }
            }
        }
        int hasBlue = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (pic[r][c] == '#') hasBlue++;
            }
        }
        if (hasBlue > 0) {
            return null;
        } else {
            return pic;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int T = Integer.parseInt(line.trim());
        for (int t = 1; t <= T; t++) {
            String rcLine = br.readLine();
