            StringTokenizer st = new StringTokenizer(rcLine);
            int R = Integer.parseInt(st.nextToken());
            int C = Integer.parseInt(st.nextToken());
            char[][] pic = new char[R][];
            for (int i = 0; i < R; i++) {
                String row = br.readLine();
                if (row == null) row = "";
                pic[i] = row.trim().toCharArray();
                if (pic[i].length < C) {
                    // pad if necessary to preserve structure
                    char[] padded = new char[C];
                    for (int j = 0; j < C; j++) {
                        padded[j] = (j < pic[i].length) ? pic[i][j] : ' ';
                    }
                    pic[i] = padded;
                }
            }
            char[][] newpic = solve(pic);
            System.out.println("Case #" + t + ":");
            if (newpic == null) {
                System.out.println("Impossible");
            } else {
                for (int i = 0; i < newpic.length; i++) {
                    System.out.println(new String(newpic[i]));
                }
            }
        }
    }
