#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int IsRedPossible(char **board, int rows, int cols, int i, int j)
{
    if (i >= rows - 1 || j >= cols - 1)
        return 0;
    if (board[i][j] == '*' && board[i + 1][j] == '*' && board[i][j + 1] == '*' && board[i + 1][j + 1] == '*')
        return 1;
    return 0;
}

char *GetFirstRow(char *row, int j)
{
    char *nb = strdup(row);
    nb[j] = 'A';
    nb[j + 1] = 'B';
    return nb;
}

char *GetSecondRow(char *row, int j)
{
    char *nb = strdup(row);
    nb[j] = 'C';
    nb[j + 1] = 'D';
    return nb;
}

int main()
{
    int totalCases;
    if (scanf("%d", &totalCases) != 1) return 0;
    for (int cs = 1; cs <= totalCases; ++cs)
    {
        int r, c;
        scanf("%d %d", &r, &c);
        char **board = (char **)malloc(sizeof(char *) * r);
        for (int i = 0; i < r; ++i)
        {
            char buffer[1024];
            scanf("%s", buffer);
            board[i] = strdup(buffer);
        }

        for (int i = 0; i < r; ++i)
        {
            for (int j = 0; j < c; ++j)
            {
                if (board[i][j] == '*' && IsRedPossible(board, r, c, i, j))
                {
                    char *newFirst = GetFirstRow(board[i], j);
                    char *newSecond = GetSecondRow(board[i + 1], j);
                    free(board[i]);
                    free(board[i + 1]);
                    board[i] = newFirst;
                    board[i + 1] = newSecond;
                }
            }
        }

        int isGood = 1;
        for (int i = 0; i < r; ++i)
        {
            for (int j = 0; j < c; ++j)
            {
                if (board[i][j] == '*')
                    isGood = 0;
            }
        }

        printf("Case #%d:\n", cs);
        if (!isGood)
            printf("Unprocessed\n");
        else
        {
            for (int i = 0; i < r; ++i)
            {
                printf("%s\n", board[i]);
            }
        }

        for (int i = 0; i < r; ++i)
            free(board[i]);
        free(board);
    }
    return 0;
}

