public class Program {
    public static void main(String[] args) throws Exception {
        if (args.length != 1) {
            System.out.println("specify input file");
            return;
        }
        String path = args[0];
        try (BufferedWriter sw = new BufferedWriter(new FileWriter(path + ".out"))) {
            try (BufferedReader sr = new BufferedReader(new FileReader(path))) {
                int count = Integer.parseInt(sr.readLine());
                for (int i = 0; i < count; i++) {
                    sw.write(String.format("Case #%d:\n%s", i + 1, SolveTaskA(sr)));
                }
            }
        }
    }

    private static String SolveTaskA(BufferedReader sr) throws IOException {
        String input = sr.readLine();
        StringBuffer buffer = new StringBuffer(input);
        int r = buffer.ReadInt();
        int c = buffer.ReadInt();
        String[] str = new String[r];
        for (int i = 0; i < r; i++)
            str[i] = sr.readLine();
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (str[i].charAt(j) != 'B')
                    continue;
                if (IsBlue(str, i, j) && IsBlue(str, i + 1, j) && IsBlue(str, i, j + 1) && IsBlue(str, i + 1, j + 1)) {
                    str[i] = str[i].substring(0, j) + "[]" + str[i].substring(j + 2);
                    str[i + 1] = str[i + 1].substring(0, j) + "<>" + str[i + 1].substring(j + 2);
                }
            }
        }
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < r; i++) {
            if (str[i].indexOf('B') >= 0)
                return "Unsolvable\n";
            result.append(str[i]).append(System.lineSeparator());
        }
        return result.toString();
    }

    private static boolean IsBlue(String[] str, int r, int c) {
        if (r < 0 || r >= str.length)
            return false;
        if (c < 0 || c >= str[r].length())
            return false;
        return str[r].charAt(c) == 'B';
    }

    private static int CalculateLastMoveTime(int currentPosition, int targetButtonIndex, int lastMoveTime, int otherRobotLastMoveTime) {
        int minTime = Math.abs(currentPosition - targetButtonIndex) + 1;
        return Math.max(minTime + lastMoveTime, otherRobotLastMoveTime + 1);
    }
}

