public class Main {
    static char[][] m = new char[55][55];
    static BufferedReader br;
    static StringTokenizer st;

    static String next() throws IOException {
        while (st == null || !st.hasMoreElements()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    public static void main(String[] args) throws Exception {
        br = new BufferedReader(new InputStreamReader(System.in));
        st = new StringTokenizer("");
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int T, R, C, i, j, t;
        String tok = next();
        if (tok == null) return;
        T = Integer.parseInt(tok);
        for (t = 1; t <= T; t++) {
            R = Integer.parseInt(next());
            C = Integer.parseInt(next());
            String line;
            // consume rest of current line to align with grid reading
            line = br.readLine();
            for (i = 1; i <= R; i++) {
                line = br.readLine();
                while (line == null) line = br.readLine();
                while (line.length() < C) {
                    String more = br.readLine();
                    if (more == null) break;
                    line += more;
                }
                for (j = 1; j <= C; j++) {
                    m[i][j] = (j-1 < line.length()) ? line.charAt(j-1) : ' ';
                }
            }
            for (i = 1; i <= R; i++) {
                for (j = 1; j <= C; j++) {
                    if (m[i][j] == '#') {
                        m[i][j] = 'A';
                        if (i != R && m[i+1][j] == '#') m[i+1][j] = 'B';
                        else break;
                        if (j != C && m[i][j+1] == '#') m[i][j+1] = 'C';
                        else break;
                        if (i != R && j != C && m[i+1][j+1] == '#') m[i+1][j+1] = 'D';
                        else break;
                    }
                }
                if (j <= C) break;
            }
            out.printf("Case #%d:%n", t);
            if (i <= R) {
                out.printf("Corrupted%n");
            } else {
                for (i = 1; i <= R; i++) {
                    for (j = 1; j <= C; j++) {
                        out.print(m[i][j]);
                    }
                    out.print("\n");
                }
            }
        }
        out.flush();
    }
