#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char buf[1000][1000];

int range(int n, int m, int i, int j)
{
    return 0 <= i && i < n && 0 <= j && j < m;
}

int refill(int n, int m)
{
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (buf[i][j] == '#')
            {
                for (int di = 0; di <= 1; di++)
                    for (int dj = 0; dj <= 1; dj++)
                    {
                        if (!range(n, m, i + di, j + dj))
                            return 0;
                        if (buf[i + di][j + dj] != '#')
                            return 0;
                        /* Change functional purpose:
                           Instead of converting to slashes,
                           we mark each 2x2 found block with digits:
                           top-left '1', top-right '2', bottom-left '3', bottom-right '4'.
                           This preserves the same traversal and validation logic
                           but changes the produced output meaning. */
                        buf[i + di][j + dj] = '1' + (di * 2 + dj);
                    }
            }
    return 1;
}

int main()
{
    FILE *cin = fopen("input.txt", "r");
    FILE *cout = fopen("output.txt", "w");
    if (!cin || !cout)
    {
        return 1;
    }
    int t;
    if (fscanf(cin, "%d", &t) != 1)
    {
        fclose(cin);
        fclose(cout);
        return 1;
    }
    for (int aaa = 0; aaa < t; aaa++)
    {
        int n, m;
        fscanf(cin, "%d %d", &n, &m);
        for (int i = 0; i < n; i++)
            fscanf(cin, "%s", buf[i]);
        int res = refill(n, m);
        fprintf(cout, "Case #%d:", aaa + 1);
        fprintf(cout, "\n");
        if (!res)
        {
            fprintf(cout, "Impossible\n");
        }
        else
        {
            for (int i = 0; i < n; i++)
                fprintf(cout, "%s\n", buf[i]);
        }
    }
    fclose(cin);
    fclose(cout);
    return 0;
}

