import java.io.*;
import java.util.*;

public class Main {
    static void pout(ArrayList<ArrayList<Character>> panel) {
        for (int i = 0; i < panel.size(); i++) {
            for (int j = 0; j < panel.get(i).size(); j++) {
                System.out.print(panel.get(i).get(j));
            }
            System.out.println();
        }
    }

    static int countHashInRow(ArrayList<Character> row) {
        int cnt = 0;
        for (int k = 0; k < row.size(); k++) {
            if (row.get(k) == '#') cnt++;
        }
        return cnt;
    }

    static boolean trans(ArrayList<ArrayList<Character>> panel) {
        for (int i = 0; i < panel.size() - 1; i++) {
            if (countHashInRow(panel.get(i)) == 1) return false;
            for (int j = 0; j < panel.get(i).size() - 1; j++) {
                if (panel.get(i).get(j) == '#') {
                    if (panel.get(i).get(j + 1) != '#') return false;
                    if (panel.get(i + 1).get(j) != '#') return false;
                    if (panel.get(i + 1).get(j + 1) != '#') return false;
                    panel.get(i).set(j, 'A');
                    panel.get(i).set(j + 1, 'B');
                    panel.get(i + 1).set(j, 'C');
                    panel.get(i + 1).set(j + 1, 'D');
                }
            }
        }
        for (int i = 0; i < panel.size(); i++) {
            if (countHashInRow(panel.get(i)) > 0) return false;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int T = Integer.parseInt(line.trim());
        for (int t = 0; t < T; t++) {
            String[] data;
            while (true) {
                line = br.readLine();
                if (line != null && line.trim().length() > 0) {
                    data = line.trim().split("\\s+");
                    break;
                }
            }
            int R = Integer.parseInt(data[0]);
            int C = Integer.parseInt(data[1]);
            ArrayList<ArrayList<Character>> panel = new ArrayList<ArrayList<Character>>();
            for (int r = 0; r < R; r++) {
                panel.add(new ArrayList<Character>());
                String row;
                while (true) {
                    row = br.readLine();
                    if (row != null && row.length() >= C) break;
                }
                for (int c = 0; c < C; c++) {
                    panel.get(r).add(row.charAt(c));
                }
            }
            System.out.println("Scenario #" + (t + 1) + ":");
            if (trans(panel) == false) {
                System.out.println("Failed");
            } else {
                pout(panel);
            }
        }
    }
}

