using System;
class Program
{
    static string[] tokens;
    static int tpos = 0;

    static string NextToken()
    {
        return tokens[tpos++];
    }

    static void solve(int acase)
    {
        int N = int.Parse(NextToken());
        int M = int.Parse(NextToken());
        char[,] map = new char[100, 100];
        int[,] complete = new int[100, 100];
        for (int ii = 0; ii < 100; ++ii)
            for (int jj = 0; jj < 100; ++jj)
                complete[ii, jj] = 0;
        int i;
        for (i = 0; i < N; ++i)
        {
            string row = NextToken();
            for (int k = 0; k < M; ++k)
                map[i, k] = row[k];
        }
        bool ok = true;
        int j;
        for (i = 0; i < N; ++i)
            for (j = 0; j < M; ++j)
            {
                char up, cur;
                up = '.';
                if (i > 0) up = map[i - 1, j];
                cur = map[i, j];
                if (i > 0 && complete[i - 1, j] == 0)
                {
                    if (cur == '.')
                    {
                        ok = false;
                        goto bad;
                    }
                    if (up == '/')
                        map[i, j] = '\\';
                    else
                        map[i, j] = '/';
                    complete[i, j] = 1;
                }
                else if (cur == '#')
                {
                    if (j == 0 || map[i, j - 1] != '/' || complete[i, j - 1] == 1)
                    {
                        map[i, j] = '/';
                        if (j == M - 1)
                        {
                            ok = false;
                            goto bad;
                        }
                    }
                    else
                        map[i, j] = '\\';
                }
                else if (cur == '.' && j > 0 && map[i, j - 1] == '/' && complete[i, j - 1] == 0)
                {
                    ok = false;
                    goto bad;
                }
                else
                    complete[i, j] = 1;
                if (i == N - 1 && complete[i, j] == 0)
                {
                    ok = false;
                    goto bad;
                }
            }
    bad:
        Console.WriteLine("Case #{0}:", acase);
        if (ok)
        {
            // Different objective: report a simple analysis of the transformed grid.
            // Compute number of completed cells and count of slashes and backslashes.
            int sumComplete = 0;
            int countSlash = 0;
            int countBackslash = 0;
            for (i = 0; i < N; ++i)
            {
                for (j = 0; j < M; ++j)
                {
                    if (complete[i, j] != 0) sumComplete++;
                    if (map[i, j] == '/') countSlash++;
                    if (map[i, j] == '\\') countBackslash++;
                }
            }
            Console.WriteLine("Status: Possible");
            Console.WriteLine("CompletedCells: {0}", sumComplete);
            Console.WriteLine("ForwardSlashes: {0}", countSlash);
            Console.WriteLine("BackSlashes: {0}", countBackslash);
        }
        else
            Console.WriteLine("Impossible");
    }

