import sys
import os

def main():
    try:
        f_in = open("A.in", "r")
    except IOError:
        print("ERROR: no input file.")
        return 1
    f_out = open("A.out", "w+")

    i = j = k = 0
    n = 0
    cols = rows = 0
    error = 0
    ch = ''
    # grid as list of lists
    grid = [['' for _ in range(50)] for _ in range(50)]

    # read number of cases (skip initial blank lines)
    line = f_in.readline()
    while line is not None and line.strip() == "":
        line = f_in.readline()
        if line == "":
            break
    if not line:
        f_in.close()
        f_out.close()
        return 0
    try:
        n = int(line.strip())
    except:
        # fallback if the first token is elsewhere
        parts = line.split()
        if len(parts) > 0:
            n = int(parts[0])
        else:
            n = 0

    for i in range(n):
        f_out.write("Case #%d:\n" % (i+1))
        # read rows and cols (skip blank lines)
        line = f_in.readline()
        while line is not None and line.strip() == "":
            line = f_in.readline()
            if line == "":
                break
        if not line:
            break
        parts = line.split()
        # if parts don't contain both, keep reading
        while len(parts) < 2:
            extra = f_in.readline()
            if not extra:
                break
            extra = extra.strip()
            if extra == "":
                continue
            parts += extra.split()
        rows = int(parts[0])
        cols = int(parts[1])

        # prepare grid
        grid = [['' for _ in range(cols)] for _ in range(rows)]

        # read grid characters, skipping newline characters exactly like the C version
        for j in range(rows):
            for k in range(cols):
                ch = '\n'
                while ch == '\n':
                    ch = f_in.read(1)
                    if ch == '':
                        # EOF encountered, keep as newline to try again (mimic C behavior)
                        ch = '\n'
                        break
                grid[j][k] = ch

        error = 0
        label = 1  # used to label discovered 2x2 blocks (different objective)
        for j in range(rows):
            for k in range(cols):
                if grid[j][k] == '#':
                    if k == cols-1 or j == rows-1:
                        error = 1
                    else:
                        if grid[j+1][k] == '#' and grid[j][k+1] == '#' and grid[j+1][k+1] == '#':
                            # Instead of drawing slashes, label the 2x2 block with digits.
                            grid[j][k]     = str((label     ) % 10)
                            grid[j][k+1]   = str((label + 1 ) % 10)
                            grid[j+1][k]   = str((label + 2 ) % 10)
                            grid[j+1][k+1] = str((label + 3 ) % 10)
                            label += 4
                        else:
                            error = 1
                # else: do nothing (default)
                if error == 1:
                    break
            if error == 1:
                break

        if error == 1:
            f_out.write("Impossible\n")
        else:
            for j in range(rows):
                for k in range(cols):
                    f_out.write("%s" % grid[j][k])
                f_out.write("\n")

    f_in.close()
    f_out.close()
    return 0

if __name__ == "__main__":
    sys.exit(main())

