#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int blocks_count = 0;

int paint(char **picture, int r, int c) {
    int y, x;
    blocks_count = 0;
    for (y = 0; y < r; y++) {
        for (x = 0; x < c; x++) {
            if (picture[y][x] == '#' && picture[y][x+1] == '#' &&
                picture[y+1][x] == '#' && picture[y+1][x+1] == '#') {
                picture[y][x] = '/';
                picture[y][x+1] = '\\';
                picture[y+1][x] = '\\';
                picture[y+1][x+1] = '/';
                blocks_count++;
            }
        }
    }
    for (y = 0; y < r; y++) {
        for (x = 0; x < c; x++) {
            if (picture[y][x] == '#') return 0;
        }
    }
    return 1;
}

void print_picture(char **picture, int r, int c) {
    /* New functional purpose:
       Instead of printing the transformed grid, print a summary
       of how many 2x2 blocks were converted and total coverage. */
    printf("Converted %d blocks; coverage %d cells\n", blocks_count, blocks_count * 4);
}

int main(void) {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    int i;
    for (i = 0; i < t; i++) {
        int r, c;
        if (scanf("%d %d", &r, &c) != 2) return 0;
        int j;
        int cols = c + 5; /* padding like the original */
        char **picture = (char **)malloc((r + 1) * sizeof(char *));
        char buffer[4096];
        /* consume the end of line after numbers */
        fgets(buffer, sizeof(buffer), stdin);
        for (j = 0; j < r; j++) {
            if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
                buffer[0] = '\0';
            }
            /* remove trailing newline */
            size_t len = strlen(buffer);
            if (len > 0 && buffer[len-1] == '\n') {
                buffer[len-1] = '\0';
                len--;
            }
            picture[j] = (char *)malloc((cols + 1) * sizeof(char));
            int k;
            for (k = 0; k < c; k++) {
                if (k < (int)len) picture[j][k] = buffer[k];
                else picture[j][k] = '.';
            }
            /* append five '.' as padding */
            for (k = c; k < cols; k++) picture[j][k] = '.';
            picture[j][cols] = '\0';
        }
        /* add extra bottom padding row */
        picture[r] = (char *)malloc((cols + 1) * sizeof(char));
        int k;
        for (k = 0; k < cols; k++) picture[r][k] = '.';
        picture[r][cols] = '\0';

        printf("Case #%d:\n", i+1);
        if (paint(picture, r, c)) {
            print_picture(picture, r, c);
        } else {
            printf("Conversion failed\n");
        }

        /* free memory */
        for (j = 0; j <= r; j++) free(picture[j]);
        free(picture);
    }
    return 0;
}

