using namespace std;

struct Main {
    istream* in;
    ostream* out;
    static constexpr const char* problem = "A-large";
    static void asserT(bool e) {
        if (!e) {
            throw runtime_error("assertion failed");
        }
    }
    void solveOne() {
        int r, c;
        (*in) >> r >> c;
        vector<string> ar(r);
        for (int i = 0; i < r; i++) {
            (*in) >> ar[i];
            asserT((int)ar[i].length() == c);
        }
        int labelCount = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (ar[i][j] == '#') {
                    if (i == r - 1 || j == c - 1) {
                        (*out) << "Unlabelable" << '\n';
                        return;
                    }
                    if (ar[i][j + 1] == '#' && ar[i + 1][j] == '#' && ar[i + 1][j + 1] == '#') {
                        char topLeft = char('A' + (labelCount % 26));
                        char topRight = char('a' + (labelCount % 26));
                        char bottomLeft = char('0' + (labelCount % 10));
                        char bottomRight = char('9' - (labelCount % 10));
                        ar[i][j] = topLeft;
                        ar[i][j + 1] = topRight;
                        ar[i + 1][j] = bottomLeft;
                        ar[i + 1][j + 1] = bottomRight;
                        labelCount++;
                    } else {
                        (*out) << "Unlabelable" << '\n';
                        return;
                    }
                }
            }
        }
        for (int i = 0; i < r; i++) {
            for (char val : ar[i]) {
                (*out) << val;
            }
            (*out) << '\n';
        }
    }
    void solve() {
        int nTests;
        (*in) >> nTests;
        for (int i = 0; i < nTests; i++) {
            (*out) << "Case #" << (i+1) << ":" << '\n';
            solveOne();
        }
