#include <bits/stdc++.h>
using namespace std;

bool Replace(vector<string>& tiles)
{
    int R = tiles.size();
    int C = tiles[0].size();
    for (int i = 0; i < R; i++)
    {
        for (int j = 0; j < C; j++)
        {
            if (tiles[i][j] == '#')
            {
                if (i + 1 >= R) return false;
                if (j + 1 >= C) return false;
                if (tiles[i][j + 1] != '#') return false;
                if (tiles[i + 1][j] != '#') return false;
                if (tiles[i + 1][j + 1] != '#') return false;
                // New functional purpose:
                // instead of drawing slashes/backslashes, we stamp a 2x2 signature
                // using letters to mark transformed blocks.
                tiles[i][j] = 'A';
                tiles[i][j + 1] = 'B';
                tiles[i + 1][j] = 'C';
                tiles[i + 1][j + 1] = 'D';
            }
        }
    }
    return true;
}

int main(int argc, char** argv)
{
    string name = "../A-large";
    ifstream sr(name + ".in");
    ofstream sw(name + ".out");
    if (!sr.is_open() || !sw.is_open()) return 0;
    string line;
    getline(sr, line);
    int T = stoi(line);
    for (int i = 1; i <= T; i++)
    {
        getline(sr, line);
        while(line.size() == 0 && !sr.eof()) getline(sr, line);
        stringstream ss(line);
        int R, C;
        ss >> R >> C;
        vector<string> tiles(R);
        for (int j = 0; j < R; j++)
        {
            getline(sr, tiles[j]);
            if ((int)tiles[j].size() == 0 && j >= 0) { j--; continue; }
        }
        sw << "Case #" << i << ":" << "\n";
        if (Replace(tiles))
        {
            for (const auto& tile : tiles) sw << tile << "\n";
        }
        else sw << "Impossible" << "\n";
        cout << "Case #" << i << ": Done" << endl;
    }
    sw.close();
    sr.close();
    return 0;
}

