            String line = "";
            while (line.length() < C) {
                String l = br.readLine();
                if (l == null) l = "";
                line += l;
            }
            for (c = 0; c < C; c++) {
                M[r][c] = line.charAt(c);
            }
        }
        outer:
        for (r = 0; r < R; r++) {
            for (c = 0; c < C; c++) {
                if (M[r][c] != '#') continue;
                if (r == R - 1) {
                    System.out.printf("Scenario #%d:%nCannot renovate%n", n);
                    return;
                }
                if (c == C - 1) {
                    System.out.printf("Scenario #%d:%nCannot renovate%n", n);
                    return;
                }
                if (M[r][c] == '#') M[r][c] = 'R'; else {
                    System.out.printf("Scenario #%d:%nCannot renovate%n", n);
                    return;
                }
                if (M[r][c + 1] == '#') M[r][c + 1] = 'O'; else {
                    System.out.printf("Scenario #%d:%nCannot renovate%n", n);
                    return;
                }
                if (M[r + 1][c] == '#') M[r + 1][c] = 'O'; else {
                    System.out.printf("Scenario #%d:%nCannot renovate%n", n);
                    return;
                }
                if (M[r + 1][c + 1] == '#') M[r + 1][c + 1] = 'M'; else {
                    System.out.printf("Scenario #%d:%nCannot renovate%n", n);
                    return;
                }
            }
        }
        System.out.printf("Scenario #%d:%n", n);
        for (r = 0; r < R; r++) {
            for (c = 0; c < C; c++) {
                System.out.print(M[r][c]);
            }
            System.out.println();
        }
    }

