import java.io.*;
import java.util.*;

public class Main {
    static final int size = 100;
    static char[][] buf = new char[size][size];
    static int n, m;

    static void process() {
        int i, j;
        for (i = 0; i < n; i++)
            for (j = 0; j < m; j++)
                if (buf[i][j] == '*' && buf[i][j + 1] == '*' && buf[i + 1][j] == '*' && buf[i + 1][j + 1] == '*') {
                    // Instead of cutting tiles, we mark a 2x2 patch as a sensor block with letters
                    buf[i][j] = 'A';
                    buf[i][j + 1] = 'B';
                    buf[i + 1][j] = 'C';
                    buf[i + 1][j + 1] = 'D';
                }
    }

    static boolean check() {
        int i, j;
        for (i = 0; i < n; i++)
            for (j = 0; j < m; j++)
                if (buf[i][j] == '*')
                    return false;
        return true;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int tc;
        st = new StringTokenizer(br.readLine());
        tc = Integer.parseInt(st.nextToken());
        for (int t = 0; t < tc; t++) {
            st = new StringTokenizer(br.readLine());
            n = Integer.parseInt(st.nextToken());
            m = Integer.parseInt(st.nextToken());
            int i, j;
            for (i = 0; i < n; i++) {
                String line = br.readLine();
                for (j = 0; j < m; j++) {
                    buf[i][j] = line.charAt(j);
                }
            }
            for (i = 0; i <= n; i++)
                buf[i][m] = '@';
            for (i = 0; i <= m; i++)
                buf[n][i] = '@';
            process();
            System.out.println("Case #" + (t + 1) + ":");
            if (!check())
                System.out.println("Uncovered");
            else {
                // New objective: output the sensor-marked grid after coverage
                for (i = 0; i < n; i++) {
                    for (j = 0; j < m; j++)
                        System.out.print(buf[i][j]);
                    System.out.println();
                }
            }
        }
    }
}

