using System;
using System.IO;
using System.Collections.Generic;

class TestCase
{
    public int R;
    public int C;
    public char[][] picture;
    public TestCase(int r, int c, char[][] p) { R = r; C = c; picture = p; }
}

class Program
{
    static List<TestCase> readInput(string[] args)
    {
        var file = new StreamReader(args[0]);
        int testCaseCount = int.Parse(file.ReadLine());
        var testCases = new List<TestCase>();
        for (int x = 0; x < testCaseCount; x++)
        {
            string[] rc = file.ReadLine().Split();
            int R = int.Parse(rc[0]);
            int C = int.Parse(rc[1]);
            var picture = new char[R][];
            for (int i = 0; i < R; i++)
            {
                picture[i] = file.ReadLine().TrimEnd().ToCharArray();
            }
            testCases.Add(new TestCase(R, C, picture));
        }
        return testCases;
    }

    static List<string> solve(TestCase tc)
    {
        int R = tc.R;
        int C = tc.C;
        var picture = tc.picture;
        int converted = 0;
        for (int row = 0; row < R; row++)
        {
            for (int column = 0; column < C; column++)
            {
                if (picture[row][column] != '#')
                    continue;
                if (row == R - 1 || column == C - 1 || picture[row][column + 1] != '#' || picture[row + 1][column] != '#' || picture[row + 1][column + 1] != '#')
                    return new List<string> { "Impossible" };
                picture[row][column] = 'A';
                picture[row][column + 1] = 'B';
                picture[row + 1][column] = 'C';
                picture[row + 1][column + 1] = 'D';
                converted++;
            }
        }
        return new List<string> { "Converted blocks: " + converted.ToString() };
    }

    static void Main(string[] args)
    {
        var testCases = readInput(args);
        int testCaseNr = 1;
        foreach (var testCase in testCases)
        {
            var result = solve(testCase);
            Console.WriteLine("Case #{0}: \n{1}", testCaseNr, string.Join("\n", result));
            testCaseNr += 1;
        }
    }
}

