using System;
using System.IO;
using System.Globalization;

public class A {
    StreamReader br;
    string[] st;
    int stIdx = 0;
    StreamWriter outWriter;
    bool eof = false;
    Random rand = new Random(125475452);
    string FNAME = "A-large";

    public static void Main(string[] args) {
        new A().Run();
    }

    private void Run() {
        CultureInfo.DefaultThreadCurrentCulture = new CultureInfo("en-US");
        try {
            br = new StreamReader(FNAME + ".in");
            outWriter = new StreamWriter(FNAME + ".out");
            Solve();
            outWriter.Close();
        } catch (Exception e) {
            Console.WriteLine(e);
            Environment.Exit(566);
        }
    }

    string NextToken() {
        while (st == null || stIdx >= st.Length) {
            try {
                string line = br.ReadLine();
                if (line == null) {
                    eof = true;
                    return "0";
                }
                st = line.Split(new char[0], StringSplitOptions.RemoveEmptyEntries);
                stIdx = 0;
            } catch (Exception) {
                eof = true;
                return "0";
            }
        }
        return st[stIdx++];
    }

    int NextInt() {
        return int.Parse(NextToken());
    }

    double NextDouble() {
        return double.Parse(NextToken(), CultureInfo.InvariantCulture);
    }

    private void Solve() {
        int T = NextInt();
        for (int test = 1; test <= T; ++test) {
            int n = NextInt();
            int m = NextInt();
            char[][] c = new char[n][];
            for (int i = 0; i < n; ++i) {
                c[i] = NextToken().ToCharArray();
            }
            bool good = true;
            // The logic below identifies 2x2 blocks of '#' and replaces them.
            // Functional purpose changed: we now mark each valid 2x2 block with 'A','B','C','D'
            // keeping the same control flow and checks.
            goto startLoop;
        startLoop:;
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (c[i][j] == '#') {
                        if (i + 1 >= n || j + 1 >= m || c[i + 1][j] != '#' || c[i][j + 1] != '#' || c[i + 1][j + 1] != '#') {
                            good = false;
                            goto afterLoop;
                        } else {
                            c[i][j] = 'A';
                            c[i + 1][j] = 'B';
                            c[i][j + 1] = 'C';
                            c[i + 1][j + 1] = 'D';
                        }
                    }
                }
            }
        afterLoop:;
            outWriter.WriteLine("Case #" + test + ":");
            if (!good) {
                outWriter.WriteLine("Invalid configuration");
            } else {
                for (int i = 0; i < n; ++i) {
                    outWriter.WriteLine(new string(c[i]));
                }
            }
        }
    }
}

