#include <bits/stdc++.h>
using namespace std;

ifstream inf("in.txt");
ofstream ouf("out.txt");

void close_files(){
    // mimic original: just close streams
    inf.close();
    ouf.close();
}

void precount(){
    // placeholder to keep same structure
}

int printcounter = 0;

void printstr(const string &a){
    // not used in solver but kept to preserve structure
    printcounter += 1;
    ouf << "Case #" << printcounter << ": " << a << "\n";
}

void solvetest(){
    // keep same logic and control flow as original Python
    int r, c;
    inf >> r >> c;
    string tmp;
    getline(inf, tmp); // consume end of line

    vector<string> a;
    for(int i = 0; i < r; ++i){
        string line;
        getline(inf, line);
        // ensure line has at least c characters (mimic original reading)
        // no simplification: assume input is well-formed
        a.push_back(line);
    }

    int bad = 0;
    int replaceCount = 0;

    for(int i = 0; i < r; ++i){
        for(int j = 0; j < c; ++j){
            if(j < (int)a[i].size() && a[i][j] == '#'){
                if(i == r-1 || j == c-1){
                    bad = 1;
                    break;
                }
                // check corresponding 2x2 block
                // ensure indices valid for strings (mimic original exact checks)
                if( (j >= (int)a[i+1].size()) || (j+1 >= (int)a[i].size()) || (j+1 >= (int)a[i+1].size())
                    || a[i+1][j] != '#' || a[i][j+1] != '#' || a[i+1][j+1] != '#'){
                    bad = 1;
                    break;
                }
                // change purpose: mark found 2x2 '#' blocks by letters A,B,C,D
                a[i][j] = 'A';
                a[i+1][j] = 'B';
                a[i][j+1] = 'C';
                a[i+1][j+1] = 'D';
                replaceCount += 1;
            }
        }
        if(bad){
            break;
        }
    }

    printcounter += 1;
    ouf << "Case #" << printcounter << ":\n";

    if(bad){
        // different output message from original "Impossible"
        ouf << "Error\n";
    } else {
        // new functional purpose: output number of replacements, then the transformed grid
        ouf << replaceCount << "\n";
        for(int i = 0; i < r; ++i){
            string s = "";
            for(int j = 0; j < c; ++j){
                char ch = ' ';
                if(j < (int)a[i].size()) ch = a[i][j];
                else ch = ' ';
                s = s + ch;
            }
            ouf << s << "\n";
        }
    }
}

int main(){
    precount();
    int testnum = 0;
    if(!(inf >> testnum)){
        // no tests
        close_files();
        return 0;
    }
    string rest;
    getline(inf, rest); // consume end line after testnum
    for(int test = 0; test < testnum; ++test){
        solvetest();
    }
    close_files();
    return 0;
}

