#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
Mine Defusal Grid Transformer
Derived from original square tiles logic but repurposed:
- Detects 2x2 clusters of '#' (mines) and marks them as defused with a 2x2 pattern:
  D E
  F G
- If any '#' remain after processing, the case is reported as INCOMPLETE.
*/

int main(int argc, char **argv) {
    FILE *in_file;
    if (argc == 2 && strcmp(argv[1], "--help") != 0) {
        in_file = fopen(argv[1], "r");
        if (!in_file) {
            printf("Usage: mine_defusal.exe <input file>\n");
            return 0;
        }
    } else {
        printf("Usage: mine_defusal.exe <input file>\n");
        return 0;
    }

    int T;
    if (fscanf(in_file, "%d", &T) != 1) {
        fclose(in_file);
        return 0;
    }

    int cur_case;
    for (cur_case = 0; cur_case < T; cur_case++) {
        int R, C;
        if (fscanf(in_file, "%d %d", &R, &C) != 2) {
            break;
        }

        char **pic = (char **)malloc(sizeof(char *) * R);
        int i;
        for (i = 0; i < R; i++) {
            pic[i] = (char *)malloc(sizeof(char) * (C + 1));
            if (fscanf(in_file, "%s", pic[i]) != 1) {
                pic[i][0] = '\0';
            }
        }

        /* Begin processing: scan for 2x2 mine clusters and mark them as defused */
        int j;
        for (i = 0; i < R - 1; i++) {
            for (j = 0; j < C - 1; j++) {
                if (pic[i][j] == '#' && pic[i+1][j] == '#' && pic[i][j+1] == '#' && pic[i+1][j+1] == '#') {
                    pic[i][j]     = 'D';
                    pic[i+1][j]   = 'E';
                    pic[i][j+1]   = 'F';
                    pic[i+1][j+1] = 'G';
                }
            }
        }

        int is_possible = 1;
        for (i = 0; i < R; i++) {
            if (strchr(pic[i], '#') != NULL) {
                is_possible = 0;
                break;
            }
        }

        printf("Case #%d:\n", cur_case + 1);
        if (is_possible) {
            for (i = 0; i < R; i++) {
                printf("%s\n", pic[i]);
            }
        } else {
            printf("INCOMPLETE\n");
        }

        for (i = 0; i < R; i++) free(pic[i]);
        free(pic);
    }

    fclose(in_file);
    return 0;
}

