import sys
import traceback

PROBLEM = "A"
SIZE = "large"

class A:
    def __init__(self):
        self.reader = None
        self._tokens = []
        self._line = ''

    def next_token(self):
        while not self._tokens:
            line = self.reader.readline()
            if line == '':
                return ''
            self._tokens = line.strip().split()
        return self._tokens.pop(0)

    def next_int(self):
        return int(self.next_token())

    def solve(self):
        r = self.next_int()
        c = self.next_int()
        f = []
        for i in range(r):
            row = list(self.next_token())
            if len(row) != c:
                raise Exception("Invalid row length")
            f.append(row)
        for i in range(r):
            for j in range(c):
                if f[i][j] == '#':
                    if i < r - 1 and j < c - 1 and f[i][j + 1] == '#' and f[i + 1][j] == '#' and f[i + 1][j + 1] == '#':
                        # Instead of converting to slashes, label the 2x2 block with letters A/B pattern
                        f[i][j] = 'A'
                        f[i][j + 1] = 'B'
                        f[i + 1][j] = 'B'
                        f[i + 1][j + 1] = 'A'
                    else:
                        return "\nCannot label"
        sb = []
        for row in f:
            sb.append("\n")
            sb.append(''.join(row))
        return ''.join(sb)

    def run(self):
        self.reader = open(PROBLEM + "-" + SIZE + ".in", "r")
        writer = open(PROBLEM + "-" + SIZE + ".out", "w")
        try:
            n = self.next_int()
            for i in range(n):
                writer.write("Case #" + str(i + 1) + ":")
                writer.write(self.solve())
                writer.write("\n")
        finally:
            try:
                self.reader.close()
            except:
                pass
            try:
                writer.close()
            except:
                pass

if __name__ == "__main__":
    try:
        A().run()
    except Exception:
        traceback.print_exc()

