                        tiles[r][c + 1] = 'B';
                        tiles[r + 1][c] = 'C';
                        tiles[r + 1][c + 1] = 'D';
                    }
                    catch (Exception)
                    {
                        impossible = true;
                        break;
                    }
                }
            }
        }
        Console.WriteLine("Case #" + t + ":");
        if (impossible)
        {
            Console.WriteLine("Failed");
        }
        else
        {
            for (int i = 0; i < R; i++)
            {
                Console.WriteLine(new string(tiles[i]));
            }
        }
    }

