int main() {
    FILE *fr = fopen("input.txt", "r");
    FILE *fw = fopen("output.txt", "w");
    if (!fr || !fw) {
        return 1;
    }

    int T;
    if (fscanf(fr, "%d", &T) != 1) {
        fclose(fr);
        fclose(fw);
        return 1;
    }

    for (int caseNum = 1; caseNum <= T; caseNum++) {
        int R, C;
        fscanf(fr, "%d %d", &R, &C);
        char **data = (char **)malloc(R * sizeof(char *));
        for (int i = 0; i < R; i++) {
            data[i] = (char *)malloc((C + 1) * sizeof(char));
            fscanf(fr, "%s", data[i]);
        }

        bool ok = true;
        for (int i = 0; i < R && ok; i++) {
            for (int j = 0; j < C && ok; j++) {
                if (data[i][j] == 'T') {
                    if (i + 1 < R && j + 1 < C &&
                        data[i+1][j] == 'T' &&
                        data[i][j+1] == 'T' &&
                        data[i+1][j+1] == 'T') {
                        /* Transform a 2x2 block of trees 'T' into a small cabin pattern.
                           top-left -> 'C', top-right -> 'A'
                           bottom-left -> 'B', bottom-right -> 'D' */
                        data[i][j] = 'C';
                        data[i+1][j+1] = 'D';
                        data[i+1][j] = 'B';
                        data[i][j+1] = 'A';
                    } else {
                        ok = false;
                    }
                }
            }
        }

        fprintf(fw, "Case #%d:\n", caseNum);
        if (ok) {
            for (int i = 0; i < R; i++) {
                fprintf(fw, "%s\n", data[i]);
            }
        } else {
            fprintf(fw, "Cannot build cabins\n");
        }

        for (int i = 0; i < R; i++) free(data[i]);
        free(data);
    }

    fclose(fr);
    fclose(fw);
    return 0;
}

