import sys

class TestCaseDataRequired:
    def __init__(self):
        self.CaseNumber = 0
        self.Results = ""

class TestCaseData(TestCaseDataRequired):
    def __init__(self):
        super().__init__()
        self.y = 0
        self.x = 0
        self.grid = []

    @staticmethod
    def Read(input_file):
        results = TestCaseData()
        testLine = input_file.readline()
        # If empty line or EOF, propagate as-is (caller should handle)
        if not testLine:
            return results
        tokens = testLine.split()
        # preserve parsing behavior: expect two tokens
        results.y = int(tokens[0])
        results.x = int(tokens[1])
        for i in range(results.y):
            line = input_file.readline()
            # keep the line content as-is (strip only trailing newline)
            results.grid.append(line.rstrip('\n'))
        return results

    def AnalyzeLargestRegion(self):
        # Change of functional purpose:
        # Find the size of the largest connected region of '#' characters using DFS.
        if self.y <= 0 or self.x <= 0:
            self.Results = "0"
            return

        visited = [[False for _ in range(self.x)] for _ in range(self.y)]
        largest = 0

        for row in range(self.y):
            for col in range(self.x):
                if col >= len(self.grid[row]):
                    # If the input line is shorter than x, treat missing as empty
                    continue
                if visited[row][col]:
                    continue
                if self.grid[row][col] != '#':
                    visited[row][col] = True
                    continue

                # DFS stack
                stack = []
                stack.append((row, col))
                visited[row][col] = True
                size = 0

                while stack:
                    r, c = stack.pop()
                    size += 1

                    # check neighbors: up, down, left, right
                    # Up
                    nr = r - 1
                    nc = c
                    if nr >= 0 and nc >= 0 and nc < self.x:
                        if not visited[nr][nc]:
                            if nc < len(self.grid[nr]) and self.grid[nr][nc] == '#':
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                            else:
                                visited[nr][nc] = True

                    # Down
                    nr = r + 1
                    nc = c
                    if nr < self.y and nc >= 0 and nc < self.x:
                        if not visited[nr][nc]:
                            if nc < len(self.grid[nr]) and self.grid[nr][nc] == '#':
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                            else:
                                visited[nr][nc] = True

                    # Left
                    nr = r
                    nc = c - 1
                    if nr >= 0 and nr < self.y and nc >= 0:
                        if nc < self.x and not visited[nr][nc]:
                            if nc < len(self.grid[nr]) and self.grid[nr][nc] == '#':
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                            else:
                                visited[nr][nc] = True

                    # Right
                    nr = r
                    nc = c + 1
                    if nr >= 0 and nr < self.y and nc < self.x:
                        if nc >= 0 and not visited[nr][nc]:
                            if nc < len(self.grid[nr]) and self.grid[nr][nc] == '#':
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                            else:
                                visited[nr][nc] = True

                if size > largest:
                    largest = size

        self.Results = str(largest)

if __name__ == "__main__":
    data = sys.stdin.readline()
    if not data:
        sys.exit(0)
    try:
        T = int(data.split()[0])
    except:
        T = 0

    for case_num in range(1, T + 1):
        tc = TestCaseData.Read(sys.stdin)
        tc.CaseNumber = case_num
        tc.AnalyzeLargestRegion()
        print(f"Case #{tc.CaseNumber}: {tc.Results}")

