                for (int i = 0; i < N; ++i) {
                    s[i] = br.readLine();
                    if (s[i].length() != N)
                        throw new RuntimeException("Line length mismatch at case " + caseNumber + " line " + i);
                }
                int[] Games = new int[N];
                int[] Wins = new int[N];
                for (int i = 0; i < N; ++i) {
                    for (int j = 0; j < N; ++j)
                        if (s[i].charAt(j) != '.') {
                            Games[i]++;
                            if (s[i].charAt(j) == '1')
                                Wins[i]++;
                        }
                }
                double[] OWP = new double[N];
                for (int i = 0; i < N; ++i) {
                    for (int j = 0; j < N; ++j)
                        if (s[i].charAt(j) != '.') {
                            int opWinds = Wins[j];
                            if (s[i].charAt(j) == '0')
                                opWinds--;
                            OWP[i] += (((double) opWinds) / (Games[j] - 1));
                        }
                    OWP[i] /= Games[i];
                }
                double[] OOWP = new double[N];
                for (int i = 0; i < N; ++i) {
