                        if (s[i].charAt(j) != '.')
                            OOWP[i] += OWP[j];
                    OOWP[i] /= Games[i];
                }
                // Different functional purpose: interpret computed metrics as influence scores
                sw.write("Simulation #" + caseNumber + " - Influence Metrics:");
                sw.newLine();
                for (int i = 0; i < N; ++i) {
