            foreach (var t in toks) parts.Add(t);
        }
        _stok = new Queue<string>(parts);
        return _string;
    }
    static string nextTok() { return _stok.Dequeue(); }
    static int nextInt() { return int.Parse(nextTok()); }
    static long nextLong() { return long.Parse(nextTok()); }
