    public static void Main(string[] args) {
        nextLine();
        int Cases = nextInt();
        for (int Case = 0; Case < Cases; Case++) {
            nextLine();
            int R = nextInt();
            int C = nextInt();
            char[][] tiles = new char[R][];
            for (int i = 0; i < R; i++) {
                tiles[i] = new char[C];
            }
            for (int i = 0; i < R; i++) {
                string s = nextLine();
                for (int j = 0; j < C; j++) {
                    tiles[i][j] = s[j];
                }
            }
            bool ok = true;
            List<Tuple<int,int>> patches = new List<Tuple<int,int>>();
            int patchCount = 0;
            for (int i = 0; i < R && ok; i++) {
                for (int j = 0; j < C && ok; j++) {
                    if (tiles[i][j] == '#') {
                        tiles[i][j] = '/';
                        if (j+1 < C && tiles[i][j+1] == '#') {
                            tiles[i][j+1] = '\\';
                        } else {
                            ok = false;
                            break;
                        }
                        if (i+1 < R && tiles[i+1][j] == '#') {
                            tiles[i+1][j] = '\\';
                        } else {
                            ok = false;
                            break;
                        }
                        if (i+1 < R && j+1 < C && tiles[i+1][j+1] == '#') {
                            tiles[i+1][j+1] = '/';
                        } else {
