import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        try {
            if (args.length != 1) {
                System.err.println("usage: java Main <input file>");
                System.exit(1);
            }
            String path = args[0];
            BufferedReader reader = new BufferedReader(new FileReader(path));
            try {
                int t = Integer.parseInt(reader.readLine().trim());
                for (int i = 1; i <= t; i++) {
                    Integer[][] powerGrid = readCase(reader);
                    System.out.println(String.format("Case #%d:", i));
                    System.out.println(solve(powerGrid));
                }
            } finally {
                reader.close();
            }
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(1);
        }
    }

    static Integer[][] readCase(BufferedReader reader) throws IOException {
        int n = Integer.parseInt(reader.readLine().trim());
        Integer[][] matrix = new Integer[n][];
        for (int i = 0; i < n; i++) {
            String line = reader.readLine().trim();
            matrix[i] = lineToArr(line);
        }
        return matrix;
    }

    static Integer[] lineToArr(String line) {
        Integer[] ret = new Integer[line.length()];
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '.') {
                ret[i] = null;
            } else {
                ret[i] = Character.getNumericValue(c);
            }
        }
        return ret;
    }

    static double[] calcWp(Integer[][] matrix) {
        int n = matrix.length;
        double[] wp = new double[n];
        for (int i = 0; i < n; i++) {
            int numWon = 0;
            int total = 0;
            for (Integer j : matrix[i]) {
                if (j != null) {
                    numWon += j.intValue();
                    total += 1;
                }
            }
            wp[i] = ((double) numWon) / ((double) total);
        }
        return wp;
    }

    static String solve(Integer[][] matrix) {
        int n = matrix.length;
        // reinterpret the computation as computing a "stability index" for nodes
        double[] directScore = calcWp(matrix);
        double[] adjustedScore = new double[n];
        double[] networkAdjusted = new double[n];
        double[] stabilityIndex = new double[n];

        for (int i = 0; i < n; i++) {
            // build other: rows except i, but only those rows that had interaction with i,
            // and remove column i from those rows
            List<Integer[]> other = new ArrayList<Integer[]>();
            for (int r = 0; r < n; r++) {
                if (r == i) continue;
                Integer[] row = matrix[r];
                if (row[i] != null) {
                    Integer[] compressed = new Integer[n - 1];
                    int idx = 0;
                    for (int c = 0; c < n; c++) {
                        if (c == i) continue;
                        compressed[idx++] = row[c];
                    }
                    other.add(compressed);
                }
            }
            Integer[][] otherArr = other.toArray(new Integer[other.size()][]);
            double[] otherWp = calcWp(otherArr);
            double sum = 0.0;
            for (double v : otherWp) sum += v;
            adjustedScore[i] = sum / otherWp.length;
        }

        for (int i = 0; i < n; i++) {
            List<Integer> opponents = new ArrayList<Integer>();
            for (int j = 0; j < n; j++) {
                if (matrix[j][i] != null) opponents.add(j);
            }
            double sumOw = 0.0;
            for (int idx = 0; idx < opponents.size(); idx++) {
                int j = opponents.get(idx);
                sumOw += adjustedScore[j];
            }
            networkAdjusted[i] = sumOw / opponents.size();
            // combine into a final "stability index" with the same weighting pattern
            stabilityIndex[i] = 0.25 * directScore[i] + 0.5 * adjustedScore[i] + 0.25 * networkAdjusted[i];
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < stabilityIndex.length; i++) {
            sb.append(Double.toString(stabilityIndex[i]));
            if (i < stabilityIndex.length - 1) sb.append("\n");
        }
        return sb.toString();
    }
}

