import java.io.*;
import java.util.*;

public class Program {
    public static void main(String[] args) {
        String inFile = "";
        String outFile = "";
        for (int i = 0; i < args.length; i++) {
            switch (args[i]) {
                case "-i":
                    inFile = args[++i];
                    break;
                case "-o":
                    outFile = args[++i];
                    break;
            }
        }
        if (!inFile.isEmpty() && !outFile.isEmpty()) {
            try (BufferedReader reader = new BufferedReader(new FileReader(inFile));
                 BufferedWriter writer = new BufferedWriter(new FileWriter(outFile))) {
                Program p = new Program();
                p.Run(reader, writer);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void Run(BufferedReader reader, BufferedWriter writer) throws IOException {
        long start = System.nanoTime();
        int caseCount = Integer.parseInt(reader.readLine());
        for (int i = 1; i <= caseCount; i++) {
            List<Double> answer = RunCase(reader);
            writer.write("Network #" + i + ":");
            writer.newLine();
            for (double d : answer) {
                writer.write("InfluenceScore: " + d);
                writer.newLine();
            }
        }
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;
        System.out.println(String.format("%,dms", elapsedMs));
    }

    private List<Double> RunCase(BufferedReader reader) throws IOException {
        int count = Integer.parseInt(reader.readLine());
        double[][] wpa = new double[count][count];
        double[] owpa = new double[count];
        for (int i = 0; i < count; i++) {
            String line = reader.readLine();
            int win = 0;
            int played = 0;
            for (char c : line.toCharArray()) {
                if (c == '0')
                    played++;
                else if (c == '1') {
                    played++;
                    win++;
                }
            }
            double wp = (double) win / played;
            double owpWin = (double) (win - 1) / (played - 1);
            double owpLos = (double) win / (played - 1);
            for (int j = 0; j < count; j++) {
                if (i == j)
                    wpa[i][j] = wp;
                else if (line.charAt(j) == '1')
                    wpa[i][j] = owpWin;
                else if (line.charAt(j) == '0')
                    wpa[i][j] = owpLos;
                else
                    wpa[i][j] = -1;
            }
        }
        for (int j = 0; j < count; j++) {
            double total = 0d;
            int cnt = 0;
            for (int k = 0; k < count; k++) {
                if (j == k) continue;
                double owp = wpa[k][j];
                if (owp != -1) {
                    total += owp;
                    cnt++;
                }
            }
            owpa[j] = total / cnt;
        }
        List<Double> result = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            double owpTotal = 0d;
            int owpCount = 0;
            for (int j = 0; j < count; j++) {
                if (i == j) continue;
                if (wpa[i][j] == -1d) continue;
                owpTotal += owpa[j];
                owpCount++;
            }
            double oowp = owpTotal / owpCount;
            // The numeric formula is preserved but the purpose is changed:
            // now it represents a derived "influence" metric in a network
            result.add(0.25 * wpa[i][i] + 0.5 * owpa[i] + 0.25 * oowp);
        }
        return result;
    }
}

