#include <stdio.h>
#include <stdlib.h>
#include <string.h>

double WP(int **a, int n, int i) {
    int c = 0;
    int s = 0;
    int j;
    for (j = 0; j < n; j++) {
        if (a[i][j] != -1) {
            c += 1;
            if (a[i][j] == 1) s += 1;
        }
    }
    if (c == 0) return 0.0;
    return (double)s / (double)c;
}

double OWP(int **a, int n, int i) {
    int cc = 0;
    double ss = 0.0;
    int j, k;
    for (j = 0; j < n; j++) {
        if (a[i][j] != -1) {
            int c = 0;
            int s = 0;
            for (k = 0; k < n; k++) {
                if (a[j][k] != -1 && k != i) {
                    c += 1;
                    if (a[j][k] == 1) s += 1;
                }
            }
            if (c == 0) {
                ss += 0.0;
            } else {
                ss += (double)s / (double)c;
            }
            cc += 1;
        }
    }
    if (cc == 0) return 0.0;
    return ss / (double)cc;
}

double RPI(int **a, int n, int i) {
    double res = 0.25 * WP(a, n, i) + 0.5 * OWP(a, n, i);
    double oowp = 0.0;
    int c_oowp = 0;
    int j;
    for (j = 0; j < n; j++) {
        if (a[i][j] != -1) {
            c_oowp += 1;
            oowp += OWP(a, n, j);
        }
    }
    if (c_oowp == 0) return res;
    return res + 0.25 * (oowp / (double)c_oowp);
}

