import java.io.*;
import java.util.*;

public class Main {
    static class streamreader {
        private BufferedReader br;
        private StringTokenizer st;
        public streamreader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }
        private String next() throws IOException {
            while (!st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        public String nextString() throws IOException {
            return next();
        }
    }

    static char[] split(String s) {
        return s.toCharArray();
    }

    static void pr(ArrayList<char[]> x, int n) {
        for (int i = 1; i <= n; i++) {
            char[] line = x.get(i);
            System.out.println(new String(line, 1, line.length - 2));
        }
    }

    public static void main(String[] args) throws Exception {
        streamreader sr = new streamreader(System.in);
        int T = sr.nextInt();
        for (int tc = 0; tc < T; tc++) {
            int n = sr.nextInt();
            int m = sr.nextInt();
            ArrayList<char[]> x = new ArrayList<char[]>();
            // top padding: '.' * (m+2)
            StringBuilder topb = new StringBuilder();
            for (int k = 0; k < m + 2; k++) topb.append('.');
            x.add(split(topb.toString()));
            for (int i = 0; i < n; i++) {
                String s = sr.nextString();
                StringBuilder sb = new StringBuilder();
                sb.append('.');
                sb.append(s);
                sb.append('.');
                x.add(split(sb.toString()));
            }
            x.add(x.get(0));

            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (x.get(i)[j] == '#') {
                        if (x.get(i-1)[j] != '#' && x.get(i)[j-1] != '#') {
                            if (x.get(i+1)[j] == '#' && x.get(i)[j+1] == '#' && x.get(i+1)[j+1] == '#') {
                                // Instead of transforming into slashes, mark the 2x2 block with distinct letters.
                                x.get(i)[j] = 'A';
                                x.get(i+1)[j] = 'B';
                                x.get(i)[j+1] = 'C';
                                x.get(i+1)[j+1] = 'D';
                            }
                        }
                    }
                }
            }

            boolean possible = true;
            for (char[] line : x) {
                String joined = new String(line);
                if (joined.indexOf('#') >= 0) {
                    possible = false;
                    break;
                }
            }
            System.out.println("Case #" + (tc + 1) + ":");
            if (possible) {
                pr(x, n);
            } else {
                System.out.println("Impossible");
            }
        }
    }
}

