import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;
    static String next() throws IOException {
        while (st == null || !st.hasMoreElements()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    static void solve() throws IOException {
        int n;
        n = nextInt();
        int[] cnt = new int[110];
        char[][] t = new char[110][110];
        for (int i = 0; i < n; i++) {
            String s = next();
            for (int j = 0; j < s.length(); j++) t[i][j] = s.charAt(j);
        }
        double[] wp = new double[110];
        double[] owp = new double[110];
        double[] oowp = new double[110];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) if (t[i][j] != 0 && t[i][j] != '.') {
                cnt[i]++;
                if (t[i][j] == '1') wp[i] += 1.0;
            }
            if (cnt[i] != 0) wp[i] /= cnt[i];
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) if (t[i][j] != 0 && t[i][j] != '.') {
                int tmp_cnt = 0;
                double tmp_wp = 0.0;
                for (int k = 0; k < n; k++) if (k != i && t[j][k] != 0 && t[j][k] != '.') {
                    tmp_cnt++;
                    if (t[j][k] == '1') tmp_wp += 1.0;
                }
                if (tmp_cnt != 0) tmp_wp /= tmp_cnt;
                owp[i] += tmp_wp;
            }
            if (cnt[i] != 0) owp[i] /= cnt[i];
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) if (t[i][j] != 0 && t[i][j] != '.') {
                oowp[i] += owp[j];
            }
            if (cnt[i] != 0) oowp[i] /= cnt[i];
        }
        for (int i = 0; i < n; i++) {
            double score = wp[i] / 4.0 + owp[i] / 2.0 + oowp[i] / 4.0;
            // Changed functional purpose: classify each row as ADVANTAGE or DISADVANTAGE
            if (score >= 0.5) {
                System.out.println("ADVANTAGE");
            } else {
                System.out.println("DISADVANTAGE");
            }
        }
    }

    public static void main(String[] args) throws Exception {
        int t = nextInt();
        for (int tt = 1; tt <= t; tt++) {
            System.out.println("Case #" + tt + ":");
            solve();
            System.out.flush();
        }
    }
}

