import sys

def main():
    import sys
    eps = 1e-8
    inf = 10**9
    A = [['']*110 for _ in range(110)]
    B = [[0.0,0.0,0.0] for _ in range(110)]
    G = [0.0]*110
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    for cnt in range(1, t+1):
        # mimic debug print from original
        print(cnt, file=sys.stderr)
        n = int(next(it))
        # reset arrays
        for i in range(110):
            for j in range(110):
                A[i][j] = '.'
        for i in range(110):
            B[i][0] = 0.0
            B[i][1] = 0.0
            B[i][2] = 0.0
            G[i] = 0.0
        # read grid rows
        for i in range(n):
            s = next(it)
            # store into A row
            for j,ch in enumerate(s):
                A[i][j] = ch
            # fill remaining with '.'
            for j in range(len(s), n):
                A[i][j] = '.'
        # first pass: count non-dots and '1's
        for i in range(n):
            for j in range(n):
                if A[i][j] != '.':
                    G[i] += 1.0
                    if A[i][j] == '1':
                        B[i][0] += 1.0
        # second pass: compute B[i][1]
        for i in range(n):
            for j in range(n):
                if A[i][j] != '.':
                    denom = (G[j] - 1.0)
                    numerator = (B[j][0] - (1.0 if A[j][i] == '1' else 0.0))
                    if abs(denom) < eps:
                        term = float('inf')
                    else:
                        term = numerator / denom
                    B[i][1] += term
        # third pass: compute B[i][2]
        for i in range(n):
            for j in range(n):
                if A[i][j] != '.':
                    if abs(G[j]) < eps:
                        term2 = float('inf')
                    else:
                        term2 = B[j][1] / G[j]
                    B[i][2] += term2
        # New functional purpose:
        # Instead of printing numeric score, categorize each node into labels based on computed score.
        # Labels: "Strong" (>0.75), "Moderate" (>0.5), "Weak" (>0.25), "VeryWeak" (else). Inf -> "Strongest"
        sys.stdout.write(f"Case #{cnt}:\n")
        for i in range(n):
            if abs(G[i]) < eps:
                val = float('inf')
            else:
                val = (B[i][0]/4.0 + B[i][1]/2.0 + B[i][2]/4.0) / G[i]
            if val == float('inf'):
                label = "Strongest"
            elif val > 0.75:
                label = "Strong"
            elif val > 0.5:
                label = "Moderate"
            elif val > 0.25:
                label = "Weak"
            else:
                label = "VeryWeak"
            sys.stdout.write(label + "\n")

if __name__ == "__main__":
    main()

