#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

int **allocate_matrix_int(int R, int C) {
    int **m = (int**)malloc(R * sizeof(int*));
    for (int i = 0; i < R; i++) {
        m[i] = (int*)malloc(C * sizeof(int));
        for (int j = 0; j < C; j++) m[i][j] = 0;
    }
    return m;
}

void free_matrix_int(int **m, int R) {
    if (!m) return;
    for (int i = 0; i < R; i++) free(m[i]);
    free(m);
}

int **getSolMatrix(int **tiles, int R, int C, bool *ok) {
    int **solution = allocate_matrix_int(R, C);
    // 1 : A
    // 2 : B
    for (int j = 0; j < R; j++) {
        for (int k = 0; k < C; k++) {
            if (tiles[j][k] == 1) {
                if (j == R-1 || k == C-1) {
                    free_matrix_int(solution, R);
                    *ok = false;
                    return NULL;
                } else if (tiles[j][k+1] == 0 || tiles[j][k+1] == 2 ||
                           tiles[j+1][k] == 0 || tiles[j+1][k] == 2 ||
                           tiles[j+1][k+1] == 0 || tiles[j+1][k+1] == 2) {
                    free_matrix_int(solution, R);
                    *ok = false;
                    return NULL;
                } else {
                    tiles[j][k] = 2;
                    tiles[j+1][k] = 2;
                    tiles[j][k+1] = 2;
                    tiles[j+1][k+1] = 2;
                    solution[j][k] = 1;
                    solution[j+1][k] = 2;
                    solution[j][k+1] = 2;
                    solution[j+1][k+1] = 1;
                }
            }
        }
    }
    *ok = true;
    return solution;
}

int main() {
    int numCases;
    if (scanf("%d", &numCases) != 1) return 0;
    for (int i = 0; i < numCases; i++) {
        int R, C;
        if (scanf("%d %d", &R, &C) != 2) return 0;
        // consume end of line
        char linebuf[2005];
        fgets(linebuf, sizeof(linebuf), stdin);
        int **tiles = allocate_matrix_int(R, C);
        for (int j = 0; j < R; j++) {
            if (!fgets(linebuf, sizeof(linebuf), stdin)) linebuf[0] = '\0';
            for (int k = 0; k < C; k++) {
                if (linebuf[k] == '#') tiles[j][k] = 1;
                else tiles[j][k] = 0;
            }
        }
        bool valid = false;
        int **solution = getSolMatrix(tiles, R, C, &valid);
        printf("Case #%d:\n", i+1);
        if (!valid) {
            printf("Transformation Failed\n");
        } else {
            for (int j = 0; j < R; j++) {
                for (int k = 0; k < C; k++) {
                    if (solution[j][k] == 0) putchar('.');
                    else if (solution[j][k] == 1) putchar('A');
                    else if (solution[j][k] == 2) putchar('B');
                }
                putchar('\n');
            }
        }
        free_matrix_int(tiles, R);
        free_matrix_int(solution, R);
    }
    return 0;
}

