#include <bits/stdc++.h>
using namespace std;

vector<int> line_tostr(const string &line) {
    vector<int> ret;
    for (char c : line) {
        if (c == '.') {
            ret.push_back(-1);
        } else {
            ret.push_back(c - '0');
        }
    }
    return ret;
}

vector<vector<int>> read_case(istream &in) {
    string line;
    if (!getline(in, line)) return {};
    int n = stoi(line);
    vector<vector<int>> mat;
    for (int i = 0; i < n; ++i) {
        getline(in, line);
        // trim possible trailing carriage return
        if (!line.empty() && line.back() == '\r') line.pop_back();
        mat.push_back(line_tostr(line));
    }
    return mat;
}

vector<double> calc_wp(const vector<vector<int>> &matrix) {
    int n = (int)matrix.size();
    vector<double> wp(n, 0.0);
    for (int i = 0; i < n; ++i) {
        int num_won = 0;
        int total = 0;
        for (int j : matrix[i]) {
            if (j != -1) {
                num_won += j;
                total += 1;
            }
        }
        wp[i] = double(num_won) / double(total);
    }
    return wp;
}

string solve(const vector<vector<int>> &case_matrix) {
    vector<vector<int>> matrix = case_matrix;
    vector<double> wp = calc_wp(matrix);
    int n = (int)matrix.size();
    vector<double> owp(n, 0.0);
    vector<double> oowp(n, 0.0);
    vector<double> rpi(n, 0.0);

    for (int i = 0; i < n; ++i) {
        vector<vector<int>> other;
        for (int r = 0; r < n; ++r) {
            if (r == i) continue;
            if (matrix[r][i] != -1) {
                vector<int> row;
                for (int c = 0; c < n; ++c) {
                    if (c == i) continue;
                    row.push_back(matrix[r][c]);
                }
                other.push_back(row);
            }
        }
        vector<double> other_wp = calc_wp(other);
        double sum_other_wp = 0.0;
        for (double v : other_wp) sum_other_wp += v;
        owp[i] = double(sum_other_wp) / double(other_wp.size());
    }

    for (int i = 0; i < n; ++i) {
        vector<int> opponents;
        for (int j = 0; j < n; ++j) {
            if (matrix[j][i] != -1) opponents.push_back(j);
        }
        double sum_owp = 0.0;
        for (int j : opponents) sum_owp += owp[j];
        oowp[i] = double(sum_owp) / double(opponents.size());
        rpi[i] = 0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i];
    }

    // Changed functional purpose:
    // Instead of printing the RPI values, produce a ranking order (1-based indices)
    // sorted descending by the computed rpi score.
    vector<pair<double,int>> order;
    for (int i = 0; i < n; ++i) order.emplace_back(rpi[i], i + 1);
    sort(order.begin(), order.end(), [](const pair<double,int> &a, const pair<double,int> &b){
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    stringstream ss;
    for (size_t i = 0; i < order.size(); ++i) {
        if (i) ss << " ";
        ss << order[i].second;
    }
    return ss.str();
}

int main(int argc, char **argv) {
    if (argc != 2) {
        cerr << "usage: " << argv[0] << " <input file>" << endl;
        return 1;
    }
    ifstream infile(argv[1]);
    if (!infile) {
        cerr << "failed to open input file" << endl;
        return 1;
    }
    string line;
    if (!getline(infile, line)) return 0;
    int T = stoi(line);
    for (int i = 1; i <= T; ++i) {
        vector<vector<int>> c = read_case(infile);
        cout << "Case #" << i << ":" << endl;
        cout << solve(c) << endl;
    }
    return 0;
}

