import sys

def solve(test):
    line = sys.stdin.readline()
    if not line:
        return
    n = int(line.strip())
    s = []
    for i in range(n):
        row = sys.stdin.readline()
        if row is None:
            row = ''
        row = row.rstrip('\n')
        s.append(row)
    w = [0] * 110
    l = [0] * 110
    owp = [0.0] * 110
    wp = [0.0] * 110
    oowp = [0.0] * 110

    for i in range(n):
        w[i] = 0
        l[i] = 0
    for i in range(n):
        for j in range(n):
            if j < len(s[i]) and s[i][j] == '1':
                w[i] += 1
            else:
                if j < len(s[i]) and s[i][j] == '0':
                    l[i] += 1
    for i in range(n):
        wp[i] = float(w[i]) / float(w[i] + l[i])
    for i in range(n):
        owp[i] = 0.0
        op = 0.0
        for j in range(n):
            if j < len(s[i]) and s[i][j] != '.':
                # replicate original char-arithmetic logic:
                # numerator = w[j] - (s[j][i] - '0')
                # we interpret s[j][i] as character '0' or '1'
                ch = '.'
                if i < len(s[j]):
                    ch = s[j][i]
                if ch == '1':
                    sub = 1
                else:
                    sub = 0
                numerator = float(w[j] - sub)
                denominator = float(w[j] + l[j] - 1)
                owp[i] += numerator / denominator
                op += 1.0
        owp[i] /= op
    for i in range(n):
        oowp[i] = 0.0
        op = 0.0
        for j in range(n):
            if j < len(s[i]) and s[i][j] != '.':
                oowp[i] += owp[j]
