        while (idx < lines.Length && caseNum <= totalCases)
        {
            string line = lines[idx++].Trim();
            if (line == "")
            {
                continue;
            }
            int n = int.Parse(line);
            List<string> tab = new List<string>();
            List<double[]> l = new List<double[]>();
            double[] wp = new double[n];
            double[] owp = new double[n];
            double[] oowp = new double[n];

            for (int x = 0; x < n; x++)
            {
                string row = lines[idx++].Trim();
                tab.Add(row);
                l.Add(new double[3] { 0.0, 0.0, 0.0 });
                foreach (char c in row)
                {
                    if (c == '1')
                    {
                        l[x][0] += 1.0;
                        l[x][1] += 1.0;
                    }
                    if (c == '0')
                    {
                        l[x][0] += 1.0;
                        l[x][2] += 1.0;
                    }
                }
                wp[x] = l[x][1] / l[x][0];
            }

            for (int x = 0; x < n; x++)
            {
                double total = 0.0;
                int div = 0;
                for (int y = 0; y < n; y++)
                {
                    if (tab[x][y] == '.' || x == y)
                        continue;
