                }
                owp[x] = total / div;
            }

            for (int x = 0; x < n; x++)
            {
                double total = 0.0;
                int div = 0;
                for (int y = 0; y < n; y++)
                {
                    if (tab[x][y] == '.' || x == y)
                        continue;
                    div += 1;
                    total += owp[y];
                }
                oowp[x] = total / div;
            }

            // New functional purpose:
