import java.io.*;
import java.util.*;

public class Main {
    static class TokenIterator {
        private ArrayList<String> tokens = new ArrayList<String>();
        private int idx = 0;

        TokenIterator(String filename) throws Exception {
            BufferedReader br = new BufferedReader(new FileReader(filename));
            String line;
            while ((line = br.readLine()) != null) {
                StringTokenizer st = new StringTokenizer(line);
                while (st.hasMoreTokens()) {
                    String token = st.nextToken();
                    if (!token.equals("")) {
                        tokens.add(token);
                    }
                }
            }
            br.close();
        }

        public String next() {
            return tokens.get(idx++);
        }
    }

    public static void main(String[] args) throws Exception {
        String inputFilename = "A-large.in";
        String outputFilename = "A-large.txt";
        TokenIterator tokenIterator = new TokenIterator(inputFilename);

        class Util {
            String get() { return tokenIterator.next(); }
            int getint() { return Integer.parseInt(get()); }
        }
        Util util = new Util();

        BufferedWriter outputFile = new BufferedWriter(new FileWriter(outputFilename));
        int caseNum = util.getint();
        for (int caseIndex = 0; caseIndex < caseNum; caseIndex++) {
            int n = util.getint();
            ArrayList<String> x = new ArrayList<String>();
            int[] wins = new int[n];
            int[] losses = new int[n];
            double[] wp = new double[n];
            double[] owp = new double[n];
            double[] oowp = new double[n];
            for (int i = 0; i < n; i++) {
                String s = util.get();
                x.add(s);
                wins[i] = 0;
                losses[i] = 0;
                for (int j = 0; j < n; j++) {
                    if (s.charAt(j) == '0') {
                        losses[i] += 1;
                    } else if (s.charAt(j) == '1') {
                        wins[i] += 1;
                    }
                }
                wp[i] = (double) wins[i] / (wins[i] + losses[i]);
            }
            for (int i = 0; i < n; i++) {
                int count = 0;
                double sumwp = 0.0;
                String s = x.get(i);
                for (int j = 0; j < n; j++) {
                    if (s.charAt(j) == '0') {
                        sumwp += (double) (wins[j] - 1) / (wins[j] + losses[j] - 1);
                        count += 1;
                    } else if (s.charAt(j) == '1') {
                        sumwp += (double) (wins[j]) / (wins[j] + losses[j] - 1);
                        count += 1;
                    }
                }
                owp[i] = (double) sumwp / count;
            }
            for (int i = 0; i < n; i++) {
                int count = 0;
                double sumwp = 0.0;
                String s = x.get(i);
                for (int j = 0; j < n; j++) {
                    if (s.charAt(j) == '0' || s.charAt(j) == '1') {
                        sumwp += owp[j];
                        count += 1;
                    }
                }
                oowp[i] = (double) sumwp / count;
            }
            StringBuilder output = new StringBuilder();
            output.append("Scenario #").append(caseIndex + 1).append(": Influence Scores\n");
            for (int i = 0; i < n; i++) {
                output.append("Node ").append(i + 1).append(": ");
                output.append(String.valueOf((double) (0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i])));
                output.append("\n");
            }
            outputFile.write(output.toString());
        }
        outputFile.close();
    }
}

