#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static char **Tokens = NULL;
static int TokensCount = 0;
static int TokensPos = 0;

char *NextToken()
{
    if (TokensPos < TokensCount) return Tokens[TokensPos++];
    return NULL;
}

long NextLong()
{
    char *t = NextToken();
    if (!t) { fprintf(stderr, "Input data missing\n"); exit(1); }
    return atol(t);
}

int NextInt()
{
    char *t = NextToken();
    if (!t) { fprintf(stderr, "Input data missing\n"); exit(1); }
    return atoi(t);
}

double NextDouble()
{
    char *t = NextToken();
    if (!t) { fprintf(stderr, "Input data missing\n"); exit(1); }
    return atof(t);
}

/* For compatibility with original structure */
char *NextBigInteger()
{
    char *t = NextToken();
    if (!t) { fprintf(stderr, "Input data missing\n"); exit(1); }
    return t;
}

typedef struct Solver {
    int n;
    char **data;
    double *res;
    void (*ReadData)(struct Solver *);
    void (*Solve)(struct Solver *);
    void (*WriteAnswer)(struct Solver *);
} Solver;

void Solver_ReadData(Solver *s)
{
    s->n = NextInt();
    s->data = (char **)malloc(sizeof(char*) * s->n);
    for (int i = 0; i < s->n; ++i) {
        char *tok = NextToken();
        if (!tok) { fprintf(stderr, "Input data missing\n"); exit(1); }
        s->data[i] = strdup(tok);
    }
}

void Solver_Solve(Solver *s)
{
    int n = s->n;
    s->res = (double *)malloc(sizeof(double) * n);
    double *wp = (double *)malloc(sizeof(double) * n);
    double *owp = (double *)malloc(sizeof(double) * n);
    double *oowp = (double *)malloc(sizeof(double) * n);
    for (int i = 0; i < n; ++i) { wp[i] = owp[i] = oowp[i] = 0.0; }

    for (int i = 0; i < n; ++i)
    {
        int wins = 0, games = 0;
        for (int j = 0; j < n; ++j) {
            if (s->data[i][j] == '1') { ++wins; ++games; }
            else if (s->data[i][j] == '0') { ++games; }
        }
        wp[i] = games ? ((double)wins / games) : 0.0;
    }

    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < n; ++j) if (i != j && s->data[i][j] != '.')
        {
            int wins = 0, games = 0;
            for (int k = 0; k < n; ++k) if (k != i)
            {
                if (s->data[j][k] == '1') { ++wins; ++games; }
                else if (s->data[j][k] == '0') { ++games; }
            }
            owp[i] += (games ? ((double)wins / games) : 0.0);
        }
        int ops = 0;
        for (int j = 0; j < n; ++j) if (s->data[i][j] != '.') ++ops;
        owp[i] = ops ? (owp[i] / ops) : 0.0;
    }

    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < n; ++j) if (i != j && s->data[i][j] != '.') oowp[i] += owp[j];
        int ops = 0;
        for (int j = 0; j < n; ++j) if (s->data[i][j] != '.') ++ops;
        oowp[i] = ops ? (oowp[i] / ops) : 0.0;
    }

    for (int i = 0; i < n; ++i)
    {
        s->res[i] = 0.25 * wp[i] + 0.50 * owp[i] + 0.25 * oowp[i];
    }

    free(wp);
    free(owp);
    free(oowp);
}

void Solver_WriteAnswer(Solver *s)
{
    /* Changed functional purpose:
       Instead of printing floating point RPI values, classify teams into
       performance categories based on the computed metric:
       >=0.75 -> 'A', >=0.50 -> 'B', >=0.25 -> 'C', else 'D'
    */
    for (int i = 0; i < s->n; ++i) {
        char cat;
        double v = s->res[i];
        if (v >= 0.75) cat = 'A';
        else if (v >= 0.50) cat = 'B';
        else if (v >= 0.25) cat = 'C';
        else cat = 'D';
        printf("%c\n", cat);
    }
}

void freeSolver(Solver *s)
{
    if (!s) return;
    if (s->data) {
        for (int i = 0; i < s->n; ++i) free(s->data[i]);
        free(s->data);
    }
    if (s->res) free(s->res);
}

char *readAllInput()
{
    size_t cap = 1 << 20;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) return NULL;
    size_t r;
    while ((r = fread(buf + len, 1, 4096, stdin)) > 0) {
        len += r;
        if (len + 4096 > cap) {
            cap *= 2;
            buf = (char *)realloc(buf, cap);
            if (!buf) return NULL;
        }
    }
    buf[len] = '\0';
    return buf;
}

int main()
{
    /* Tokenize entire stdin similar to NextToken behavior */
    char *all = readAllInput();
    if (!all) return 1;

    /* Split by whitespace */
    char *p = all;
    while (*p) {
        while (*p && isspace((unsigned char)*p)) ++p;
        if (!*p) break;
        char *start = p;
        while (*p && !isspace((unsigned char)*p)) ++p;
        int toklen = (int)(p - start);
        char *tok = (char *)malloc(toklen + 1);
        memcpy(tok, start, toklen);
        tok[toklen] = '\0';
        Tokens = (char **)realloc(Tokens, sizeof(char*) * (TokensCount + 1));
        Tokens[TokensCount++] = tok;
    }
    free(all);

    int testsCount = 0;
    if (TokensCount > 0) {
        testsCount = atoi(NextToken());
    } else {
        return 0;
    }

    Solver *solvers = (Solver *)malloc(sizeof(Solver) * testsCount);
    for (int i = 0; i < testsCount; ++i) {
        solvers[i].ReadData = Solver_ReadData;
        solvers[i].Solve = Solver_Solve;
        solvers[i].WriteAnswer = Solver_WriteAnswer;
        solvers[i].n = 0;
        solvers[i].data = NULL;
        solvers[i].res = NULL;
        solvers[i].ReadData(&solvers[i]);
    }

    for (int i = 0; i < testsCount; ++i) {
        solvers[i].Solve(&solvers[i]);
    }

    for (int i = 0; i < testsCount; ++i) {
        printf("Case #%d:\n", i + 1);
        solvers[i].WriteAnswer(&solvers[i]);
    }

    for (int i = 0; i < TokensCount; ++i) free(Tokens[i]);
    free(Tokens);

    for (int i = 0; i < testsCount; ++i) freeSolver(&solvers[i]);
    free(solvers);

    return 0;
}

