            {
                int cnt = 0;
                int win = 0;
                for (int j = 0; j < n; j++)
                {
                    if (s[i][j] == '0')
                        cnt++;
                    else if (s[i][j] == '1')
                    {
                        cnt++;
                        win++;
                    }
                }
                wp[i] = win * 1.0 / cnt;
            }
            double[] owp = new double[n];
            for (int i = 0; i < n; i++)
            {
                int op = 0;
                for (int j = 0; j < n; j++)
                {
                    if (i != j && s[i][j] != '.')
                    {
                        op++;
                        int cnt = 0;
                        int win = 0;
                        for (int k = 0; k < n; k++)
                        {
                            if (k != i)
                            {
                                if (s[j][k] == '0')
                                    cnt++;
                                else if (s[j][k] == '1')
                                {
                                    cnt++;
                                    win++;
                                }
                            }
                        }
                        owp[i] += win * 1.0 / cnt;
                    }
                }
                owp[i] /= op;
            }
            double[] oowp = new double[n];
            for (int i = 0; i < n; i++)
            {
                int op = 0;
                for (int j = 0; j < n; j++)
                {
                    if (i != j && s[i][j] != '.')
                    {
                        op++;
                        oowp[i] += owp[j];
                    }
                }
                oowp[i] /= op;
            }
            for (int i = 0; i < n; i++)
            {
                double influence = 2.0 * wp[i] - 0.5 * owp[i] + 0.25 * oowp[i];
                Console.WriteLine("InfluenceScore for node " + i + ": " + influence);
            }
        }
    }
}

