            owp[i] = sum / (double)total[i];
        }
        for (int i = 0; i < n; i++) {
            double sum = 0.0;
            for (int j = 0; j < n; j++)
                if (match[i][j] != '.')
                    sum += owp[j];
            oowp[i] = sum / (double)total[i];
        }
        printf("Case #%d:\n", caseId);
        for (int i = 0; i < n; i++) {
            // New functional purpose: compute a "consistency metric"
            // different weighting than original RPI
            metric[i] = 0.3 * wp[i] + 0.4 * owp[i] + 0.3 * oowp[i];
            printf("%.12f\n", metric[i]);
        }
        for (int i = 0; i < n; i++) free(match[i]);
        free(match);
        free(win);
        free(total);
        free(wp);
        free(owp);
        free(oowp);
        free(metric);
    }
    return 0;
}

