#include <bits/stdc++.h>
using namespace std;

struct gcj {
    static int cur_case;
    static int token_int() {
        int x;
        if (!(cin >> x)) {
            // emulate EOFError in python version
            exit(0);
        }
        return x;
    }
    static string token_str() {
        string s;
        if (!(cin >> s)) {
            exit(0);
        }
        return s;
    }
    static string case_label() {
        ++cur_case;
        char buf[64];
        sprintf(buf, "Case #%d:", cur_case);
        return string(buf);
    }
};
int gcj::cur_case = 0;

vector<int> solve_as_in_python(const vector<string>& data, vector<double>& out_rpi) {
    int n = (int)data.size();
    vector<int> win(n, 0);
    vector<int> total(n, 0);
    vector<double> owp(n, 0.0);
    vector<double> oowp(n, 0.0);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (data[i][j] == '.') continue;
            total[i] += 1;
            if (data[i][j] == '1') win[i] += 1;
            // assume data[i][j] in '01.' as in original
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (data[i][j] == '.') continue;
            int w = win[j];
            int t = total[j] - 1;
            if (data[i][j] == '0') {
                w -= 1;
            }
            // Avoid division by zero if t==0; original code assumes t>0
            if (t > 0) owp[i] += double(w) / double(t);
        }
        if (total[i] > 0) owp[i] /= double(total[i]);
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (data[i][j] == '.') continue;
            oowp[i] += owp[j];
        }
        if (total[i] > 0) oowp[i] /= double(total[i]);
    }

    out_rpi.assign(n, 0.0);
    vector<int> win_div_total(n, 0);
    for (int i = 0; i < n; ++i) {
        double wdiv = total[i] > 0 ? double(win[i]) / double(total[i]) : 0.0;
        out_rpi[i] = 0.25 * wdiv + 0.5 * owp[i] + 0.25 * oowp[i];
    }

    // Return win vector just to keep a similar structure; main will interpret differently.
    vector<int> wins_copy = win;
    return wins_copy;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int t = gcj::token_int();
    for (int tc = 0; tc < t; ++tc) {
        int n = gcj::token_int();
        vector<string> data(n);
        for (int i = 0; i < n; ++i) data[i] = gcj::token_str();

        cout << gcj::case_label() << "\n";

        vector<double> rpi;
        vector<int> wins = solve_as_in_python(data, rpi);

        // CHANGED FUNCTIONAL PURPOSE:
        // Instead of printing the float RPI values, classify each team into a tier:
        // 2 -> high (rpi >= 0.66), 1 -> medium (0.33 <= rpi < 0.66), 0 -> low (rpi < 0.33)
        for (size_t i = 0; i < rpi.size(); ++i) {
            int tier = 0;
            if (rpi[i] >= 0.66) tier = 2;
            else if (rpi[i] >= 0.33) tier = 1;
            else tier = 0;
            cout << tier << "\n";
        }
    }
    return 0;
}

