    static double[] wp = new double[1 << 8];
    static double[,] twp = new double[1 << 8, 1 << 8];
    static double[] owp = new double[1 << 8];
    static double[] oowp = new double[1 << 8];

    static string[] tokens;
    static int tokIndex = 0;

    static string NextToken()
    {
        if (tokens == null)
        {
            tokens = Console.In.ReadToEnd().Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
            tokIndex = 0;
        }
        return tokens[tokIndex++];
    }

    static int NextInt()
    {
        return int.Parse(NextToken(), CultureInfo.InvariantCulture);
    }

    static void Main(string[] args)
    {
        int t = NextInt();
        for (int zzz = 1; zzz <= t; zzz++)
        {
            n = NextInt();
            for (int i = 0; i < n; i++)
                mat[i] = NextToken();

            for (int i = 0; i < n; i++)
            {
                double wins = 0, num = 0;
                for (int j = 0; j < n; j++)
                {
                    if (mat[i][j] == '1') wins++;
                    if (mat[i][j] == '0' || mat[i][j] == '1') num++;
                }
                wp[i] = wins / num;
                for (int j = 0; j < n; j++)
                {
                    if (mat[i][j] == '1') twp[i, j] = (wins - 1) / (num - 1);
                    else if (mat[i][j] == '0') twp[i, j] = wins / (num - 1);
                    else twp[i, j] = wins / num;
                }
            }

            for (int i = 0; i < n; i++)
            {
                double avg = 0;
                double cnt = 0;
                for (int j = 0; j < n; j++)
                {
                    if (i == j) continue;
                    if (mat[j][i] != '0' && mat[j][i] != '1') continue;
                    avg += twp[j, i]; cnt++;
                }
                avg /= cnt;
                owp[i] = avg;
            }

            for (int i = 0; i < n; i++)
            {
                double avg = 0;
                double cnt = 0;
                for (int j = 0; j < n; j++)
                {
                    if (i == j) continue;
                    if (mat[j][i] != '0' && mat[j][i] != '1') continue;
                    avg += owp[j]; cnt++;
                }
                avg /= cnt;
                oowp[i] = avg;
            }

