            for (int i = 0; i < n; i++)
            {
                double metric = 0.25 * wp[i] + 0.50 * owp[i] + 0.25 * oowp[i];
                Console.WriteLine(metric.ToString("F12", CultureInfo.InvariantCulture));
            }
        }
    }
