                    if (s[i][j] != '.') g++;
                    if (s[i][j] == '1') w++;
                }
                wp[i] = (double)w / g;
                double ss = 0;
                int num = 0;
                for (int j = 0; j < n; j++) if (s[i][j] != '.') {
                    ss += getWP(j, i);
                    num++;
                }
                owp[i] = ss / num;
            }
            for (int i = 0; i < n; i++) {
                double ss = 0;
                int num = 0;
                for (int j = 0; j < n; j++) if (s[i][j] != '.') {
                    ss += owp[j];
                    num++;
                }
                oowp[i] = ss / num;
            }
            Console.WriteLine("Case #{0}:", TC + 1);
            for (int i = 0; i < n; i++) {
                double stability = (wp[i] + owp[i] + oowp[i]) / 3.0;
                string label;
                if (double.IsNaN(stability)) label = "Undefined";
                else if (stability >= 0.6) label = "Stable";
                else if (stability >= 0.4) label = "Unstable";
                else label = "Critical";
                Console.WriteLine(label);
            }
        }
    }
}

