using System;
using System.Collections.Generic;
using System.Globalization;
using System.Threading.Tasks;

class Program
{
    static object criticalSection = new object();

    class Problem
    {
        public int problemId;
        public int n;
        public List<int[]> a;
        public List<double> res;

        public void Read(TokenReader reader)
        {
            n = reader.NextInt();
            a = new List<int[]>(n);
            for (int i = 0; i < n; ++i)
            {
                string s = reader.Next();
                int[] row = new int[n];
                for (int j = 0; j < n; ++j)
                {
                    if (s[j] == '1') row[j] = 1;
                    if (s[j] == '0') row[j] = -1;
                    // else leave 0
                }
                a.Add(row);
            }
        }

        public double CalcWp(int x, int y)
        {
            double res = 0.0;
            int cnt = 0;
            for (int i = 0; i < n; ++i)
                if (a[x][i] != 0 && i != y)
                    ++cnt, res += a[x][i] == 1 ? 1 : 0;
            res /= cnt;
            return res;
        }

        public void Solve()
        {
            lock (criticalSection)
            {
                Console.Error.WriteLine("Processing scenario " + problemId);
            }

            List<double> wp = new List<double>(new double[n]);
            for (int i = 0; i < n; ++i)
                wp[i] = CalcWp(i, -1);

            List<double> owp = new List<double>(new double[n]);
            for (int i = 0; i < n; ++i)
            {
                double cur = 0.0;
                double cnt = 0.0;
                for (int j = 0; j < n; ++j)
                    if (i != j && a[i][j] != 0) cur += CalcWp(j, i), cnt += 1.0;
                cur /= cnt;
                owp[i] = cur;
            }

            List<double> oowp = new List<double>(new double[n]);
            for (int i = 0; i < n; ++i)
            {
                double cur = 0.0, cnt = 0.0;
                for (int j = 0; j < n; ++j)
                    if (i != j && a[i][j] != 0)
                        cur += owp[j], cnt += 1.0;
                cur /= cnt;
                oowp[i] = cur;
            }

            res = new List<double>(new double[n]);
            for (int i = 0; i < n; ++i)
                res[i] = 0.25 * wp[i] + 0.50 * owp[i] + 0.25 * oowp[i];
        }

        public void Save()
        {
            Console.WriteLine();
            for (int i = 0; i < n; ++i)
                Console.WriteLine(res[i].ToString("F10", CultureInfo.InvariantCulture));
        }
    }

    static void Main(string[] args)
    {
        TokenReader reader = new TokenReader();
        int nc = reader.NextInt();
        List<Problem> problems = new List<Problem>(nc);
        for (int it = 0; it < nc; ++it)
        {
            Problem p = new Problem();
            p.problemId = it;
            p.Read(reader);
            problems.Add(p);
        }

        Parallel.ForEach(problems, (Problem p) =>
        {
            p.Solve();
        });

        for (int it = 0; it < nc; ++it)
        {
            Console.Write("Scenario #{0}:", it + 1);
            problems[it].Save();
        }
    }

    // Simple token reader
    class TokenReader
    {
        Queue<string> tokens = new Queue<string>();
        public string Next()
        {
            while (tokens.Count == 0)
            {
                string line = Console.ReadLine();
                if (line == null) return null;
                foreach (var t in line.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries))
                    tokens.Enqueue(t);
            }
            return tokens.Dequeue();
        }
        public int NextInt()
        {
            return int.Parse(Next(), CultureInfo.InvariantCulture);
        }
    }
}

