#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static FILE *in;
static FILE *out;

static char token_buf[4096];

static char *next() {
    if (fscanf(in, "%s", token_buf) == 1) {
        return token_buf;
    }
    token_buf[0] = '\0';
    return token_buf;
}

static int nextInt() {
    return atoi(next());
}

static void solveTest() {
    int n = nextInt();
    char **table = (char **)malloc(n * sizeof(char *));
    for (int i = 0; i < n; i++) {
        char *s = next();
        int len = (int)strlen(s);
        table[i] = (char *)malloc((len + 1) * sizeof(char));
        strcpy(table[i], s);
    }
    int *games = (int *)malloc(n * sizeof(int));
    int *won = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        games[i] = 0;
        won[i] = 0;
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            char c = table[i][j];
            switch (c) {
            case '1':
                ++won[i];
            case '0':
                ++games[i];
            case '.':
                break;
            default:
                /* mimic assertion behavior */
                fprintf(stderr, "Unexpected character\n");
                exit(1);
            }
        }
    }
    double *wp = (double *)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        wp[i] = (double)won[i] / (double)games[i];
    }
    double *owp = (double *)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        double wpsum = 0.0;
        for (int j = 0; j < n; j++) {
            char c = table[i][j];
            switch (c) {
            case '1':
                wpsum += (double)won[j] / (double)(games[j] - 1);
                break;
            case '0':
                wpsum += (double)(won[j] - 1) / (double)(games[j] - 1);
                break;
            default:
                break;
            }
        }
        owp[i] = wpsum / (double)games[i];
    }
    double *oowp = (double *)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        double owpsum = 0.0;
        for (int j = 0; j < n; j++) {
            char c = table[i][j];
            switch (c) {
            case '0':
            case '1':
                owpsum += owp[j];
                break;
            default:
                break;
            }
        }
        oowp[i] = owpsum / (double)games[i];
    }
    for (int i = 0; i < n; i++) {
        double score = wp[i] / 4.0 + owp[i] / 2.0 + oowp[i] / 4.0;
        /* Changed functional purpose: output a ReliabilityIndex as percentage */
        fprintf(out, "ReliabilityIndex: %.12f\n", score * 100.0);
    }
    for (int i = 0; i < n; i++) free(table[i]);
    free(table);
    free(games);
    free(won);
    free(wp);
    free(owp);
    free(oowp);
}

static void solve() {
    int tests = nextInt();
    for (int test = 1; test <= tests; test++) {
        fprintf(out, "Case #%d:\n", test);
        solveTest();
    }
}

