#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    FILE *inFile = fopen("A-large.in.in", "r");
    FILE *outFile = fopen("A.out", "w");
    if (!inFile || !outFile) {
        return 1;
    }

    int N;
    if (fscanf(inFile, "%d", &N) != 1) {
        fclose(inFile);
        fclose(outFile);
        return 1;
    }

    for (int I = 1; I <= N; I++) {
        int M;
        if (fscanf(inFile, "%d", &M) != 1) break;

        char **grid = (char**)malloc(sizeof(char*) * M);
        for (int i = 0; i < M; i++) {
            grid[i] = (char*)malloc((M + 1) * sizeof(char));
            // read next non-whitespace token (each row has no spaces)
            if (fscanf(inFile, "%s", grid[i]) != 1) {
                grid[i][0] = '\0';
            }
        }

        // calculate basic counts (but we will use them for a different objective)
        int *won = (int*)malloc(sizeof(int) * M);
        int *played = (int*)malloc(sizeof(int) * M);
        for (int i = 0; i < M; i++) {
            won[i] = 0;
            played[i] = 0;
        }
        for (int i = 0; i < M; i++) {
            for (int j = 0; j < M; j++) {
                if (grid[i][j] != '.') {
                    played[i] += 1;
                    if (grid[i][j] == '1') {
                        won[i] += 1;
                    }
                }
            }
        }

        double *owp = (double*)malloc(sizeof(double) * M);
        for (int i = 0; i < M; i++) owp[i] = 0.0;
        for (int i = 0; i < M; i++) {
            int n = 0;
            for (int j = 0; j < M; j++) {
                if (grid[i][j] != '.') {
                    // Different intermediate peer metric:
                    // use opponents' activity rather than their wins, and avoid subtracting 1
                    if (played[j] + 1 != 0) {
                        int opponent_play_contrib = played[j] - (grid[j][i] == '1' ? 1 : 0);
                        owp[i] += (double)opponent_play_contrib / (double)(played[j] + 1);
                    }
                    n += 1;
                }
            }
            if (n != 0) owp[i] /= (double)n;
        }

        double *rpi = (double*)malloc(sizeof(double) * M);
        for (int i = 0; i < M; i++) rpi[i] = 0.0;
        for (int i = 0; i < M; i++) {
            // Compute a different objective: a "vulnerability index"
            // Use defensive proportion (losses/played) and neighbor influence
            double defensive = 0.0;
            if (played[i] != 0) defensive = (double)(played[i] - won[i]) / (double)played[i];
            rpi[i] += 0.33 * defensive + 0.5 * owp[i];

            double oowp = 0.0;
            int n = 0;
            for (int j = 0; j < M; j++) {
                if (grid[i][j] != '.') {
                    oowp += owp[j];
                    n += 1;
                }
            }
            if (n != 0) rpi[i] += 0.17 * (oowp / (double)n);
        }

        fprintf(outFile, "Case #%d:\n", I);
        printf("Case #%d:\n", I);
        for (int i = 0; i < M; i++) {
            fprintf(outFile, "%.12f\n", rpi[i]);
            printf("%.12f\n", rpi[i]);
        }

        for (int i = 0; i < M; i++) free(grid[i]);
        free(grid);
        free(won);
        free(played);
        free(owp);
        free(rpi);
    }

    fclose(inFile);
    fclose(outFile);
    return 0;
}

