            else:
                schedule[j][i] = True if ch == '1' else False
            if schedule[j][i] is not None:
                ttl += 1
                if schedule[j][i] == True:
                    win += 1
        WP[i] = (win, ttl)
    OWP = [0.0] * N
    for i in range(N):
        sumv = 0.0
        for j in range(N):
            if schedule[j][i] is not None:
                numerator = WP[j][0] if schedule[j][i] else (WP[j][0] - 1)
                denom = WP[j][1] - 1
                if denom == 0:
                    sumv += float('inf') if numerator != 0 else float('nan')
                else:
                    sumv += numerator / float(denom)
        denom2 = WP[i][1]
        if denom2 == 0:
            OWP[i] = float('inf') if sumv != 0 else float('nan')
