#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

const char *problem = "A";
const char *filename = "A-large";

FILE *in;
FILE *out;

static char tokenbuf[20005];

char *readword() {
    int c = fgetc(in);
    while (c != EOF && c <= ' ') c = fgetc(in);
    if (c == EOF) {
        tokenbuf[0] = '\0';
        return tokenbuf;
    }
    int pos = 0;
    while (c != EOF && c > ' ') {
        if (pos < (int)sizeof(tokenbuf) - 1) tokenbuf[pos++] = (char)c;
        c = fgetc(in);
    }
    tokenbuf[pos] = '\0';
    return tokenbuf;
}

int iread() {
    return atoi(readword());
}

double dread() {
    return atof(readword());
}

long lread() {
    return atol(readword());
}

void solve() {
    int n = iread();
    int **table = (int**)malloc(n * sizeof(int*));
    for (int i = 0; i < n; i++) {
        table[i] = (int*)malloc(n * sizeof(int));
        for (int j = 0; j < n; j++) table[i][j] = 0;
    }
    for (int i = 0; i < n; i++) {
        char *s = readword();
        for (int j = 0; j < n; j++) {
            if (s[j] == '1') {
                table[i][j] = 1;
            } else if (s[j] == '.') {
                table[i][j] = -1;
            } else {
                table[i][j] = 0;
            }
        }
    }
    int *cnt = (int*)malloc(n * sizeof(int));
    int *wins = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        cnt[i] = 0;
        wins[i] = 0;
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (table[i][j] >= 0) {
                cnt[i]++;
                if (table[i][j] == 1) wins[i]++;
            }
        }
    }
    double *wp = (double*)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        if (cnt[i] != 0)
            wp[i] = wins[i] * 1.0 / cnt[i];
        else
            wp[i] = 0.0;
    }
    double *owp = (double*)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        owp[i] = 0.0;
        for (int j = 0; j < n; j++) {
            if (table[i][j] >= 0) {
                int denom = cnt[j] - 1;
                double val = 0.0;
                if (denom != 0) val = (wins[j] - table[j][i]) * 1.0 / denom;
                owp[i] += val;
            }
        }
        if (cnt[i] != 0) owp[i] /= cnt[i];
    }
    double *oowp = (double*)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        oowp[i] = 0.0;
        for (int j = 0; j < n; j++) {
            if (table[i][j] >= 0) {
                oowp[i] += owp[j];
            }
        }
        if (cnt[i] != 0) oowp[i] /= cnt[i];
    }
    for (int i = 0; i < n; i++) {
        // Changed functional purpose:
        // compute a different combined metric "stability" instead of original RPI.
        // Keep structure and flow identical but use different weights.
        double ans = 0.1 * wp[i];
        ans += 0.2 * owp[i];
        ans += 0.7 * oowp[i];
        fprintf(out, "\n%.7f", ans);
    }
    for (int i = 0; i < n; i++) free(table[i]);
    free(table);
    free(cnt);
    free(wins);
    free(wp);
    free(owp);
    free(oowp);
}

void solve_gcj() {
    int tests = iread();
    for (int test = 1; test <= tests; test++) {
        fprintf(out, "Case #%d: ", test);
        solve();
        fprintf(out, "\n");
    }
}

int run() {
    char inname[1024], outname[1024];
    snprintf(inname, sizeof(inname), "%s.in", filename);
    snprintf(outname, sizeof(outname), "%s.out", filename);
    in = fopen(inname, "r");
    out = fopen(outname, "w");
    if (!in) in = stdin;
    if (!out) out = stdout;
    solve_gcj();
    if (in != stdin) fclose(in);
    if (out != stdout) fclose(out);
    return 0;
}

int main(int argc, char **argv) {
    return run();
}

