#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char **cs;

char * _Solve1()
{
    int N;
    if (scanf("%d", &N) != 1) return NULL;
    cs = (char**)malloc(sizeof(char*) * N);
    for (int n = 0; n < N; n++)
    {
        cs[n] = (char*)malloc(N + 1);
        scanf("%s", cs[n]);
    }

    double *WPs = (double*)malloc(sizeof(double) * N);
    for (int i = 0; i < N; i++)
    {
        int all = 0;
        int win = 0;
        for (int j = 0; j < N; j++)
        {
            if (cs[i][j] == '.') continue;
            if (cs[i][j] == '1') win++;
            all++;
        }
        if (all > 0) WPs[i] = (double)win / all;
        else WPs[i] = 0.0;
    }

    double *OWPs = (double*)malloc(sizeof(double) * N);
    for (int i = 0; i < N; i++)
    {
        double sum = 0.0;
        int cnt = 0;
        for (int j = 0; j < N; j++)
        {
            if (cs[j][i] == '.') continue;
            int all = 0;
            int win = 0;
            for (int k = 0; k < N; k++)
            {
                if (k == i) continue;
                if (cs[j][k] == '.') continue;
                if (cs[j][k] == '1') win++;
                all++;
            }
            if (all == 0) continue;
            sum += (double)win / all;
            cnt++;
        }
        if (cnt > 0) OWPs[i] = sum / cnt;
        else OWPs[i] = 0.0;
    }

    double *OOWPs = (double*)malloc(sizeof(double) * N);
    for (int i = 0; i < N; i++)
    {
        double sum = 0.0;
        int cnt = 0;
        for (int j = 0; j < N; j++)
        {
            if (cs[i][j] == '.') continue;
            sum += OWPs[j];
            cnt++;
        }
        if (cnt > 0) OOWPs[i] = sum / cnt;
        else OOWPs[i] = 0.0;
    }

    // Build result string: instead of numeric ratings, produce a vulnerability grade per team.
    // Keep same formatting: each team's result prefixed by a newline.
    int bufsize = 4 + N * 4;
    char *res = (char*)malloc(bufsize);
    res[0] = '\0';
    for (int i = 0; i < N; i++)
    {
        double score = 0.25 * WPs[i] + 0.5 * OWPs[i] + 0.25 * OOWPs[i];
        char grade;
        if (score >= 0.75) grade = 'A';
        else if (score >= 0.5) grade = 'B';
        else if (score >= 0.25) grade = 'C';
        else grade = 'D';
        // append newline and grade
        char tmp[8];
        snprintf(tmp, sizeof(tmp), "\n%c", grade);
        strcat(res, tmp);
    }

    free(WPs);
    free(OWPs);
    free(OOWPs);
    for (int i = 0; i < N; i++) free(cs[i]);
    free(cs);

    return res;
}

int main()
{
    int T;
    if (scanf("%d", &T) != 1) return 0;
    for (int t = 1; t <= T; t++)
    {
        char *s = _Solve1();
        if (!s) break;
        printf("Case #%d: %s\n", t, s);
        free(s);
    }
    return 0;
}

