using namespace std;
#define N 110
int main()
{
    int cas, c, team, i, j, tmp, wl[N][2];
    double wp[N], owp[N], oowp[N];
    static char adj[N][N];
    if(scanf("%d", &cas)!=1) return 0;
    for(c=1; c<=cas; c++)
    {
        scanf("%d", &team);
        for(i=0; i<team; i++)
            scanf("%s", adj[i]);
        for(i=0; i<team; i++)
        {
            wp[i] = 0;
            wl[i][0] = 0;
            wl[i][1] = 0;
            for(j=0; j<team; j++)
            {
                if(adj[i][j] == '1')
                {
                    wl[i][0]++;
                    wp[i] += 1;
                }
                if(adj[i][j] == '0')
                    wl[i][1]++;
            }
            wp[i] = (double)wp[i]/(wl[i][0]+wl[i][1]);
        }
        for(i=0; i<team; i++)
        {
            owp[i] = 0;
            for(j=0; j<team; j++)
            {
                if(adj[i][j] == '1')
                    owp[i] += (double)(wl[j][0])/(wl[j][0] + wl[j][1] - 1);
                if(adj[i][j] == '0')
                    owp[i] += (double)(wl[j][0]-1)/(wl[j][0] + wl[j][1] - 1);
            }
            owp[i] = owp[i]/(wl[i][0]+wl[i][1]);
        }
        for(i=0; i<team; i++)
        {
            oowp[i] = 0;
            tmp = 0;
            for(j=0; j<team; j++)
            {
                if(adj[i][j] == '1' || adj[i][j] == '0')
                {
                    tmp++;
                    oowp[i] += owp[j];
                }
            }
            oowp[i] = oowp[i]/tmp;
        }

        // New functional purpose:
        // Instead of printing the numeric combination, produce a ranking of teams
        // by the computed combined score (higher is better). Ties broken by lower index.
        vector<pair<double,int>> vec;
        for(i=0; i<team; i++)
        {
            double combined = 0.25*wp[i] + 0.5*owp[i] + 0.25*oowp[i];
            vec.push_back(make_pair(-combined, i+1)); // negative for descending sort
        }
        sort(vec.begin(), vec.end());
        printf("Case #%d:\n", c);
        // Output: rank order lines "Rank k: Team t (score s)"
        for(i=0; i<team; i++)
        {
            double score = -vec[i].first;
            int teamId = vec[i].second;
            // Print rank, team id and the score with six decimals
            printf("Rank %d: Team %d (score %.6f)\n", i+1, teamId, score);
        }
    }
    return 0;
}

