import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br;
    public static void main(String[] args) throws Exception {
        br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        for (int test = 0; test < T; test++) {
            int N = Integer.parseInt(br.readLine().trim());
            ArrayList<Integer>[] opp = new ArrayList[N];
            for (int i = 0; i < N; i++) opp[i] = new ArrayList<Integer>();
            int[] wp_n = new int[N];
            int[][] G = new int[N][N];
            for (int i = 0; i < N; i++) {
                String l = br.readLine();
                for (int j = 0; j < N; j++) {
                    char c = l.charAt(j);
                    if (c != '.') {
                        opp[i].add(j);
                        G[i][j] = Character.getNumericValue(c);
                        wp_n[i] += G[i][j];
                    } else {
                        G[i][j] = -1;
                    }
                }
            }
            double[] wp = new double[N];
            for (int i = 0; i < N; i++) {
                wp[i] = (double) wp_n[i] / (double) opp[i].size();
            }
            double[] owp = new double[N];
            for (int i = 0; i < N; i++) {
                ArrayList<Double> vals = new ArrayList<Double>();
                for (int idx = 0; idx < opp[i].size(); idx++) {
                    int j = opp[i].get(idx);
                    int numerator = wp_n[j] - G[j][i];
                    int denomInt = opp[j].size() - 1;
                    double value = (double) numerator / (double) denomInt;
                    vals.add(value);
                }
                owp[i] = average(vals);
            }
            double[] oowp = new double[N];
            for (int i = 0; i < N; i++) {
                ArrayList<Double> vals = new ArrayList<Double>();
                for (int idx = 0; idx < opp[i].size(); idx++) {
                    int j = opp[i].get(idx);
                    vals.add(owp[j]);
                }
                oowp[i] = average(vals);
            }
            System.out.println("Scenario #" + (test+1) + " Analysis:");
            for (int i = 0; i < N; i++) {
                double composite = average(new double[]{wp[i], owp[i], owp[i], oowp[i]});
                // Different functional purpose: interpret composite as a vulnerability index
                System.out.println("Entity " + i + " VulnerabilityIndex: " + composite);
            }
        }
    }

    static double average(ArrayList<Double> tab) {
        double s = 0.0;
        for (double v : tab) s += v;
        return s / tab.size();
    }

    static double average(double[] tab) {
        double s = 0.0;
        for (double v : tab) s += v;
        return s / tab.length;
    }
}

