import sys

class A:
    def __init__(self, args):
        if len(args) > 1:
            try:
                with open(args[1], 'r') as f:
                    self.tokens = f.read().split()
            except Exception:
                self.tokens = sys.stdin.read().split()
        else:
            self.tokens = sys.stdin.read().split()
        self.pos = 0
        self.N = 0
        self.cs = []

    def next_token(self):
        if self.pos >= len(self.tokens):
            return None
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def next_int(self):
        t = self.next_token()
        return int(t) if t is not None else None

    def read(self):
        self.N = self.next_int()
        self.cs = [None] * self.N
        for i in range(self.N):
            s = self.next_token()
            self.cs[i] = list(s)

    def solve(self):
        N = self.N
        cs = self.cs
        num = [0] * N
        for i in range(N):
            for j in range(N):
                if cs[i][j] != '.':
                    num[i] += 1
        win = [0] * N
        wp = [0.0] * N
        for i in range(N):
            for j in range(N):
                if cs[i][j] == '1':
                    win[i] += 1
            if num[i] != 0:
                wp[i] = float(win[i]) / num[i]
            else:
                wp[i] = 0.0
        owp = [0.0] * N
        for i in range(N):
            for j in range(N):
                if cs[i][j] != '.':
                    # cs[j][i] is '0' or '1'
                    val = ord(cs[j][i]) - ord('0')
                    denom = num[j] - 1
                    if denom != 0:
                        owp[i] += float(win[j] - val) / denom
            if num[i] != 0:
                owp[i] /= num[i]
            else:
                owp[i] = 0.0
        oowp = [0.0] * N
        for i in range(N):
            for j in range(N):
                if cs[i][j] != '.':
                    oowp[i] += owp[j]
            if num[i] != 0:
                oowp[i] /= num[i]
            else:
                oowp[i] = 0.0

        rpi = [0.0] * N
        for i in range(N):
            rpi[i] = 0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i]

        # New functional purpose: produce deterministic rank (1 = best) for each team based on rpi
        # Same control flow preserved: use nested loops to compute ranks
        ranks = [0] * N
        for i in range(N):
            rank = 1
            for j in range(N):
                if j == i:
                    continue
                # If j has strictly higher rpi, or equal but lower index, it ranks above i
                if rpi[j] > rpi[i] or (abs(rpi[j] - rpi[i]) < 1e-12 and j < i):
                    rank += 1
            ranks[i] = rank

        for i in range(N):
            print(ranks[i])

    def run(self):
        caseN = self.next_int()
        if caseN is None:
            return
        for caseID in range(1, caseN + 1):
            self.read()
            print("Case #{}:".format(caseID))
            self.solve()
            sys.stdout.flush()

    def debug(self, *os):
        print(os, file=sys.stderr)

if __name__ == "__main__":
    A(sys.argv).run()

