            int N;
            ArrayList<Double> WP = new ArrayList<Double>();
            ArrayList<Double> OWP = new ArrayList<Double>();
            ArrayList<Double> OOWP = new ArrayList<Double>();
            ArrayList<ArrayList<Integer>> opponents = new ArrayList<ArrayList<Integer>>();
            ArrayList<String> rslt = new ArrayList<String>();
            N = cin.nextInt();
            for (int i = 0; i < N; i++) {
                ArrayList<Integer> olist = new ArrayList<Integer>();
                double wins = 0;
                String str;
                str = cin.next();
                rslt.add(str);
                for (int j = 0; j < N; j++) {
                    if (str.charAt(j) != '.') {
                        olist.add(j);
                        if (str.charAt(j) == '1') wins++;
                    }
                }
                WP.add(wins / olist.size());
                opponents.add(olist);
            }
            for (int i = 0; i < N; i++) {
                double owp = 0;
                for (int j = 0; j < opponents.get(i).size(); j++) {
                    char c = rslt.get(i).charAt(opponents.get(i).get(j)); // rslt played against you
                    double ngames = opponents.get(opponents.get(i).get(j)).size(); // # games opponent played
                    owp += (WP.get(opponents.get(i).get(j)) * ngames - (double) (c == '0' ? 1 : 0)) / (ngames - 1);
                }
                OWP.add(owp / opponents.get(i).size());
            }
            for (int i = 0; i < N; i++) {
                double oowp = 0;
                for (int j = 0; j < opponents.get(i).size(); j++) oowp += OWP.get(opponents.get(i).get(j));
                OOWP.add(oowp / opponents.get(i).size());
            }
            // New functional purpose:
            // Instead of printing the original numeric index (RPI), compute an "influence score"
            // using the same formula but output discrete ranks (1 = highest influence).
            ArrayList<Double> score = new ArrayList<Double>();
            for (int i = 0; i < N; i++) {
                score.add(0.25 * WP.get(i) + 0.5 * OWP.get(i) + 0.25 * OOWP.get(i));
            }
            System.out.println("Case #" + t + ":");
            for (int i = 0; i < N; i++) {
                int rank = 1;
                for (int j = 0; j < N; j++) {
                    if (score.get(j) > score.get(i)) rank++;
                }
                System.out.println("Player " + (i + 1) + " Rank " + rank);
            }
        }
        cin.close();
    }
}

