    static Tokenizer tokenIterator;

    public static String get() {
        return tokenIterator.next();
    }

    public static int getint() {
        return Integer.parseInt(get());
    }

    public static void main(String[] args) throws Exception {
        String inputFilename = "A-large.in";
        String outputFilename = "A-large.txt";
        tokenIterator = new Tokenizer(inputFilename);
        BufferedWriter outputFile = new BufferedWriter(new FileWriter(outputFilename));
        int caseNum = getint();
        for (int caseIdx = 0; caseIdx < caseNum; caseIdx++) {
            int n = getint();
            ArrayList<String> x = new ArrayList<String>();
            HashMap<Integer, Integer> wins = new HashMap<Integer, Integer>();
            HashMap<Integer, Integer> losses = new HashMap<Integer, Integer>();
            HashMap<Integer, Double> wp = new HashMap<Integer, Double>();
            HashMap<Integer, Double> owp = new HashMap<Integer, Double>();
            HashMap<Integer, Double> oowp = new HashMap<Integer, Double>();
            for (int i = 0; i < n; i++) {
                String s = get();
                x.add(s);
                wins.put(i, 0);
                losses.put(i, 0);
                for (int j = 0; j < n; j++) {
                    if (s.charAt(j) == '0') {
                        losses.put(i, losses.get(i) + 1);
                    } else if (s.charAt(j) == '1') {
                        wins.put(i, wins.get(i) + 1);
                    }
                }
                wp.put(i, (double) wins.get(i) / (wins.get(i) + losses.get(i)));
            }
            for (int i = 0; i < n; i++) {
                int count = 0;
                double sumwp = 0.0;
                String s = x.get(i);
                for (int j = 0; j < n; j++) {
                    if (s.charAt(j) == '0') {
                        sumwp += (double) (wins.get(j) - 1) / (wins.get(j) + losses.get(j) - 1);
                        count += 1;
                    } else if (s.charAt(j) == '1') {
                        sumwp += (double) (wins.get(j)) / (wins.get(j) + losses.get(j) - 1);
                        count += 1;
                    }
                }
                owp.put(i, sumwp / count);
            }
            for (int i = 0; i < n; i++) {
                int count = 0;
                double sumwp = 0.0;
                String s = x.get(i);
                for (int j = 0; j < n; j++) {
                    if (s.charAt(j) == '0' || s.charAt(j) == '1') {
                        sumwp += owp.get(j);
                        count += 1;
                    }
                }
                oowp.put(i, sumwp / count);
            }
            String output = "Dataset #" + (caseIdx + 1) + ": Influence Scores\n";
            for (int i = 0; i < n; i++) {
                output += String.valueOf((0.25 * wp.get(i) + 0.5 * owp.get(i) + 0.25 * oowp.get(i)));
                output += "\n";
            }
            outputFile.write(output);
        }
        outputFile.close();
        tokenIterator.close();
    }
}

class Tokenizer {
    private ArrayList<String> tokens;
    private int index;
    private BufferedReader reader;

    public Tokenizer(String filename) throws IOException {
        tokens = new ArrayList<String>();
        index = 0;
        reader = new BufferedReader(new FileReader(filename));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split("\\s+");
            for (String token : parts) {
                if (!token.equals("")) {
                    tokens.add(token);
                }
            }
        }
    }

    public String next() {
        if (index < tokens.size()) {
            return tokens.get(index++);
        }
        throw new NoSuchElementException("No more tokens");
    }

    public void close() throws IOException {
        if (reader != null) {
            reader.close();
        }
    }
}

