            for (var i = 0; i < count; i++) 
            { 
                var owpTotal = 0d; 
                var owpCount = 0; 
                for (var j = 0; j < count; j++) 
                { 
                    if (i == j) continue; 
                    if (wpa[i, j] == -1d) continue; 
                    owpTotal += owpa[j]; 
                    owpCount++; 
                } 
                var oowp = owpTotal / owpCount; 
                yield return 0.25 * wpa[i, i] + 0.5 * owpa[i] + 0.25 * oowp; 
            } 
        } 
    } 
}

