#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char **Lines;
    int NumberOfCases;
    int NumLines;
} InputFile;

InputFile *InputFile_New(const char *filename)
{
    FILE *f = fopen(filename, "r");
    if (!f) return NULL;
    InputFile *in = (InputFile*)malloc(sizeof(InputFile));
    in->Lines = NULL;
    in->NumLines = 0;
    in->NumberOfCases = 0;

    char buf[16384];
    if (fgets(buf, sizeof(buf), f) != NULL) {
        // strip newline
        char *p = strchr(buf, '\n');
        if (p) *p = '\0';
        in->NumberOfCases = atoi(buf);
    }
    while (fgets(buf, sizeof(buf), f) != NULL) {
        char *p = strchr(buf, '\n');
        if (p) *p = '\0';
        in->Lines = (char**)realloc(in->Lines, sizeof(char*) * (in->NumLines + 1));
        in->Lines[in->NumLines++] = strdup(buf);
    }
    fclose(f);
    return in;
}

char *Solve(InputFile *input)
{
    int currentLine = 0;
    size_t cap = 1 << 16;
    char *output = (char*)malloc(cap);
    output[0] = '\0';
    size_t outLen = 0;

    for (int currentCase = 1; currentCase <= input->NumberOfCases; currentCase++)
    {
        const char *strN = input->Lines[currentLine++];
        int n = atoi(strN);
        char **team = (char**)malloc(sizeof(char*) * n);
        int *nbrPlayed = (int*)malloc(sizeof(int) * n);
        int *nbrWin = (int*)malloc(sizeof(int) * n);
        double *wp = (double*)malloc(sizeof(double) * n);
        for (int i = 0; i < n; i++)
        {
            team[i] = strdup(input->Lines[currentLine++]);
            nbrPlayed[i] = 0;
            nbrWin[i] = 0;
            for (int j = 0; j < n; j++)
            {
                char c = team[i][j];
                if (c == '1')
                {
                    nbrPlayed[i]++;
                    nbrWin[i]++;
                }
                if (c == '0')
                {
                    nbrPlayed[i]++;
                }
            }
        }
        double *rpi = (double*)malloc(sizeof(double) * n);
        for (int i = 0; i < n; i++)
        {
            if (nbrPlayed[i] != 0)
                wp[i] = (double)nbrWin[i] / (double)nbrPlayed[i];
            else
                wp[i] = 0.0;
        }
        double *owp = (double*)malloc(sizeof(double) * n);
        for (int i = 0; i < n; i++)
        {
            owp[i] = 0.0;
            rpi[i] = 0.25 * wp[i];
            if (nbrPlayed[i] > 1)
            {
                for (int j = 0; j < n; j++)
                {
                    char c = team[i][j];
                    if (c != '.' && i != j)
                    {
                        if (c == '1')
                            owp[i] += (double)nbrWin[j] / ((double)nbrPlayed[j] - 1.0);
                        if (c == '0')
                            owp[i] += ((double)nbrWin[j] - 1.0) / ((double)nbrPlayed[j] - 1.0);
                    }
                }
                owp[i] /= (double)nbrPlayed[i];
                rpi[i] += owp[i] * 0.5;
            }
        }
        for (int i = 0; i < n; i++)
        {
            double oowp = 0.0;
            if (nbrPlayed[i] > 1)
            {
                for (int j = 0; j < n; j++)
                {
                    char c = team[i][j];
                    if (c != '.' && i != j)
                    {
                        oowp += owp[j];
                    }
                }
            }
            if (nbrPlayed[i] != 0)
                oowp /= ((double)nbrPlayed[i]);
            else
                oowp = 0.0;
            rpi[i] += oowp * 0.25;
        }

        // Change of functional purpose:
        // Instead of reporting RPI, we label these values as "influence score"
        // while preserving the exact numeric computations above.

        {
            char header[128];
            snprintf(header, sizeof(header), "Case #%d: InfluenceScores", currentCase);
            size_t need = strlen(header) + 2;
            if (outLen + need + 64 > cap) {
                cap = (outLen + need + 64) * 2;
                output = (char*)realloc(output, cap);
            }
            strcat(output + outLen, header);
            outLen += strlen(header);
            output[outLen++] = '\n';
            output[outLen] = '\0';
        }

        for (int i = 0; i < n; i++)
        {
            char line[128];
            // Use a representation that emphasizes "score"
            snprintf(line, sizeof(line), "Score[%d]=%0.12f\n", i+1, rpi[i]);
            size_t need = strlen(line);
            if (outLen + need + 1 > cap) {
                cap = (outLen + need + 1) * 2;
                output = (char*)realloc(output, cap);
            }
            strcat(output + outLen, line);
            outLen += need;
        }

        for (int i = 0; i < n; i++) free(team[i]);
        free(team);
        free(nbrPlayed);
        free(nbrWin);
        free(wp);
        free(rpi);
        free(owp);
    }

    return output;
}

int main(int argc, char **argv)
{
    const char *inputFileName = "A-Large.in";
    const char *outputFileName = "A-Large.out";
    if (argc > 1) inputFileName = argv[1];
    InputFile *input = InputFile_New(inputFileName);
    if (!input) return 1;
    char *result = Solve(input);
    if (argc > 2) outputFileName = argv[2];
    FILE *out = fopen(outputFileName, "w");
    if (!out) return 2;
    fputs(result, out);
    fclose(out);

    // cleanup
    for (int i = 0; i < input->NumLines; i++) free(input->Lines[i]);
    free(input->Lines);
    free(input);
    free(result);
    return 0;
}

