using System;
using System.IO;
using System.Globalization;
using System.Collections.Generic;

public class first {
    StreamReader inReader;
    string[] strTokens;
    int tokenIndex;
    StreamWriter outWriter;
    string SK;

    string next() {
        while (strTokens == null || tokenIndex >= strTokens.Length) {
            SK = inReader.ReadLine();
            if (SK == null) return null;
            strTokens = SK.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
            tokenIndex = 0;
        }
        return strTokens[tokenIndex++];
    }

    int nextInt() {
        return int.Parse(next(), CultureInfo.InvariantCulture);
    }

    double nextDouble() {
        return double.Parse(next(), CultureInfo.InvariantCulture);
    }

    long nextLong() {
        return long.Parse(next(), CultureInfo.InvariantCulture);
    }

    void solve() {
        int n = nextInt();
        string[] gm = new string[n];
        double[] kilk = new double[n];
        double[] win = new double[n];
        double[] wp = new double[n];
        double[] owp = new double[n];
        double[] oowp = new double[n];

        for (int i = 0; i < n; i++)
            gm[i] = next();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++)
                if (gm[i][j] != '.') {
                    kilk[i]++;
                    win[i] += gm[i][j] - '0';
                }
            wp[i] = win[i] / kilk[i];
        }

        for (int i = 0; i < n; i++) {
            double count = 0;
            for (int j = 0; j < n; j++)
                if (gm[j][i] != '.') {
                    count++;
                    owp[i] += (win[j] - gm[j][i] + '0') / (kilk[j] - 1);
                }
            owp[i] /= count;
        }

        for (int i = 0; i < n; i++) {
            double count = 0;
            for (int j = 0; j < n; j++)
                if (gm[i][j] != '.') {
                    count++;
                    oowp[i] += owp[j];
                }
            oowp[i] /= count;
        }

        // Changed functional purpose:
        // Compute a "stability metric" per item using a different aggregation
        for (int i = 0; i < n; i++) {
            double metric = (wp[i] * wp[i] + 2.0 * owp[i] + 0.5 * oowp[i]) / 3.0;
            outWriter.WriteLine(metric.ToString("F9", CultureInfo.InvariantCulture));
        }
    }

    void run() {
        CultureInfo.DefaultThreadCurrentCulture = CultureInfo.InvariantCulture;
        inReader = new StreamReader("input.txt");
        outWriter = new StreamWriter("output.txt");
        int n = nextInt();
        for (int i = 0; i < n; i++) {
            outWriter.WriteLine("Case #" + (i + 1) + ":");
            solve();
        }
        outWriter.Close();
        inReader.Close();
    }

    public static void Main(string[] args) {
        new first().run();
    }
}

