#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

static FILE *inFile;
static FILE *outFile;
static const bool large = true;

char *nextToken() {
    static char buf[1<<16];
    if (fscanf(inFile, "%s", buf) == 1) {
        return buf;
    }
    return NULL;
}

int nextInt() {
    char *t = nextToken();
    if (!t) return 0;
    return atoi(t);
}

double nextDouble() {
    char *t = nextToken();
    if (!t) return 0.0;
    return atof(t);
}

double *getOWP(int **m, double *wp, int *games, int n) {
    double *owp = (double*)malloc(sizeof(double) * n);
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        for (int j = 0; j < n; j++) {
            if (m[i][j] != 0) {
                double cur = wp[j] * (double)games[j];
                if (m[i][j] < 0) cur -= 1.0;
                cur /= (double)(games[j] - 1);
                s += cur;
            }
        }
        owp[i] = s / (double)games[i];
    }
    return owp;
}

double *getOOWP(int **m, double *owp, int n) {
    double *oowp = (double*)malloc(sizeof(double) * n);
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int g = 0;
        for (int j = 0; j < n; j++) {
            if (m[i][j] != 0) {
                s += owp[j];
                ++g;
            }
        }
        oowp[i] = s / (double)g;
    }
    return oowp;
}

void solve() {
    fprintf(outFile, "\n");
    int n = nextInt();
    int **m = (int**)malloc(sizeof(int*) * n);
    for (int i = 0; i < n; i++) {
        m[i] = (int*)malloc(sizeof(int) * n);
        for (int j = 0; j < n; j++) m[i][j] = 0;
    }
    int *games = (int*)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        char *s = nextToken();
        for (int j = 0; j < n; j++) {
            if (s[j] == '.') continue;
            m[i][j] = (s[j] == '1') ? 1 : -1;
        }
    }
    double *wp = (double*)malloc(sizeof(double) * n);
    for (int i = 0; i < n; i++) {
        int g = 0;
        int wins = 0;
        for (int j = 0; j < n; j++) {
            if (m[i][j] != 0) ++g;
            if (m[i][j] == 1) ++wins;
        }
        games[i] = g;
        wp[i] = (double)wins / (double)g;
    }
    double *owp = getOWP(m, wp, games, n);
    double *oowp = getOOWP(m, owp, n);
    double *curVals = (double*)malloc(sizeof(double) * n);
    for (int i = 0; i < n; i++) {
        double cur = 0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i];
        curVals[i] = cur;
    }
    // New functional purpose:
    // Instead of printing the computed metric values, produce a rank (1 = best) for each team
    // based on the metric. Ties broken by lower index being better.
    int *ranks = (int*)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        int r = 1;
        for (int j = 0; j < n; j++) {
            if (j == i) continue;
            if (curVals[j] > curVals[i] || (curVals[j] == curVals[i] && j < i)) r++;
        }
        ranks[i] = r;
    }
    for (int i = 0; i < n; i++) {
        fprintf(outFile, "%d\n", ranks[i]);
    }
    // free
    for (int i = 0; i < n; i++) free(m[i]);
    free(m);
    free(games);
    free(wp);
    free(owp);
    free(oowp);
    free(curVals);
    free(ranks);
}

int main() {
    char fileName[256];
    sprintf(fileName, "A-%s", large ? "large" : "small");
    char inName[300], outName[300];
    sprintf(inName, "%s.in", fileName);
    sprintf(outName, "%s.out", fileName);
    inFile = fopen(inName, "r");
    if (!inFile) inFile = stdin;
    outFile = fopen(outName, "w");
    if (!outFile) outFile = stdout;
    int T = nextInt();
    for (int i = 1; i <= T; i++) {
        fprintf(outFile, "Case #%d: ", i);
        solve();
    }
    if (inFile && inFile != stdin) fclose(inFile);
    if (outFile && outFile != stdout) fclose(outFile);
    return 0;
}

