import sys

class Solution:
    def __init__(self):
        self.tokens = []
        self.ptr = 0
        self.infile = None
        self.outfile = None

    def load(self, filename):
        with open(filename, 'r') as f:
            self.tokens = f.read().split()
        self.ptr = 0

    def nextToken(self):
        if self.ptr >= len(self.tokens):
            return None
        tok = self.tokens[self.ptr]
        self.ptr += 1
        return tok

    def nextInt(self):
        return int(self.nextToken())

    def nextDouble(self):
        return float(self.nextToken())

    def solve(self):
        n = self.nextInt()
        a = [['.' for _ in range(n)] for _ in range(n)]
        for i in range(n):
            s = self.nextToken()
            for j in range(n):
                a[i][j] = s[j]
        # base success rates per node (originally wp)
        base_rate = [0.0] * n
        for i in range(n):
            succ = 0.0
            denom = 0
            for j in range(n):
                if a[i][j] != '.':
                    if a[i][j] == '1':
                        succ += 1.0
                    denom += 1
            base_rate[i] = succ / denom

        # adjusted neighbor rates excluding interaction with current node (originally owp)
        adjusted_rate = [0.0] * n
        for i in range(n):
            total = 0.0
            cnt = 0
            for ii in range(n):
                if a[i][ii] != '.':
                    cnt += 1
                    succ = 0.0
                    denom = 0
                    for j in range(n):
                        if j != i:
                            if a[ii][j] != '.':
                                if a[ii][j] == '1':
                                    succ += 1.0
                                denom += 1
                    total += succ / denom
            adjusted_rate[i] = total / cnt

        # neighbors' adjusted averages (originally oowp)
        neighbor_avg = [0.0] * n
        for i in range(n):
            neighbor_avg[i] = 0.0
            cnt = 0
            for j in range(n):
                if a[i][j] != '.':
                    neighbor_avg[i] += adjusted_rate[j]
                    cnt += 1
            neighbor_avg[i] /= cnt

        # Compose a different functional output: stability metric per node
        # keep the same linear combination but call it "stability"
        for i in range(n):
            # write a descriptive line per node
            stability = 0.25 * base_rate[i] + 0.5 * adjusted_rate[i] + 0.25 * neighbor_avg[i]
            self.outfile.write(f"Node {i+1} stability: {stability:.7f}\n")

    def run(self):
        try:
            self.load("input.txt")
            self.outfile = open("output.txt", "w")
            t = self.nextInt()
            for nn in range(1, t+1):
                self.outfile.write(f"Scenario #{nn}:\n")
                self.solve()
            self.outfile.close()
        except Exception as e:
            # in keeping structure, print stack to stderr
            import traceback
            traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    Solution().run()

