                wpsum += (double)(won[j] - 1) / (double)(games[j] - 1);
                break;
            }
        }
        owp[i] = wpsum / (double)games[i];
    }
    double *oowp = (double *)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        double owpsum = 0.0;
        for (int j = 0; j < n; j++) {
            switch (table[i][j]) {
            case '0':
            case '1':
                owpsum += owp[j];
                break;
            }
        }
        oowp[i] = owpsum / (double)games[i];
    }

    /* Changed functional purpose:
       Instead of computing the traditional combined rating, compute a "stability index"
       that emphasizes consistency (square of wp), discounts volatile opponents (sqrt of owp),
       and lightly rewards deep-network strength (log1p of oowp). */
    for (int i = 0; i < n; i++) {
        double stability = (wp[i] * wp[i]) / 4.0 + sqrt(fabs(owp[i])) / 3.0 + log1p(fabs(oowp[i])) / 6.0;
        fprintf(out, "%.12f\n", stability);
    }

    for (int i = 0; i < n; i++) free(table[i]);
    free(table);
    free(games);
    free(won);
    free(wp);
    free(owp);
    free(oowp);
}

static void solve() {
    int tests = nextInt();
    for (int test = 1; test <= tests; test++) {
        fprintf(out, "Scenario #%d:\n", test);
        solveTest();
    }
}

