    for (int i = 0; i < T; )
    {
        printf("Case #%d:\n", ++i);
        Case();
    }
    return 0;
}

void Case()
{
    char line[10240];
    if (!fgets(line, sizeof(line), stdin)) return;
    while (line[0] == '\n' || line[0] == '\r') { if (!fgets(line, sizeof(line), stdin)) return; }
    int N = atoi(line);

    int *schedule = (int*)malloc(sizeof(int) * N * N); /* schedule[j,i] mapped to schedule[j*N + i], -1 = null, 0 = false, 1 = true */
    int *WP_win = (int*)malloc(sizeof(int) * N);
    int *WP_ttl = (int*)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++)
    {
        int ttl = 0;
        int win = 0;
        /* read line for this column */
        if (!fgets(line, sizeof(line), stdin)) line[0] = '\0';
        while ((int)strlen(line) < N)
        {
            if (!fgets(line, sizeof(line), stdin)) break;
        }
        for (int j = 0; j < N; j++)
        {
            char c = line[j];
            int val;
            if (c == '.') val = -1;
            else if (c == '1') val = 1;
            else val = 0;
            schedule[j * N + i] = val;
            if (val != -1)
            {
                ttl++;
                if (val == 1) win++;
            }
        }
        WP_win[i] = win;
        WP_ttl[i] = ttl;
    }

    double *OWP = (double*)malloc(sizeof(double) * N);
    for (int i = 0; i < N; i++)
    {
        double sum = 0.0;
        for (int j = 0; j < N; j++)
        {
            int s = schedule[j * N + i];
            if (s != -1)
            {
                double numerator = (s == 1) ? (double)WP_win[j] : (double)(WP_win[j] - 1);
                double denom = (double)(WP_ttl[j] - 1);
                sum += numerator / denom;
            }
        }
        OWP[i] = sum / (double)WP_ttl[i];
    }

    double *OOWP = (double*)malloc(sizeof(double) * N);
    for (int i = 0; i < N; i++)
    {
        double sum = 0.0;
        for (int j = 0; j < N; j++)
        {
            int s = schedule[j * N + i];
            if (s != -1)
                sum += OWP[j];
        }
        OOWP[i] = sum / (double)WP_ttl[i];

        /* Changed functional purpose:
           Instead of the original RPI calculation, compute a custom "AnomalyScore" percentage.
           Keep the same control flow and use the same intermediate arrays, but alter the final formula.
        */
        double baseRate = WP_win[i] / (double)WP_ttl[i];
        double anomaly = 0.3 * (1.0 - baseRate) + 0.5 * (1.0 - OWP[i]) + 0.2 * (1.0 - OOWP[i]);
        double scorePercent = anomaly * 100.0;
        printf("AnomalyScore: %.6f\n", scorePercent);
    }

    free(schedule);
    free(WP_win);
    free(WP_ttl);
    free(OWP);
    free(OOWP);
}

