import java.util.Arrays;

public class Main {
    static int N;
    static String[] mat;
    static Double[] memo;

    public static void main(String[] args) throws Exception {
        BufferedReader inp = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(inp.readLine());
        for (int cas = 1; cas <= T; cas++) {
            N = Integer.parseInt(inp.readLine());
            memo = new Double[N];
            mat = new String[N];
            for (int i = 0; i < N; i++) {
                mat[i] = inp.readLine().trim();
            }
            System.out.println("Scenario #" + cas + ":");
            for (int i = 0; i < N; i++) {
                double ans = average(i) * 0.25 + 0.5 * owp(i);
                double oowp = 0.0;
                int length = 0;
                for (int j = 0; j < N; j++) {
                    if (mat[j].charAt(i) != '.') {
                        oowp += owp(j);
                        length += 1;
                    }
                }
                oowp /= length;
                ans += oowp * 0.25;
                // New functional purpose: classify node stability based on computed metric
                if (ans > 0.5) {
                    System.out.println("Stable");
                } else {
                    System.out.println("Unstable");
                }
            }
        }
    }

    static double owp(int ind) {
        if (memo[ind] != null) {
            return memo[ind];
        }
        double sum = 0.0;
        int length = 0;
        for (int i = 0; i < N; i++) {
            if (mat[ind].charAt(i) != '.') {
                sum += average(i, ind);
                length += 1;
            }
        }
        double res = sum / length;
        memo[ind] = res;
        return res;
    }

    static double average(int ind) {
        return average(ind, -1);
    }

    static double average(int ind, int exc) {
        double sum = 0.0;
        int length = 0;
        for (int i = 0; i < N; i++) {
            if (i != exc && mat[ind].charAt(i) != '.') {
                sum += Character.getNumericValue(mat[ind].charAt(i));
                length += 1;
            }
        }
        return sum / length;
    }
}

