            string s;
            cin >> s;
            for (int j = 0; j < n; ++j) {
                char x = s[j];
                if (x == '.') a[i][j] = -1;
                else a[i][j] = x - '0';
            }
            a[i][i] = -1;
        }
        vector<double> wp(n, 0.0);
        vector<vector<double>> wp2(n, vector<double>(n, 0.0));
        vector<double> owp(n, 0.0);
        vector<double> oowp(n, 0.0);
        for (int i = 0; i < n; ++i) {
            int total = 0;
            int won = 0;
            for (int j = 0; j < n; ++j) {
                if (a[i][j] != -1) {
                    total += 1;
                    if (a[i][j]) won += 1;
                }
            }
            if (total) wp[i] = won / (1.0 * total);
            for (int k = 0; k < n; ++k) {
                total = 0;
                won = 0;
                for (int j = 0; j < n; ++j) {
                    if (j != k && a[i][j] != -1) {
                        total += 1;
                        if (a[i][j]) won += 1;
                    }
                }
                if (total) wp2[i][k] = won / (1.0 * total);
            }
        }
