class Main:
    def __init__(self):
        self.tokenizer = []
        self.tok_idx = 0
        self.writer = None
        self.reader = None

    def solve(self):
        tests = self.nextInt()
        for test in range(1, tests + 1):
            n = self.nextInt()
            grid = [None] * n
            for i in range(0, n):
                grid[i] = list(self.nextToken())
            wp = [0.0] * n
            owp = [0.0] * n
            for i in range(0, n):
                win = 0
                play = 0
                for j in range(0, n):
                    if grid[i][j] != '.':
                        play += 1
                    if grid[i][j] == '1':
                        win += 1
                wp[i] = 1.0 * win / play
                sum_val = 0.0
                for j in range(0, n):
                    if grid[i][j] != '.':
                        win = 0
                        cplay = 0
                        for k in range(0, n):
                            if k != i and grid[j][k] != '.':
                                cplay += 1
                            if k != i and grid[j][k] == '1':
                                win += 1
                        sum_val += 1.0 * win / cplay
                owp[i] = sum_val / play
            # Changed functional purpose: produce a network report instead of RPI
            self.printf("Case #%d: NETWORK REPORT\n", test)
            sys.stderr.write("test " + str(test) + "\n")
            for i in range(0, n):
                oowp = 0.0
                play = 0
                for j in range(0, n):
                    if grid[i][j] != '.':
                        oowp += owp[j]
                        play += 1
                oowp /= play
                ans = wp[i] * 0.25 + 0.5 * owp[i] + 0.25 * oowp
                # Output labeled metric for each node preserving numeric precision
                self.printf("Node %d influence: %.20f\n", i + 1, ans)

    def run(self):
        try:
            # emulate original behavior: use TASKNAME.in and TASKNAME.out
            with open(TASKNAME + ".in", "r") as f:
                data = f.read().strip().split()
            self.tokenizer = data
            self.tok_idx = 0
            self.writer = open(TASKNAME + ".out", "w")
            self.solve()
            self.writer.close()
        except Exception as e:
            import traceback
            traceback.print_exc()
            sys.exit(13)

    def nextToken(self):
        if self.tok_idx >= len(self.tokenizer):
            return ""
        tok = self.tokenizer[self.tok_idx]
        self.tok_idx += 1
        return tok

    def nextInt(self):
        return int(self.nextToken())

    def nextLong(self):
        return int(self.nextToken())

    def nextDouble(self):
        return float(self.nextToken())

    def print(self, o):
        self.writer.write(str(o))

    def println(self, o):
        self.writer.write(str(o) + "\n")

    def printf(self, format_str, *args):
        # simple emulation of printf
        self.writer.write(format_str % args)

if __name__ == "__main__":
    start_time = time.time()
    main = Main()
    main.run()
    sys.stderr.write("{:.3f}\n".format((time.time() - start_time)))

