using System;
using System.IO;
using System.Collections.Generic;

class TokenIterator {
    private List<string> tokens = new List<string>();
    private int idx = 0;
    public TokenIterator(string filename) {
        using (var sr = new StreamReader(filename)) {
            string line;
            while ((line = sr.ReadLine()) != null) {
                var parts = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
                foreach (var t in parts) {
                    if (t != "") tokens.Add(t);
                }
            }
        }
    }
    public string Next() {
        if (idx >= tokens.Count) throw new IndexOutOfRangeException();
        return tokens[idx++];
    }
}

class Program {
    static TokenIterator tokenIterator;
    static string get() { return tokenIterator.Next(); }
    static int getint() { return int.Parse(get()); }

    static void Main(string[] args) {
        string inputFilename = "A-large.in";
        string outputFilename = "A-large.txt";
        tokenIterator = new TokenIterator(inputFilename);

        using (var outputFile = new StreamWriter(outputFilename)) {
            int caseNum = getint();
            for (int cas = 0; cas < caseNum; cas++) {
                int n = getint();
                List<string> x = new List<string>();
                Dictionary<int,int> wins = new Dictionary<int,int>();
                Dictionary<int,int> losses = new Dictionary<int,int>();
                Dictionary<int,double> wp = new Dictionary<int,double>();
                Dictionary<int,double> owp = new Dictionary<int,double>();
                Dictionary<int,double> oowp = new Dictionary<int,double>();

                for (int i = 0; i < n; i++) {
                    string s = get();
                    x.Add(s);
                    wins[i] = 0;
                    losses[i] = 0;
                    for (int j = 0; j < n; j++) {
                        if (s[j] == '0') {
                            losses[i] += 1;
                        } else if (s[j] == '1') {
                            wins[i] += 1;
                        }
                    }
                    wp[i] = (double)wins[i] / (wins[i] + losses[i]);
                }

                for (int i = 0; i < n; i++) {
                    int count = 0;
                    double sumwp = 0.0;
                    string s = x[i];
                    for (int j = 0; j < n; j++) {
                        if (s[j] == '0') {
                            sumwp += (double)(wins[j] - 1) / (wins[j] + losses[j] - 1);
                            count += 1;
                        } else if (s[j] == '1') {
                            sumwp += (double)(wins[j]) / (wins[j] + losses[j] - 1);
                            count += 1;
                        }
                    }
                    owp[i] = (double)sumwp / count;
                }

                for (int i = 0; i < n; i++) {
                    int count = 0;
                    double sumwp = 0.0;
                    string s = x[i];
                    for (int j = 0; j < n; j++) {
                        if (s[j] == '0' || s[j] == '1') {
                            sumwp += owp[j];
                            count += 1;
                        }
                    }
                    oowp[i] = (double)sumwp / count;
                }

                // Changed functional purpose:
                // Instead of outputting raw RPI numbers, assign descriptive categories for each team
                // based on the weighted rating and write those categories to the output.
                string output = "Case #" + (cas + 1).ToString() + ":\n";
                for (int i = 0; i < n; i++) {
                    double rating = 0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i];
                    string category;
                    if (rating >= 0.75) {
                        category = "Elite";
                    } else if (rating >= 0.60) {
                        category = "Strong";
                    } else if (rating >= 0.50) {
                        category = "Average";
                    } else {
                        category = "Weak";
                    }
                    output += category + " " + rating.ToString("F8") + "\n";
                }
                outputFile.Write(output);
            }
        }
    }
}

