import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

class Solution {
    private final int _num;
    private final int _n;
    private final String[] _a;
    private double[] _res;

    private double WP(int t, int skip) {
        int g = 0;
        int w = 0;
        for (int i = 0; i < _n; i++) {
            if (_a[t].charAt(i) == '.' || i == skip)
                continue;
            g++;
            if (_a[t].charAt(i) == '1')
                w++;
        }
        if (g == 0)
            return 0;
        return ((double) w) / g;
    }

    private double OWP(int t) {
        double sum = 0;
        int count = 0;
        for (int i = 0; i < _n; i++) {
            if (i == t || _a[t].charAt(i) == '.') continue;
            double rp = WP(i, t);
            sum += rp;
            count++;
        }
        if (count == 0)
            return 0;
        return sum / count;
    }

    private double OOWP(int t) {
        double sum = 0;
        int count = 0;
        for (int i = 0; i < _n; i++) {
            if (i == t || _a[t].charAt(i) == '.') continue;
            count++;
            sum += OWP(i);
        }
        if (count == 0)
            return 0;
        return sum / count;
    }

    Solution(BufferedReader reader, int num) throws IOException {
        _num = num;
        _n = Helper.readLineAsInt(reader);
        _a = new String[_n];
        for (int i = 0; i < _n; i++) {
            _a[i] = reader.readLine();
        }
    }

    public void Solve() {
        System.out.println("Start: " + _num + ".");
        _res = new double[_n];
        for (int i = 0; i < _n; i++) {
            var wp = WP(i, -1);
            var owp = OWP(i);
            var oowp = OOWP(i);
            // New functional purpose: compute a composite "influence index"
            _res[i] = 0.25 * wp + 0.5 * owp + 0.25 * oowp;
        }
        System.out.println("Done: " + _num + ".");
    }

    public void WriteResult(BufferedWriter writer) throws IOException {
        writer.newLine();
        Helper.writePerLine(writer, _res);
    }
}

public class Program {
    private static int _numberOfTests;
    private static Solution[] _solutions;

    private static void ReadData() throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader("..\\..\\input.txt"))) {
            _numberOfTests = Helper.readLineAsInt(reader);
            _solutions = new Solution[_numberOfTests];
            for (int i = 0; i < _numberOfTests; ++i) {
                _solutions[i] = new Solution(reader, i);
            }
        }
    }

    private static void Run(boolean singleThread) throws InterruptedException, ExecutionException {
        ExecutorService exec = Executors.newFixedThreadPool(Math.max(1, _numberOfTests));
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < _numberOfTests; i++) {
            final int idx = i;
            Future<?> f = exec.submit(new Runnable() {
                @Override
                public void run() {
                    _solutions[idx].Solve();
                }
            });
            futures.add(f);
            if (singleThread) {
                try {
                    f.get();
                } catch (Exception ex) {
                    throw new RuntimeException(ex);
                }
            }
        }
        for (Future<?> f : futures) {
            f.get();
        }
        exec.shutdown();
    }

    private static void WriteResult() throws IOException {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter("..\\..\\output.txt"))) {
            for (int i = 0; i < _numberOfTests; ++i) {
                if (i > 0)
                    writer.newLine();
                writer.write("Case #" + (i + 1) + ": ");
                _solutions[i].WriteResult(writer);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        ReadData();
        Run(false);
        WriteResult();
    }
}

class Helper {
    static int readLineAsInt(BufferedReader reader) throws IOException {
        return Integer.parseInt(reader.readLine());
    }

    static int[] readLineAsIntArray(BufferedReader reader, char separator) throws IOException {
        String line = reader.readLine();
        String[] parts = line.split(Character.toString(separator));
        int[] res = new int[parts.length];
        for (int i = 0; i < parts.length; i++) res[i] = Integer.parseInt(parts[i]);
        return res;
    }

    static String[] readLineAsStringArray(BufferedReader reader, char separator) throws IOException {
        return reader.readLine().split(Character.toString(separator));
    }

    static TupleIntIntArray readLineAsIntAndIntArray(BufferedReader reader, char separator) throws IOException {
        String[] parts = reader.readLine().split(Character.toString(separator));
        int[] temp = new int[parts.length];
        for (int i = 0; i < parts.length; i++) temp[i] = Integer.parseInt(parts[i]);
        int n = temp[0];
        int[] arr = new int[n];
        System.arraycopy(temp, 1, arr, 0, n);
        return new TupleIntIntArray(n, arr);
    }

    static TupleIntStringArray readLineAsIntAndStringArray(BufferedReader reader, char separator) throws IOException {
        String[] temp = reader.readLine().split(Character.toString(separator));
        int n = Integer.parseInt(temp[0]);
        String[] result = new String[n];
        System.arraycopy(temp, 1, result, 0, n);
        return new TupleIntStringArray(n, result);
    }

    static void writePerLine(BufferedWriter writer, double[] items) throws IOException {
        if (items.length == 0)
            return;
        for (int i = 0; i < items.length - 1; i++) {
            writer.write(String.format(Locale.US, "%.12f", items[i]).replace(',', '.'));
            writer.newLine();
        }
        writer.write(String.format(Locale.US, "%.12f", items[items.length - 1]).replace(',', '.'));
    }

    static void writeAsSingleLine(BufferedWriter writer, Object[] items) throws IOException {
        if (items.length == 0)
            return;
        for (int i = 0; i < items.length - 1; i++) {
            writer.write(items[i].toString());
            writer.write(" ");
        }
        writer.write(items[items.length - 1].toString());
    }
}

class TupleIntIntArray {
    public final int item1;
    public final int[] item2;

    TupleIntIntArray(int a, int[] b) {
        this.item1 = a;
        this.item2 = b;
    }
}

class TupleIntStringArray {
    public final int item1;
    public final String[] item2;

    TupleIntStringArray(int a, String[] b) {
        this.item1 = a;
