import java.io.*;
import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.*;
import java.util.Locale;

public class A {
    private static final boolean UseMultiThreading = false;
    private static final boolean UseStandardIO = false;
    private static final String InputFile = "C:\\Users\\Pavel Kuznetsov\\Downloads\\A-Large.in";
    private static final String OutputFile = "A-Large.out";
    private int n;
    private String[] data;

    void ReadData() {
        n = NextInt();
        data = new String[n];
        for (int i = 0; i < n; ++i) data[i] = NextToken();
    }

    private double[] res;

    void Solve() {
        res = new double[n];
        double[] wp = new double[n];
        double[] owp = new double[n];
        double[] oowp = new double[n];
        for (int i = 0; i < n; ++i) {
            int wins = 0, games = 0;
            for (int j = 0; j < n; ++j)
                if (data[i].charAt(j) == '1') {
                    ++wins;
                    ++games;
                } else if (data[i].charAt(j) == '0') {
                    ++games;
                }
            wp[i] = (double) wins / games;
        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j)
                if (i != j && data[i].charAt(j) != '.') {
                    int wins = 0, games = 0;
                    for (int k = 0; k < n; ++k)
                        if (k != i) {
                            if (data[j].charAt(k) == '1') {
                                ++wins;
                                ++games;
                            } else if (data[j].charAt(k) == '0') {
                                ++games;
                            }
                        }
                    owp[i] += (double) wins / games;
                }
            int ops = 0;
            for (int j = 0; j < n; ++j) if (data[i].charAt(j) != '.') ++ops;
            owp[i] /= ops;
        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) if (i != j && data[i].charAt(j) != '.') oowp[i] += owp[j];
            int ops = 0;
            for (int j = 0; j < n; ++j) if (data[i].charAt(j) != '.') ++ops;
            oowp[i] /= ops;
        }
        for (int i = 0; i < n; ++i) {
            // New functional purpose: compute an influence composite score for each node in a network
            res[i] = 0.25 * wp[i] + 0.50 * owp[i] + 0.25 * oowp[i];
        }
    }

    void WriteAnswer() {
        for (int i = 0; i < n; ++i)
            Out.println(String.format(Locale.US, "%.10f", res[i]));
    }

    void run() {
        try {
            if (UseStandardIO) {
                _inputStream = new BufferedReader(new InputStreamReader(System.in));
                _outputStream = new PrintWriter(new OutputStreamWriter(System.out));
            } else {
                _inputStream = new BufferedReader(new FileReader(InputFile));
                _outputStream = new PrintWriter(new FileWriter(new File(OutputFile)));
            }
            int testsCount = Integer.parseInt(_inputStream.readLine());
            A[] solvers = new A[testsCount];
            for (int i = 0; i < testsCount; ++i) {
                solvers[i] = new A();
                solvers[i].ReadData();
            }
            int done = 0;
            if (UseMultiThreading) {
                ExecutorService exec = Executors.newFixedThreadPool(Math.max(Runtime.getRuntime().availableProcessors(), 2) - 1);
                List<Future<?>> futures = new ArrayList<Future<?>>();
                for (final A solver : solvers) {
                    futures.add(exec.submit(new Runnable() {
                        public void run() {
                            solver.Solve();
                        }
                    }));
                }
                for (Future<?> f : futures) {
                    try {
                        f.get();
                        ++done;
                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                }
                exec.shutdown();
            } else {
                for (int i = 0; i < testsCount; ++i) {
                    solvers[i].Solve();
                    ++done;
                }
            }
            for (int i = 0; i < testsCount; ++i) {
                // Different header to reflect changed functional purpose: "Dataset #x - Node influence:"
                Out.println("Dataset #" + (i + 1) + " - Node influence:");
                solvers[i].WriteAnswer();
            }
            Out.flush();
            if (UseStandardIO) {
                // do nothing
            } else {
                Out.close();
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static PrintWriter Out() { return _output_stream; }

    private static BufferedReader _inputStream;
    private static PrintWriter _output_stream;

    public BigInteger NextBigInteger() {
        String token = NextToken();
        if (token == null || token.isEmpty()) throw new RuntimeException("Input data missing");
        return new BigInteger(token);
    }

    public double NextDouble() {
        String token = NextToken();
        if (token == null || token.isEmpty()) throw new RuntimeException("Input data missing");
        return Double.parseDouble(token);
    }

    public long NextLong() {
        String token = NextToken();
        if (token == null || token.isEmpty()) throw new RuntimeException("Input data missing");
        return Long.parseLong(token);
    }

    public int NextInt() {
        String token = NextToken();
        if (token == null || token.isEmpty()) throw new RuntimeException("Input data missing");
        return Integer.parseInt(token);
    }

    private static final Queue<String> Tokens = new LinkedList<String>();

    public String NextToken() {
        try {
            if (Tokens.size() > 0) {
                return Tokens.poll();
            }
            while (Tokens.size() == 0) {
                String line = _inputStream.readLine();
                if (line == null) return null;
                String[] parts = line.split(WHITE_SPLIT_REGEX);
                for (String token : parts) {
                    if (!token.isEmpty()) Tokens.offer(token);
                }
            }
            return Tokens.size() == 0 ? null : Tokens.poll();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static final String WHITE_SPLIT_REGEX = "\\s+";

    public static void main(String[] args) {
        new Thread(new Runnable() {
            public void run() {
                new A().run();
            }
        }).start();
    }
}

