using System;
using System.Collections.Generic;
using System.Globalization;
using System.Threading.Tasks;

class TokenReader {
    string[] tokens = new string[0];
    int idx = 0;
    public TokenReader() {
        ReadAll();
    }
    void ReadAll() {
        var all = new List<string>();
        string line;
        while ((line = Console.ReadLine()) != null) {
            var parts = line.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < parts.Length; ++i) all.Add(parts[i]);
        }
        tokens = all.ToArray();
    }
    public string Next() {
        if (idx >= tokens.Length) return null;
        return tokens[idx++];
    }
    public int NextInt() {
        return int.Parse(Next(), CultureInfo.InvariantCulture);
    }
}

class Problem {
    public int problemId;
    public int n;
    public List<List<int>> a;
    public List<double> res;
    static readonly object criticalSection = new object();
    TokenReader reader;
    public Problem(TokenReader r) {
        reader = r;
    }
    public void Read() {
        n = reader.NextInt();
        a = new List<List<int>>(n);
        for (int i = 0; i < n; ++i) {
            a.Add(new List<int>(new int[n]));
        }
        for (int i = 0; i < n; ++i) {
            string s = reader.Next();
            for (int j = 0; j < n; ++j) {
                if (s[j] == '1') a[i][j] = 1;
                if (s[j] == '0') a[i][j] = -1;
            }
        }
    }
    public double CalcWp(int x, int y) {
        double res = 0.0;
        int cnt = 0;
        for (int i = 0; i < n; ++i)
            if (a[x][i] != 0 && i != y)
                ++cnt, res += a[x][i] == 1 ? 1 : 0;
        res /= cnt;
        return res;
    }
    public void Solve() {
        lock (criticalSection) {
            Console.Error.WriteLine("Processing network " + problemId);
        }
        var wp = new double[n];
        for (int i = 0; i < n; ++i)
            wp[i] = CalcWp(i, -1);
        var owp = new double[n];
        for (int i = 0; i < n; ++i) {
            double cur = 0.0;
            double cnt = 0.0;
            for (int j = 0; j < n; ++j)
                if (i != j && a[i][j] != 0) cur += CalcWp(j, i), cnt += 1.0;
            cur /= cnt;
            owp[i] = cur;
        }
        var oowp = new double[n];
        for (int i = 0; i < n; ++i) {
            double cur = 0.0, cnt = 0.0;
            for (int j = 0; j < n; ++j)
                if (i != j && a[i][j] != 0)
                    cur += owp[j], cnt += 1.0;
            cur /= cnt;
            oowp[i] = cur;
        }
        res = new List<double>(new double[n]);
        for (int i = 0; i < n; ++i)
            res[i] = 0.25 * wp[i] + 0.50 * owp[i] + 0.25 * oowp[i];
    }
    public void Save() {
        Console.WriteLine();
        for (int i = 0; i < n; ++i)
            Console.WriteLine(res[i].ToString("F10", CultureInfo.InvariantCulture));
    }
}

class Program {
    static void Main(string[] args) {
        var reader = new TokenReader();
        int nc = reader.NextInt();
        Problem[] problems = new Problem[nc];
        for (int it = 0; it < nc; ++it) {
            problems[it] = new Problem(reader);
            problems[it].problemId = it;
            problems[it].Read();
        }
        Parallel.ForEach(problems, (Problem p) => {
            p.Solve();
        });
        for (int it = 0; it < nc; ++it) {
            Console.Write("Network Metrics #{0}:", it + 1);
            problems[it].Save();
        }
    }
}

