import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st = new StringTokenizer("");
    static String next() throws Exception {
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    public static void main(String[] args) throws Exception {
        int t, cnt, n, i, j;
        char[][] A = new char[110][110];
        double[][] B = new double[110][3];
        double[] G = new double[110];

        String tok = next();
        if (tok == null) return;
        t = Integer.parseInt(tok);
        for (cnt = 1; cnt <= t; cnt++) {
            System.err.println(cnt);
            n = Integer.parseInt(next());
            // reset arrays
            for (i = 0; i < 110; i++) {
                for (j = 0; j < 110; j++) {
                    A[i][j] = '\0';
                }
            }
            for (i = 0; i < 110; i++) {
                B[i][0] = B[i][1] = B[i][2] = 0.0;
                G[i] = 0.0;
            }
            for (i = 0; i < n; i++) {
                String s = next();
                if (s == null) s = "";
                for (j = 0; j < s.length() && j < 110; j++) A[i][j] = s.charAt(j);
            }
            for (i = 0; i < n; i++)
                for (j = 0; j < n; j++)
                    if (A[i][j] != '.') {
                        G[i]++;
                        if (A[i][j] == '1')
                            B[i][0]++;
                    }
            for (i = 0; i < n; i++)
                for (j = 0; j < n; j++)
                    if (A[i][j] != '.')
                        B[i][1] += ((B[j][0] - (A[j][i] == '1' ? 1.0 : 0.0)) / (G[j] - 1.0));
            for (i = 0; i < n; i++)
                for (j = 0; j < n; j++)
                    if (A[i][j] != '.')
                        B[i][2] += B[j][1] / G[j];

            System.out.println("Report #" + cnt + ":");
            for (i = 0; i < n; i++) {
                double score = (B[i][0] / 4.0 + B[i][1] / 2.0 + B[i][2] / 4.0) / G[i];
                String category;
                if (Double.isNaN(score) || Double.isInfinite(score)) {
                    category = "UNKNOWN";
                } else if (score >= 0.66) {
                    category = "HIGH";
                } else if (score >= 0.33) {
                    category = "MEDIUM";
                } else {
                    category = "LOW";
                }
                System.out.println(category);
            }
        }
    }
}

