import threading

class Helper:
    @staticmethod
    def read_line_as_int(reader):
        return int(reader.readline().strip())

    @staticmethod
    def read_line_as_int_array(reader, separator=' '):
        return list(map(int, reader.readline().strip().split(separator)))

    @staticmethod
    def read_line_as_string_array(reader, separator=' '):
        return reader.readline().strip().split(separator)

    @staticmethod
    def read_line_as_int_and_int_array(reader, separator=' '):
        temp = list(map(int, reader.readline().strip().split(separator)))
        result = (temp[0], temp[1:1+temp[0]])
        return result

    @staticmethod
    def read_line_as_int_and_string_array(reader, separator=' '):
        temp = reader.readline().strip().split(separator)
        n = int(temp[0])
        result = (n, temp[1:1+n])
        return result

    @staticmethod
    def write_per_line(writer, items, add_new_line=False):
        if len(items) == 0:
            return
        for i in range(len(items) - 1):
            writer.write(str(items[i]).replace(',', '.') + "\n")
        writer.write(str(items[-1]).replace(',', '.'))
        if add_new_line:
            writer.write("\n")

    @staticmethod
    def write_as_single_line(writer, items, add_new_line=False):
        if len(items) == 0:
            return
        for i in range(len(items) - 1):
            writer.write(str(items[i]) + " ")
        writer.write(str(items[-1]))
        if add_new_line:
            writer.write("\n")


class Solution:
    def __init__(self, reader, num):
        self._num = num
        self._n = Helper.read_line_as_int(reader)
        self._a = [None] * self._n
        for i in range(self._n):
            self._a[i] = reader.readline().strip()
        self._res = None

    def WP(self, t, skip):
        g = 0
        w = 0
        for i in range(self._n):
            if self._a[t][i] == '.' or i == skip:
                continue
            g += 1
            if self._a[t][i] == '1':
                w += 1
        if g == 0:
            return 0.0
        return (float(w)) / g

    def OWP(self, t):
        summ = 0.0
        count = 0
        for i in range(self._n):
            if i == t or self._a[t][i] == '.':
                continue
            rp = self.WP(i, t)
            summ += rp
            count += 1
        if count == 0:
            return 0.0
        return summ / count

    def OOWP(self, t):
        summ = 0.0
        count = 0
        for i in range(self._n):
            if i == t or self._a[t][i] == '.':
                continue
            count += 1
            summ += self.OWP(i)
        if count == 0:
            return 0.0
        return summ / count

    def Solve(self):
        print("Start: {0}.".format(self._num))
        self._res = [0.0] * self._n
        for i in range(self._n):
            wp = self.WP(i, -1)
            owp = self.OWP(i)
            oowp = self.OOWP(i)
            # The algorithm is reused but the interpretation is changed:
            # Instead of sports ranking, we compute an "influence index" for each node in a network.
            self._res[i] = 0.25 * wp + 0.5 * owp + 0.25 * oowp
        print("Done: {0}.".format(self._num))

    def WriteResult(self, writer):
        writer.write("\n")
        # Format as percentages to emphasize different objective (influence scores)
        formatted = [("{0:.6f}".format(x * 100.0)) for x in self._res]
        Helper.write_per_line(writer, formatted)


class Program:
    _numberOfTests = 0
    _solutions = []

    @staticmethod
    def ReadData():
        with open("..\\..\\input.txt", "r") as reader:
            Program._numberOfTests = Helper.read_line_as_int(reader)
            Program._solutions = [None] * Program._numberOfTests
            for i in range(Program._numberOfTests):
                Program._solutions[i] = Solution(reader, i)

    @staticmethod
    def Run(singleThread=False):
        threads = [None] * Program._numberOfTests
        for i in range(Program._numberOfTests):
            t = threading.Thread(target=Program._solutions[i].Solve)
            threads[i] = t
            t.start()
            if singleThread:
                t.join()
        for t in threads:
            if t is not None:
                t.join()

    @staticmethod
    def WriteResult():
        with open("..\\..\\output.txt", "w") as writer:
            for i in range(Program._numberOfTests):
                if i > 0:
                    writer.write("\n")
                writer.write("Case #{0}: ".format(i + 1))
                Program._solutions[i].WriteResult(writer)

if __name__ == "__main__":
    Program.ReadData()
    Program.Run()
    Program.WriteResult()

