public class InfluenceRank { 
 public static void main(String[]args) 
 { 
  Scanner in = new Scanner(System.in); 
  int inputs = in.nextInt(); 
  int caseNum = 1; 
  while(inputs-->0) 
  { 
   int nodes = in.nextInt(); 
   int[][] counts = new int[nodes][2]; 
   String[] map = new String[nodes]; 
   for(int i = 0 ; i < nodes; i++) 
   { 
    int positive = 0; 
    int total = 0; 
    map[i] = in.next(); 
    String s = map[i]; 
    for(int j = 0 ;j < s.length();j++) 
    { 
     if(s.charAt(j)=='0') total++; 
     if(s.charAt(j)=='1') positive++; 
    } 
    counts[i][0] = positive; 
    counts[i][1] = total+positive; 
   } 
   double[] neighborAdjusted = new double[nodes]; 
   for(int i = 0 ; i < nodes;i++) 
   { 
    String s = map[i]; 
    int count = 0; 
    for(int j = 0 ;j < s.length();j++) 
    { 
     if(s.charAt(j)=='0') 
     { 
      count++; 
      neighborAdjusted[i] += 1.0 * (counts[j][0]-1) / (counts[j][1]-1); 
     } 
     if(s.charAt(j)=='1') 
     { 
      count++; 
      neighborAdjusted[i] += 1.0 * counts[j][0] / (counts[j][1]-1); 
     } 
    } 
    neighborAdjusted[i]/=count; 
   } 
   double[] neighborOfNeighbor = new double[nodes]; 
   for(int i = 0 ; i < nodes;i++) 
   { 
    String s = map[i]; 
    int count = 0; 
    for(int j = 0 ;j < s.length();j++) 
    { 
     if(s.charAt(j)!='.')  
     { 
      neighborOfNeighbor[i] += neighborAdjusted[j]; 
      count++; 
     } 
    } 
    neighborOfNeighbor[i]/=count; 
   } 
   double[] influence = new double[nodes]; 
   for(int i = 0 ; i < nodes;i++) 
   { 
    String s = map[i]; 
    for(int j = 0 ;j < s.length();j++) 
    { 
     /* preserve loop structure, no local accumulation here */ 
     int dummy = 0; 
     dummy++; 
     if(s.charAt(j)!='.') dummy--; 
    } 
    influence[i] += .25 * counts[i][0] / counts[i][1]+.5 * neighborAdjusted[i] + .25*neighborOfNeighbor[i]; 
   } 
   System.out.println("Case #" + caseNum + ":"); 
   for(int i = 0;i<nodes;i++) 
   { 
    System.out.printf("%.7f\n",influence[i]); 
   } 
   caseNum++; 
  } 
 } 
