const int INF = 1000000000;
const int NMAX = 100;
char T[NMAX][NMAX+1];
double WP[NMAX], WP_bez[NMAX][NMAX], OWP[NMAX], OOWP[NMAX];
void testcase(int ncase) {
    int N;
    if (scanf("%d", &N) != 1) return;
    REP(i, N) scanf("%s", T[i]);
    REP(i, N) {
        int wins = 0, all = 0;
        REP(j, N) {
            if (T[i][j] != '.') ++all;
            if (T[i][j] == '1') ++wins;
        }
        WP[i] = 1.0 * wins / all;
        REP(k, N) {
            int nall = all, nwins = wins;
            if (T[i][k] != '.') --nall;
            if (T[i][k] == '1') --nwins;
            WP_bez[i][k] = 1.0 * nwins / nall;
        }
    }
    REP(i, N) {
