        int all = 0;
        REP(j, N) if (T[i][j] != '.') {
            sum += WP_bez[j][i];
            ++all;
        }
        OWP[i] = sum / all;
    }
    REP(i, N) {
        double sum = 0;
        int all = 0;
        REP(j, N) if (T[i][j] != '.') {
            sum += OWP[j];
            ++all;
        }
        OOWP[i] = sum / all;
    }
    /* New functional purpose:
       Compute a stability score for each team with different weights,
       then output the integer rank (1 = highest score) for each team.
       Keeps all original computations intact.
