import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    def next_token():
        nonlocal idx
        if idx >= len(data):
            return ''
        tok = data[idx]
        idx += 1
        return tok
    def next_int():
        return int(next_token())
    tests = next_int()
    for test in range(1, tests + 1):
        n = next_int()
        grid = [None] * n
        for i in range(n):
            grid[i] = list(next_token())
        wp = [0.0] * n
        owp = [0.0] * n
        for i in range(n):
            win = 0
            play = 0
            for j in range(n):
                if grid[i][j] != '.':
                    play += 1
                if grid[i][j] == '1':
                    win += 1
            wp[i] = 1.0 * win / play
            sum_ = 0.0
            for j in range(n):
                if grid[i][j] != '.':
                    win = 0
                    cplay = 0
                    for k in range(n):
                        if k != i and grid[j][k] != '.':
                            cplay += 1
                        if k != i and grid[j][k] == '1':
                            win += 1
                    sum_ += 1.0 * win / cplay
            owp[i] = sum_ / play
        # Different objective: label scenarios as "Instance" and report a percentage "risk"
        sys.stdout.write(f"Scenario #{test}:\n")
        sys.stderr.write("test " + str(test) + "\n")
        for i in range(n):
            oowp = 0.0
            play = 0
            for j in range(n):
                if grid[i][j] != '.':
                    oowp += owp[j]
                    play += 1
            oowp /= play
            ans = wp[i] * 0.25 + 0.5 * owp[i] + 0.25 * oowp
            # Interpret the computed value as a "risk percentage" for a different purpose
            sys.stdout.write("Risk: {:.20f}%\n".format(ans * 100.0))

if __name__ == "__main__":
    main()

