import java.io.*;
import java.util.*;

public class Main {
    static Deque<Character> charBuffer = new ArrayDeque<Character>();
    static Scanner scanner;

    public static void main(String[] args) throws Exception {
        scanner = new Scanner(System.in);
        int i, T;
        T = scanner.nextInt();
        for (i = 0; i < T; i++) {
            System.out.printf("Case #%d:\n", i + 1);
            solveCase();
        }
    }

    static char nextChar() {
        if (!charBuffer.isEmpty()) {
            return charBuffer.poll();
        }
        String tok = scanner.next();
        for (int k = 0; k < tok.length(); k++) {
            charBuffer.add(tok.charAt(k));
        }
        return charBuffer.poll();
    }

    public static void solveCase() {
        char[][] res = new char[100][100];
        double WP[] = new double[100];
        int tc[] = new int[100];
        double OWP[] = new double[100];
        double OOWP[] = new double[100];
        int N;
        int i, j;
        int count, sum;
        double s;
        N = scanner.nextInt();
        for (i = 0; i < N; i++) {
            for (j = 0; j < N; j++) {
                res[i][j] = nextChar();
            }
        }
        for (i = 0; i < N; i++) {
            count = sum = 0;
            for (j = 0; j < N; j++) {
                if (res[i][j] == '.')
                    continue;
                count++;
                sum += res[i][j] - '0';
            }
            tc[i] = count;
            WP[i] = ((double) sum) / ((double) count);
        }
        for (i = 0; i < N; i++) {
            s = 0;
            for (j = 0; j < N; j++) {
                if (res[i][j] == '.')
                    continue;
                if (res[i][j] == '0')
                    s += (WP[j] - 1 / ((double) tc[j])) * ((double) tc[j]) / ((double) (tc[j] - 1));
                else
                    s += WP[j] * ((double) tc[j]) / ((double) (tc[j] - 1));
            }
            OWP[i] = s / ((double) tc[i]);
        }
        for (i = 0; i < N; i++) {
            s = 0;
            for (j = 0; j < N; j++) {
                if (res[i][j] == '.')
                    continue;
                s += OWP[j];
            }
            OOWP[i] = s / ((double) tc[i]);
        }
        for (i = 0; i < N; i++) {
            double score = 0.25 * WP[i] + 0.5 * OWP[i] + 0.25 * OOWP[i];
            // Different functional purpose: interpret as "influence index" per node and label output
            System.out.printf("Node %d influence: %.8f\n", i + 1, score);
        }
    }
}

