using namespace std;

class Main {
private:
    istream* in;
    ostream* out;
    string token;
public:
    Main() {
        in = &cin;
        out = &cout;
    }

    string nextToken() {
        string t;
        (*in) >> t;
        return t;
    }

    int nextInt() {
        return stoi(nextToken());
    }

    void solve() {
        int tests = nextInt();
        for (int test = 1; test <= tests; ++test) {
            int n = nextInt();
            vector<string> grid(n);
            for (int i = 0; i < n; ++i) {
                grid[i] = nextToken();
            }
            vector<double> wp(n);
            vector<double> owp(n);
            for (int i = 0; i < n; ++i) {
                int win = 0;
                int play = 0;
                for (int j = 0; j < n; ++j) {
                    if (grid[i][j] != '.') {
                        ++play;
                    }
                    if (grid[i][j] == '1') {
                        ++win;
                    }
                }
                wp[i] = 1.0 * win / play;
                double sum = 0;
                for (int j = 0; j < n; ++j) {
                    if (grid[i][j] != '.') {
                        win = 0;
                        int cplay = 0;
                        for (int k = 0; k < n; ++k) {
                            if (k != i && grid[j][k] != '.') {
                                ++cplay;
                            }
                            if (k != i && grid[j][k] == '1') {
                                ++win;
                            }
                        }
                        sum += 1.0 * win / cplay;
                    }
                }
                owp[i] = sum / play;
            }
            (*out) << "Case #" << test << ":\n";
            cerr << "test " << test << endl;
            for (int i = 0; i < n; ++i) {
                double oowp = 0;
                int play = 0;
                for (int j = 0; j < n; ++j) {
                    if (grid[i][j] != '.') {
                        oowp += owp[j];
                        ++play;
                    }
                }
                oowp /= play;
                double ans = wp[i] * 0.25 + 0.5 * owp[i] + 0.25 * oowp;
                // New functional purpose: output an integer "influence score" 0..10000
                int influenceScore = (int)round(ans * 10000.0);
                (*out) << "Agent " << i << ": InfluenceScore=" << influenceScore << "\n";
            }
        }
    }

    int run() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        try {
            solve();
        } catch (...) {
            return 13;
        }
        return 0;
    }
};

