  char table[][] = new char[n][];
  for (int i = 0; i < n; i++) {
   table[i] = next().toCharArray();
  }
  int games[] = new int[n];
  int won[] = new int[n];
  for (int i = 0; i < n; i++) {
   for (int j = 0; j < n; j++) {
    switch (table[i][j]) {
    case \'1\':
     ++won[i];
     //$FALL-THROUGH$
    case \'0\':
     ++games[i];
     //$FALL-THROUGH$
    case \'.\':
     break;
    default:
     throw new AssertionError();
    }
   }
  }
  double wp[] = new double[n];
  for (int i = 0; i < n; i++) {
   wp[i] = (double) won[i] / games[i];
  }
  double owp[] = new double[n];
  for (int i = 0; i < n; i++) {
   double wpsum = 0;
   for (int j = 0; j < n; j++) {
    switch (table[i][j]) {
    case \'1\':
     wpsum += (double) won[j] / (games[j] - 1);
     break;
    case \'0\':
     wpsum += (double) (won[j] - 1) / (games[j] - 1);
    }
   }
   owp[i] = wpsum / games[i];
  }
  double oowp[] = new double[n];
  for (int i = 0; i < n; i++) {
   double owpsum = 0;
   for (int j = 0; j < n; j++) {
    switch (table[i][j]) {
    case \'0\':
    case \'1\':
     owpsum += owp[j];
    }
   }
   oowp[i] = owpsum / games[i];
  }
  for (int i = 0; i < n; i++) {
   out.printf(Locale.US, "%.12f\
", wp[i] / 4 + owp[i] / 2 + oowp[i] / 4);
  }
 }

 static void solve() throws Exception {
