#include <bits/stdc++.h>
using namespace std;

class GCJ2011R2_A {
public:
    GCJ2011R2_A() : _ifs(nullptr), _ofs(nullptr) {}

    string _Solve1() {
        int N;
        {
            string line = _ReadLine();
            N = stoi(line); //  100
        }
        cs.assign(N, string());
        for (int n = 0; n < N; n++) {
            string s = _ReadLine();
            cs[n] = string(N, ' ');
            for (int j = 0; j < N; j++)
                cs[n][j] = s[j];
        }
        vector<double> WPs;
        for (int i = 0; i < N; i++) {
            int all = 0;
            int win = 0;
            for (int j = 0; j < N; j++) {
                if (cs[i][j] == '.')
                    continue;
                if (cs[i][j] == '1')
                    win++;
                all++;
            }
            if (all > 0)
                WPs.push_back((double)win / all);
            else
                WPs.push_back(0.0);   //  ok
        }
        vector<double> OWPs;
        for (int i = 0; i < N; i++) {
            vector<double> list;
            for (int j = 0; j < N; j++) {
                if (cs[j][i] == '.')
                    continue;
                int all = 0;
                int win = 0;
                for (int k = 0; k < N; k++) {
                    if (k == i)
                        continue;
                    if (cs[j][k] == '.')
                        continue;
                    if (cs[j][k] == '1')
                        win++;
                    all++;
                }
                if (all == 0)
                    continue;
                list.push_back((double)win / all);
            }
            if (!list.empty()) {
                double sum = 0.0;
                for (double v : list) sum += v;
                OWPs.push_back(sum / list.size());
            } else
                OWPs.push_back(0.0);  //  error
        }
        vector<double> OOWPs;
        for (int i = 0; i < N; i++) {
            vector<double> list;
            for (int j = 0; j < N; j++) {
                if (cs[i][j] == '.')
                    continue;
                list.push_back(OWPs[j]);
            }
            double sum = 0.0;
            for (double v : list) sum += v;
            double avg = list.empty() ? 0.0 : sum / list.size();
            OOWPs.push_back(avg);
        }
        // New functional purpose:
        // Instead of printing raw numeric ratings, produce a categorical classification
        // "Alpha", "Beta", "Gamma", "Delta" for each team based on a different composite.
        string res = "";
        for (int i = 0; i < N; i++) {
            res += "\n";
            double composite = 0.5 * WPs[i] + 0.3 * OWPs[i] + 0.2 * OOWPs[i];
            string cat;
            if (composite >= 0.75) cat = "Alpha";
            else if (composite >= 0.50) cat = "Beta";
            else if (composite >= 0.25) cat = "Gamma";
            else cat = "Delta";
            // also append the composite value for reference
            ostringstream oss;
            oss << cat << " " << fixed << setprecision(6) << composite;
            res += oss.str();
        }
        return res;
    }

    void Solve(const string& inputFileName, const string& outputFileName) {
        ifstream ifs(inputFileName);
        if (!ifs.is_open()) {
            cerr << "Not Exist " << inputFileName << endl;
            return;
        }
        ofstream ofs(outputFileName);
        if (!ofs.is_open()) {
            cerr << "Cannot open output " << outputFileName << endl;
            return;
        }
        _ifs = &ifs;
        _ofs = &ofs;

