#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    for (int caseNum = 0; caseNum < T; caseNum++) {
        int N;
        scanf("%d", &N);
        char **A = (char**)malloc(N * sizeof(char*));
        for (int i = 0; i < N; i++) {
            A[i] = (char*)malloc((N + 5) * sizeof(char));
            scanf("%s", A[i]);
        }

        double *WP = (double*)malloc(N * sizeof(double));
        int *C = (int*)malloc(N * sizeof(int));
        for (int i = 0; i < N; i++) {
            WP[i] = 0.0;
            C[i] = 0;
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (A[i][j] != '.') C[i] += 1;
                if (A[i][j] == '1') WP[i] += 1.0;
            }
            WP[i] /= C[i];
        }

        double *OWP = (double*)malloc(N * sizeof(double));
        for (int i = 0; i < N; i++) OWP[i] = 0.0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (A[i][j] == '1') {
                    OWP[i] += WP[j] * C[j] / (C[j] - 1);
                }
                if (A[i][j] == '0') {
                    OWP[i] += (WP[j] * C[j] - 1) / (C[j] - 1);
                }
            }
            OWP[i] /= C[i];
        }

        double *OOWP = (double*)malloc(N * sizeof(double));
        for (int i = 0; i < N; i++) OOWP[i] = 0.0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (A[i][j] != '.') OOWP[i] += OWP[j];
            }
            OOWP[i] /= C[i];
        }

        /* New objective: compute a "suspicion index" as the complement of the original weighted rating.
           This preserves the exact control flow and calculations but changes the reported metric. */
        printf("Case #%d:\n", caseNum + 1);
        for (int i = 0; i < N; i++) {
            double original = 0.25 * WP[i] + 0.50 * OWP[i] + 0.25 * OOWP[i];
            double suspicion = 1.0 - original;
            printf("%.20f\n", suspicion);
        }

        for (int i = 0; i < N; i++) {
            free(A[i]);
        }
        free(A);
        free(WP);
        free(C);
        free(OWP);
        free(OOWP);
    }
    return 0;
}

