import java.io.*;
import java.util.*;

public class Main {
    public static double average(List<Double> tab) {
        double s = 0.0;
        for (double v : tab) s += v;
        return s / tab.size();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        line = br.readLine();
        int tests = Integer.parseInt(line.trim());
        for (int test = 0; test < tests; test++) {
            int N = Integer.parseInt(br.readLine().trim());
            ArrayList<Integer>[] opp = new ArrayList[N];
            for (int i = 0; i < N; i++) opp[i] = new ArrayList<Integer>();
            int[] wp_n = new int[N];
            int[][] G = new int[N][N];
            for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) G[i][j] = -1;
            for (int i = 0; i < N; i++) {
                String l = br.readLine();
                for (int j = 0; j < N; j++) {
                    char c = l.charAt(j);
                    if (c != '.') {
                        opp[i].add(j);
                        G[i][j] = c - '0';
                        wp_n[i] += (c - '0');
                    }
                }
            }
            double[] wp = new double[N];
            for (int i = 0; i < N; i++) {
                wp[i] = ((double) wp_n[i]) / opp[i].size();
            }
            double[] owp = new double[N];
            for (int i = 0; i < N; i++) {
                List<Double> vals = new ArrayList<Double>();
                for (int j : opp[i]) {
                    double numerator = wp_n[j] - G[j][i];
                    double denom = opp[j].size() - 1;
                    vals.add(numerator / denom);
                }
                owp[i] = average(vals);
            }
            double[] oowp = new double[N];
            for (int i = 0; i < N; i++) {
                List<Double> vals = new ArrayList<Double>();
                for (int j : opp[i]) {
                    vals.add(owp[j]);
                }
                oowp[i] = average(vals);
            }
            System.out.println("Case #" + (test + 1) + ":");
            for (int i = 0; i < N; i++) {
                double score = average(Arrays.asList(wp[i], owp[i], owp[i], oowp[i]));
                // New functional purpose: interpret the computed metric as a "node influence" score
                System.out.println("Node " + i + " influence: " + score);
            }
        }
    }
}

