        { 
            double sum = 0; 
            int count = 0; 
            for (int i=0;i<_n;i++) 
            { 
                if (i == t || _a[t][i] == \'.\') continue; 

                var rp = WP(i, t); 
                sum += rp; 
                count++; 
            } 

            if (count == 0) 
                return 0; 

            return sum/count; 
