import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    idx = 0
    caseCount = int(data[idx].strip()); idx += 1
    out_lines = []
    for caseNumber in range(1, caseCount + 1):
        N = int(data[idx].strip()); idx += 1
        s = [None] * N
        for i in range(N):
            s[i] = data[idx].strip(); idx += 1
            assert len(s[i]) == N

        Games = [0] * N
        Wins = [0] * N
        for i in range(N):
            for j in range(N):
                if s[i][j] != '.':
                    Games[i] += 1
                    if s[i][j] == '1':
                        Wins[i] += 1

        OWP = [0.0] * N
        for i in range(N):
            for j in range(N):
                if s[i][j] != '.':
                    opWinds = Wins[j]
                    if s[i][j] == '0':
                        opWinds -= 1
                    OWP[i] += (float(opWinds) / (Games[j] - 1))
            OWP[i] /= Games[i]

        OOWP = [0.0] * N
        for i in range(N):
            for j in range(N):
                if s[i][j] != '.':
                    OOWP[i] += OWP[j]
            OOWP[i] /= Games[i]

        res_vals = [0.0] * N
        for i in range(N):
            res_vals[i] = (float(Wins[i]) / Games[i]) * 0.25 + 0.5 * OWP[i] + 0.25 * OOWP[i]

        # New functional purpose:
        # Determine the best team (highest res) and produce a ranking of teams by res (desc)
        best_index = 0
        best_value = res_vals[0]
        for i in range(1, N):
            if res_vals[i] > best_value:
                best_value = res_vals[i]
                best_index = i

        # produce ranking: list of 1-based indices sorted by res descending, stable by index for ties
        indices = list(range(N))
        # stable sort by (-res, index)
        for i in range(N):
            for j in range(i + 1, N):
                if res_vals[indices[j]] > res_vals[indices[i]]:
                    indices[i], indices[j] = indices[j], indices[i]

        out_lines.append(f"Case #{caseNumber}:")
        out_lines.append(f"BestTeam {best_index + 1}")
        out_lines.append("Ranking " + " ".join(str(x + 1) for x in indices))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()

