#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

FILE *infile;
FILE *outfile;

char *readword() {
    int bufsize = 256;
    char *buf = (char*)malloc(bufsize);
    int idx = 0;
    int c = fgetc(infile);
    while (c != EOF && c <= ' ') c = fgetc(infile);
    if (c == EOF) {
        free(buf);
        return strdup("");
    }
    while (c != EOF && c > ' ') {
        if (idx + 1 >= bufsize) {
            bufsize *= 2;
            buf = (char*)realloc(buf, bufsize);
        }
        buf[idx++] = (char)c;
        c = fgetc(infile);
    }
    buf[idx] = '\0';
    return buf;
}

int iread() {
    char *w = readword();
    int v = atoi(w);
    free(w);
    return v;
}

double dread() {
    char *w = readword();
    double v = atof(w);
    free(w);
    return v;
}

long lread() {
    char *w = readword();
    long v = atol(w);
    free(w);
    return v;
}

void solve() {
    int n = iread();
    int **table = (int**)malloc(n * sizeof(int*));
    int i, j;
    for (i = 0; i < n; i++) {
        table[i] = (int*)malloc(n * sizeof(int));
        char *s = readword();
        for (j = 0; j < n; j++) {
            if (s[j] == '1') {
                table[i][j] = 1;
            } else if (s[j] == '.') {
                table[i][j] = -1;
            } else {
                table[i][j] = 0;
            }
        }
        free(s);
    }

    int *cnt = (int*)calloc(n, sizeof(int));
    int *wins = (int*)calloc(n, sizeof(int));
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (table[i][j] >= 0) {
                cnt[i]++;
                if (table[i][j] == 1) wins[i]++;
            }
        }
    }

    double *wp = (double*)malloc(n * sizeof(double));
    for (i = 0; i < n; i++) wp[i] = wins[i] * 1.0 / cnt[i];

    double *owp = (double*)malloc(n * sizeof(double));
    for (i = 0; i < n; i++) owp[i] = 0.0;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (table[i][j] >= 0) {
                owp[i] += (wins[j] - table[j][i]) * 1.0 / (cnt[j] - 1);
            }
        }
        owp[i] /= cnt[i];
    }

    double *oowp = (double*)malloc(n * sizeof(double));
    for (i = 0; i < n; i++) oowp[i] = 0.0;
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (table[i][j] >= 0) {
                oowp[i] += owp[j];
            }
        }
        oowp[i] /= cnt[i];
    }

    /* New functional purpose:
       Instead of printing the classic weighted rating, classify teams into three
       resilience categories based on a composite metric derived from the same
       computed arrays. Category 3 = high, 2 = medium, 1 = low.
       Thresholds chosen arbitrarily: >=0.60 -> 3, >=0.40 -> 2, else 1.
       Output one integer category per team on its own line.
    */
    for (i = 0; i < n; i++) {
        double metric = 0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i];
        int category;
        if (metric >= 0.60) category = 3;
        else if (metric >= 0.40) category = 2;
        else category = 1;
        fprintf(outfile, "%d\n", category);
    }

    for (i = 0; i < n; i++) free(table[i]);
    free(table);
    free(cnt);
    free(wins);
    free(wp);
    free(owp);
    free(oowp);
}

void solve_gcj() {
    int tests = iread();
    int test;
    for (test = 1; test <= tests; test++) {
        fprintf(outfile, "Case #%d:\n", test);
        solve();
    }
}

int main(int argc, char **argv) {
    infile = stdin;
    outfile = stdout;
    solve_gcj();
    return 0;
}

