        int n;
        fp >> n;
        string line;
        getline(fp, line); // consume endline after number
        vector<string> tab;
        vector<array<double,3>> l;
        vector<double> wp(n, 0.0);
        vector<double> owp(n, 0.0);
        vector<double> oowp(n, 0.0);
        for (int x = 0; x < n; ++x) {
            getline(fp, line);
            tab.push_back(line);
            l.push_back({0.0, 0.0, 0.0});
            for (char c : line) {
                if (c == '1') {
                    l.back()[0] += 1.0;
                    l.back()[1] += 1.0;
                }
                if (c == '0') {
                    l.back()[0] += 1.0;
                    l.back()[2] += 1.0;
                }
            }
            if (l.back()[0] > 0.0) {
                wp[x] = l.back()[1] / l.back()[0];
            } else {
                wp[x] = 0.0;
            }
        }
        for (int x = 0; x < n; ++x) {
            double total = 0.0;
            double div = 0.0;
            for (int y = 0; y < n; ++y) {
                if (tab[x][y] == '.' || x == y) continue;
                div += 1.0;
                double won = 0.0;
                double games = 0.0;
                for (int z = 0; z < n; ++z) {
                    if (z == x) continue;
                    if (tab[y][z] != '.') games += 1.0;
                    if (tab[y][z] == '1') won += 1.0;
                }
                if (games > 0.0) {
                    total += (won / games);
                } else {
                    total += 0.0;
                }
            }
            if (div > 0.0) owp[x] = total / div;
            else owp[x] = 0.0;
        }
        for (int x = 0; x < n; ++x) {
            double total = 0.0;
            double div = 0.0;
            for (int y = 0; y < n; ++y) {
                if (tab[x][y] == '.' || x == y) continue;
                div += 1.0;
                total += owp[y];
            }
            if (div > 0.0) oowp[x] = total / div;
            else oowp[x] = 0.0;
        }

        cout << "Case #" << caseNo << ":\n";
        for (int x = 0; x < n; ++x) {
            double metric = 0.25 * wp[x] + 0.5 * owp[x] + 0.25 * oowp[x];
            // New functional purpose: classify teams into categories based on the metric.
            // HIGH: metric >= 0.6, MEDIUM: 0.4 <= metric < 0.6, LOW: metric < 0.4
            if (metric >= 0.6) {
                cout << "HIGH\n";
            } else if (metric >= 0.4) {
                cout << "MEDIUM\n";
            } else {
                cout << "LOW\n";
            }
        }
        caseNo++;
    }
    fp.close();
    return 0;
}

