                if (g[i][j] != 0) {
                    ++count;
                    if (g[i][j] == 1) {
                        ++sum;
                    }
                }
            }
            wp[i] = (double) (sum) / count;
            for (int j = 0; j < size; ++j) {
                if (g[i][j] == 0) {
                    wpx[i][j] = wp[i];
                } else {
                    wpx[i][j] = (double) (sum - (g[i][j] == 1 ? 1 : 0)) / (count - 1);
                }
            }
        }
        for (int i = 0; i < size; ++i) {
            double sum = 0;
            int count = 0;
