            int count = 0;
            for (int j = 0; j < size; ++j) {
                if (g[i][j] != 0) {
                    ++count;
                    sum += owp[j];
                }
            }
            oowp[i] = sum / count;
        }
        out.println(prefix);
        for (int i = 0; i < size; ++i) {
            out.println(0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i]);
        }
    }

