                g[j][i] = 1;
            } else if (c == '1') {
                g[i][j] = 1;
                g[j][i] = -1;
            }
        }
    }
    double *wp = (double*)malloc(size * sizeof(double));
    double *owp = (double*)malloc(size * sizeof(double));
    double *oowp = (double*)malloc(size * sizeof(double));
    double **wpx = (double**)malloc(size * sizeof(double*));
    for (int i = 0; i < size; ++i) {
        wpx[i] = (double*)malloc(size * sizeof(double));
    }
    for (int i = 0; i < size; ++i) {
        int count = 0;
        int sum = 0;
        for (int j = 0; j < size; ++j) {
            if (g[i][j] != 0) {
                ++count;
                if (g[i][j] == 1) {
                    ++sum;
                }
            }
        }
        wp[i] = (double)(sum) / count;
        for (int j = 0; j < size; ++j) {
            if (g[i][j] == 0) {
                wpx[i][j] = wp[i];
            } else {
                wpx[i][j] = (double)(sum - (g[i][j] == 1 ? 1 : 0)) / (count - 1);
            }
        }
    }
    for (int i = 0; i < size; ++i) {
        double sum = 0;
        int count = 0;
        for (int j = 0; j < size; ++j) {
            if (g[i][j] != 0) {
                ++count;
                sum += wpx[j][i];
            }
        }
        owp[i] = sum / count;
    }
    for (int i = 0; i < size; ++i) {
        double sum = 0;
        int count = 0;
        for (int j = 0; j < size; ++j) {
            if (g[i][j] != 0) {
                ++count;
                sum += owp[j];
            }
        }
        oowp[i] = sum / count;
    }
    fprintf(out, "%s\n", prefix);
    for (int i = 0; i < size; ++i) {
        /* Different objective: compute a compact percentage "consensus score"
           using altered weights (0.3,0.4,0.3) and output as integer percent. */
        double combined = 0.3 * wp[i] + 0.4 * owp[i] + 0.3 * oowp[i];
        int percent = (int)floor(combined * 100.0 + 0.5);
        fprintf(out, "%d\n", percent);
    }
    for (int i = 0; i < size; ++i) {
        free(g[i]);
    }
    free(g);
    for (int i = 0; i < size; ++i) {
        free(wpx[i]);
    }
    free(wpx);
    free(wp);
    free(owp);
    free(oowp);
}

void run() {
    in = fopen("A.in", "r");
    out = fopen("A.out", "w");
    if (!in || !out) {
        return;
    }
    int nTests = nextInt();
    for (int i = 1; i <= nTests; ++i) {
        char prefix[64];
        sprintf(prefix, "Case #%d:", i);
        solveOne(prefix);
    }
    fclose(out);
    fclose(in);
}

int main() {
    run();
    return 0;
}

