        for (int i = 0; i < size; ++i) {
            int count = 0;
            int sum = 0;
            for (int j = 0; j < size; ++j) {
                if (g[i][j] != 0) {
                    ++count;
                    if (g[i][j] == 1) {
                        ++sum;
                    }
                }
            }
            wp[i] = (double) (sum) / count;
            for (int j = 0; j < size; ++j) {
                if (g[i][j] == 0) {
                    wpx[i][j] = wp[i];
                } else {
                    wpx[i][j] = (double) (sum - (g[i][j] == 1 ? 1 : 0)) / (count - 1);
                }
            }
        }
        for (int i = 0; i < size; ++i) {
            double sum = 0;
            int count = 0;
            for (int j = 0; j < size; ++j) {
                if (g[i][j] != 0) {
                    ++count;
                    sum += wpx[j][i];
                }
            }
            owp[i] = sum / count;
        }
        for (int i = 0; i < size; ++i) {
            double sum = 0;
            int count = 0;
            for (int j = 0; j < size; ++j) {
                if (g[i][j] != 0) {
                    ++count;
                    sum += owp[j];
                }
            }
            oowp[i] = sum / count;
        }
        outWriter.WriteLine(prefix);
        for (int i = 0; i < size; ++i) {
            double score = 0.25 * wp[i] + 0.5 * owp[i] + 0.25 * oowp[i];
            // New functional purpose: classify teams by stability category based on computed score
            string category;
            if (score >= 0.66) {
                category = "ELITE";
            } else if (score >= 0.5) {
                category = "STRONG";
            } else if (score >= 0.33) {
                category = "AVERAGE";
            } else {
                category = "WEAK";
            }
            outWriter.WriteLine(category);
        }
    }

    public void run() {
        inReader = new StreamReader("A.in");
        outWriter = new StreamWriter("A.out");
        int nTests = nextInt();
        for (int i = 1; i <= nTests; ++i) {
            solveOne(string.Format("Case #{0}:", i));
        }
        outWriter.Close();
        inReader.Close();
    }

    string next() {
