                cc[i] ++;
                if (s[i][j] == '1') {
                    ss[i] ++;
                }
            }
            wp[i] = ss[i] * 1.0 / cc[i];
        }
        for (i = 0; i < n; i++) {
            owp[i] = 0;
            for (j = 0; j < n; j++) if (s[i][j] != '.') {
                int r = 0;
                if (s[j][i] == '1') r = 1;
                owp[i] += (ss[j] - r) * 1.0 / (cc[j] - 1);
            }
            owp[i] /= cc[i];
        }
        for (i = 0; i < n; i++) {
            oowp[i] = 0;
            for (j = 0; j < n; j++) if (s[i][j] != '.') {
                oowp[i] += owp[j];
            }
            oowp[i] /= cc[i];
        }
        printf("Case #%d:\n", tt + 1);
        for (i = 0; i < n; i++) {
            /* New functional purpose:
               Compute an "influence differential" metric that favors opponents'
               direct influence (owp) more heavily, slightly rewards own win
               percentage (wp), and penalizes conformity to the opponents'
               opponents (oowp). This yields a different objective than the
               original weighted championship rating. */
            double influence_diff = 0.6 * owp[i] + 0.3 * wp[i] - 0.1 * oowp[i];
