using System;
using System.Collections.Generic;

class Program
{
    static double[] Solve(List<string> matches)
    {
        int M = matches.Count;
        int[] played = new int[M];
        int[] won = new int[M];
        List<List<int>> won_against = new List<List<int>>();
        List<List<bool>> played_against = new List<List<bool>>();
        for (int i = 0; i < M; i++)
        {
            won_against.Add(new List<int>());
            played_against.Add(new List<bool>());
            for (int j = 0; j < M; j++)
            {
                char ch = matches[i][j];
                if (ch == '1')
                {
                    won[i] += 1;
                }
                if (ch != '.')
                {
                    played[i] += 1;
                }
                won_against[i].Add(ch == '1' ? 1 : 0);
                played_against[i].Add(ch != '.');
            }
        }
        double[] WP = new double[M];
        for (int i = 0; i < M; i++)
        {
            WP[i] = (double)won[i] * 1.0 / (double)played[i];
        }
        double[] OWP = new double[M];
        for (int i = 0; i < M; i++)
        {
            double sum = 0.0;
            for (int j = 0; j < M; j++)
            {
                if (played_against[i][j])
                {
                    sum += ((double)won[j] - (double)won_against[j][i]) * 1.0 / ((double)played[j] - 1.0);
                }
            }
            OWP[i] = sum / (double)played[i];
        }
        double[] OOWP = new double[M];
        for (int i = 0; i < M; i++)
        {
            double sum = 0.0;
            for (int j = 0; j < M; j++)
            {
                if (played_against[i][j])
                {
                    sum += OWP[j];
                }
            }
            OOWP[i] = sum / (double)played[i];
        }
        double[] result = new double[M];
        for (int i = 0; i < M; i++)
        {
            result[i] = WP[i] * 0.25 + OWP[i] * 0.5 + OOWP[i] * 0.25;
        }
        return result;
    }

    static string ReadLineTrim()
    {
        return Console.ReadLine().Trim();
    }

    static double[] DoTest()
    {
        int M = int.Parse(ReadLineTrim());
        List<string> matches = new List<string>();
        for (int i = 0; i < M; i++)
        {
            matches.Add(ReadLineTrim());
        }
        double[] res = Solve(matches);
        return res;
    }

    static void Main()
    {
        int N = int.Parse(ReadLineTrim());
        for (int test = 0; test < N; test++)
        {
            double[] answer = DoTest();
            Console.WriteLine("Scenario #{0}: Influence Metrics", test + 1);
            for (int i = 0; i < answer.Length; i++)
            {
                Console.WriteLine(answer[i].ToString("F12"));
            }
            Console.Out.Flush();
        }
    }
}

