#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int T;
    if(!(cin>>T)) return 0;
    for(int cas=0; cas<T; ++cas){
        int N;
        cin>>N;
        vector<string> A(N);
        for(int i=0;i<N;++i) cin>>A[i];
        vector<double> WP(N,0.0);
        vector<int> C(N,0);
        for(int i=0;i<N;++i){
            for(int j=0;j<N;++j){
                if(A[i][j]!='.') C[i]+=1;
                if(A[i][j]=='1') WP[i]+=1;
            }
            if(C[i]>0) WP[i] /= C[i];
            else WP[i] = 0.0;
        }
        vector<double> OWP(N,0.0);
        for(int i=0;i<N;++i){
            for(int j=0;j<N;++j){
                if(A[i][j]=='1'){
                    // opponent j's WP excluding match vs i: use same algebra as source
                    OWP[i] += WP[j]*C[j]/(double)(C[j]-1);
                }
                if(A[i][j]=='0'){
                    OWP[i] += (WP[j]*C[j]-1)/(double)(C[j]-1);
                }
            }
            if(C[i]>0) OWP[i] /= C[i];
            else OWP[i] = 0.0;
        }
        vector<double> OOWP(N,0.0);
        for(int i=0;i<N;++i){
            for(int j=0;j<N;++j){
                if(A[i][j] != '.') OOWP[i] += OWP[j];
            }
            if(C[i]>0) OOWP[i] /= C[i];
            else OOWP[i] = 0.0;
        }

        // New functional purpose:
        // Compute a Composite Influence Score (different weights than original)
        // and output players sorted by that score (descending).
        vector<pair<double,int>> order;
        for(int i=0;i<N;++i){
            double score = 0.30*WP[i] + 0.50*OWP[i] + 0.20*OOWP[i];
            order.emplace_back(-score, i); // negative for ascending sort to get descending by score
        }
        sort(order.begin(), order.end());
        cout << "Case #" << (cas+1) << ":\n";
        cout.setf(std::ios::fixed); cout<<setprecision(12);
        for(size_t k=0;k<order.size();++k){
            int idx = order[k].second;
            double score = -order[k].first;
            // Print player index (1-based) and composite score
            cout << (idx+1) << " " << score << "\n";
        }
    }
    return 0;
}

