#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* readLine(FILE* f)
{
    if (!f) return NULL;
    size_t capacity = 4096;
    char *buffer = (char*)malloc(capacity);
    if (!buffer) return NULL;
    if (fgets(buffer, (int)capacity, f) == NULL)
    {
        free(buffer);
        return NULL;
    }
    size_t len = strlen(buffer);
    while (len > 0 && (buffer[len-1] == '\n' || buffer[len-1] == '\r'))
    {
        buffer[len-1] = '\0';
        len--;
    }
    return buffer;
}

char** Solution(FILE* in, int *out_count)
{
    char *line = readLine(in);
    if (!line)
    {
        *out_count = 0;
        return NULL;
    }
    int s = atoi(line);
    free(line);
    char **g = (char**)malloc(sizeof(char*) * s);
    int *W = (int*)malloc(sizeof(int) * s);
    int *L = (int*)malloc(sizeof(int) * s);
    double *OWP = (double*)malloc(sizeof(double) * s);
    for (int i = 0; i < s; i++)
    {
        W[i] = 0;
        L[i] = 0;
        OWP[i] = 0.0;
    }
    for (int i = 0; i < s; i++)
    {
        g[i] = readLine(in);
        if (!g[i]) g[i] = strdup("");
        for (int idx = 0; g[i][idx] != '\0'; idx++)
        {
            char item = g[i][idx];
            if (item == '0')
                L[i]++;
            if (item == '1')
                W[i]++;
        }
    }
    for (int i = 0; i < s; i++)
    {
        int gg = 0;
        for (int j = 0; j < s; j++)
        {
            char c = g[i][j];
            if (c != '.')
            {
                int w = W[j];
                int l = L[j];
                if (c == '0')
                    w--;
                if (c == '1')
                    l--;
                if (l == 0)
                    OWP[i] += 1.0;
                else
                    OWP[i] += (double)w / (double)(w + l);
                gg++;
            }
        }
        if (gg != 0)
            OWP[i] /= (double)gg;
    }
    char **ret = (char**)malloc(sizeof(char*) * s);
    for (int i = 0; i < s; i++)
    {
        double v = 0.0;
        if (L[i] == 0)
            v += 0.25;
        else
            v += 0.25 * (double)W[i] / (double)(W[i] + L[i]);
        v += 0.5 * OWP[i];
        double k = 0.0;
        double f = 0.0;
        for (int j = 0; j < s; j++)
        {
            if (g[i][j] != '.')
            {
                k += 0.25 * OWP[j];
                f++;
            }
        }
        if (f != 0)
            v += k / f;
        {
            char buf[128];
            /* Changed functional purpose: label as "CohesionScore" instead of raw rating */
            snprintf(buf, sizeof(buf), "CohesionScore: %.10f", v);
            ret[i] = strdup(buf);
        }
    }
    for (int i = 0; i < s; i++)
    {
        if (g[i]) free(g[i]);
    }
    free(g);
    free(W);
    free(L);
    free(OWP);
    *out_count = s;
    return ret;
}

int main(int argc, char **argv)
{
    FILE *in = fopen("input.txt", "r");
    if (!in) in = stdin;
    FILE *out = fopen("output.txt", "w");
    if (!out) out = stdout;
    char *line = readLine(in);
    if (!line)
    {
        if (in != stdin) fclose(in);
        if (out != stdout) fclose(out);
        return 0;
    }
    int n = atoi(line);
    free(line);
    printf("%d\n", n);
    for (int i = 0; i < n; i++)
    {
        fprintf(out, "Case #%d:\n", i + 1);
        int tcount = 0;
        char **t = Solution(in, &tcount);
        for (int k = 0; k < tcount; k++)
        {
            fprintf(out, "%s\n", t[k]);
            free(t[k]);
        }
        if (t) free(t);
        printf("%d\n", i);
    }
    if (out != stdout) fclose(out);
    if (in != stdin) fclose(in);
    printf("Finished\n");
    getchar();
    return 0;
}

