import java.io.*;
import java.util.*;

public class Main {
    static boolean check(int[][][] a, int n, int m, long i) {
        HashSet<String> used = new HashSet<String>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int d0 = a[r][c][0];
                int d1 = a[r][c][1];
                if (((i >> (r * m + c)) & 1L) == 1L) {
                    d0 = -d0;
                    d1 = -d1;
                }
                int nr = r + d0;
                int nc = c + d1;
                nr = ((nr % n) + n) % n;
                nc = ((nc % m) + m) % m;
                String key = nr + "," + nc;
                if (used.contains(key)) return false;
                used.add(key);
            }
        }
        return true;
    }

    static long run(BufferedReader br) throws Exception {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[][][] a = new int[n][m][2];
        HashMap<Character, int[]> dirs = new HashMap<Character, int[]>();
        dirs.put('|', new int[]{1, 0});
        dirs.put('-', new int[]{0, 1});
        dirs.put('/', new int[]{1, -1});
        dirs.put('\\', new int[]{1, 1});
        for (int i = 0; i < n; i++) {
            String s = br.readLine();
            for (int j = 0; j < m; j++) {
                char ch = s.charAt(j);
                int[] d = dirs.get(ch);
                a[i][j][0] = d[0];
                a[i][j][1] = d[1];
            }
        }
        long res = 0;
        long limit = 1L << (n * m);
        for (long i = 0; i < limit; i++) {
            if (!check(a, n, m, i)) res += 1;
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        for (int test = 0; test < T; test++) {
            long ans = run(br);
            System.out.println("Case #" + (test + 1) + ": " + ans);
        }
    }
}

