using System;

class Program
{
    const int MAXL = 50;
    static char[,] graph = new char[MAXL, MAXL];
    static int[] use = new int[MAXL];
    static int[] dp = new int[MAXL];
    static int R, C;

    static int aval(int p)
    {
        int ret = -1;
        int j;
        for (j = 0; j < C && ret != 0; j++)
        {
            while (j < C && graph[p, j] != '#')
            {
                ++j;
            }
            if (j < C)
            {
                ret = (p != 0 && j != C - 1
                    && graph[p - 1, j] == '#'
                    && graph[p - 1, j + 1] == '#'
                    && graph[p, j + 1] == '#'
                    ) ? 1 : 0;
            }
            ++j;
        }
        return ret;
    }

    static void Main()
    {
        string line = Console.ReadLine();
        if (line == null) return;
        int Tcases = int.Parse(line.Trim());
        for (int cases = 0; cases < Tcases; cases++)
        {
            string rcLine = Console.ReadLine();
            while (string.IsNullOrWhiteSpace(rcLine)) rcLine = Console.ReadLine();
            string[] parts = rcLine.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
            R = int.Parse(parts[0]);
            C = int.Parse(parts[1]);
            int i, j;
            for (i = 0; i < R; i++)
            {
                string input = Console.ReadLine();
                while (input == null || input.Length < C) input = Console.ReadLine();
                for (j = 0; j < C; j++)
                {
                    graph[i, j] = input[j];
                }
                use[i] = aval(i);
            }
            for (i = 0; i < R; i++)
            {
                dp[i] = 0;
                if (use[i] != 0)
                {
                    if (use[i] == -1)
                    {
                        dp[i] = i != 0 ? dp[i - 1] : 1;
                    }
                    else
                    {
                        dp[i] = i > 1 ? dp[i - 2] : 1;
                    }
                }
            }

            int ans = 1;
            for (i = 0; i < R && ans != 0; i++)
            {
                for (j = 0; j < C && ans != 0; j++)
                {
                    if (graph[i, j] == '#')
                    {
                        bool ok = i != R - 1 && j != C - 1
                            && graph[i, j + 1] == '#'
                            && graph[i + 1, j] == '#'
                            && graph[i + 1, j + 1] == '#';
                        ans &= ok ? 1 : 0;
                        if (ans != 0)
                        {
                            graph[i, j] = '/';
                            graph[i + 1, j] = '\\';
                            graph[i, j + 1] = '\\';
                            graph[i + 1, j + 1] = '/';
                        }
                    }
                }
            }

            Console.WriteLine("Result #{0}:", cases + 1);
            if (ans != 0)
            {
                for (i = R; i > 0; i--)
                {
                    if (use[i - 1] == 1)
                    {
                        for (j = 0; j < C; j++)
                        {
                            while (j < C && graph[i - 1, j] != '#')
                            {
                                ++j;
                            }
                            graph[i - 2, j] = '/';
                            graph[i - 1, j] = '\\';
                            graph[i - 2, j + 1] = '\\';
                            graph[i - 1, j + 1] = '/';
                            ++j;
                        }
                        --i;
                    }
                }

                for (i = 0; i < R; i++)
                {
                    for (j = 0; j < C; j++)
                    {
                        Console.Write(graph[i, j]);
                    }
                    Console.WriteLine();
                }
            }
            else
            {
                Console.WriteLine("CannotProcess");
            }
        }
    }
