#include <bits/stdc++.h>
using namespace std;

class GCJ2011R2_A {
public:
    GCJ2011R2_A() {}
    string _Solve1() {
        int N = stoi(_ReadLine()); //  100
        cs.assign(N, vector<char>(N));
        for (int n = 0; n < N; n++) {
            string s = _ReadLine();
            for (int j = 0; j < N; j++)
                cs[n][j] = s[j];
        }
        vector<double> WPs;
        for (int i = 0; i < N; i++) {
            int all = 0;
            int win = 0;
            for (int j = 0; j < N; j++) {
                if (cs[i][j] == '.')
                    continue;
                if (cs[i][j] == '1')
                    win++;
                all++;
            }
            if (all > 0)
                WPs.push_back((double)win / all);
            else
                WPs.push_back(0.0);   //  ok
        }
        vector<double> OWPs;
        for (int i = 0; i < N; i++) {
            vector<double> list;
            for (int j = 0; j < N; j++) {
                if (cs[j][i] == '.')
                    continue;
                int all = 0;
                int win = 0;
                for (int k = 0; k < N; k++) {
                    if (k == i)
                        continue;
                    if (cs[j][k] == '.')
                        continue;
                    if (cs[j][k] == '1')
                        win++;
                    all++;
                }
                if (all == 0)
                    continue;
                list.push_back((double)win / all);
            }
            if (!list.empty()) {
                double sum = 0.0;
                for (double v : list) sum += v;
                OWPs.push_back(sum / list.size());
            } else
                OWPs.push_back(0.0);  //  error
        }
        vector<double> OOWPs;
        for (int i = 0; i < N; i++) {
            vector<double> list;
            for (int j = 0; j < N; j++) {
                if (cs[i][j] == '.')
                    continue;
                list.push_back(OWPs[j]);
            }
            double sum = 0.0;
            for (double v : list) sum += v;
            // replicate original behavior: average (may divide by zero if list empty)
            double avg = list.size() > 0 ? sum / list.size() : 0.0;
            OOWPs.push_back(avg);
        }
        string res = "";
        for (int i = 0; i < N; i++) {
            res += "\n";
            // Different objective: compute a "stability" metric rather than original RPI.
            // Stability = (0.6 * OWPs[i] + 0.4 * (1 - WPs[i])) * (1 + OOWPs[i])
            double stability = (0.6 * OWPs[i] + 0.4 * (1.0 - WPs[i])) * (1.0 + OOWPs[i]);
            // use full precision similar to ToString()
            ostringstream oss;
            oss << stability;
            res += oss.str();
        }
        return res;
    }

    vector<vector<char>> cs;
    void Solve(const string& inputFileName, const string& outputFileName) {
        ifstream fin(inputFileName);
        if (!fin.is_open()) {
            cerr << "\nNot Exist " << inputFileName << endl;
            return;
        }
        _sr_stream = &fin;
        ofstream fout(outputFileName);
        _sw_stream = &fout;
        cerr << "\nStart... " << inputFileName << endl;
        int T = stoi(_ReadLine()); //  <=100
        for (int t = 1; t <= T; t++) {
            string s = _Solve1();
            _WriteLine(string("Case #") + to_string(t) + string(": ") + s);
        }
        fout.close();
        fin.close();
    }

private:
    istream* _sr_stream = nullptr;
    ostream* _sw_stream = nullptr;
    string _ReadLine() {
        string line;
        getline(*_sr_stream, line);
        return line;
    }
    void _Write(const string& s) {
        cerr << s;
        (*_sw_stream) << s;
    }
    void _WriteLine(const string& s) {
        _Write(s + "\n");
    }
};

int main() {
    GCJ2011R2_A solver;
    vector<string> subs = { "Sample", "Small", "Large" };
    for (auto& sub : subs) {
        string inputFileName = string("..\\\\..\\\\") + "GCJ2011R2_A." + sub + ".txt";
        string outputFileName = string("..\\\\..\\\\") + "GCJ2011R2_A." + sub + ".out.txt";
        solver.Solve(inputFileName, outputFileName);
    }
    return 0;
}

