            in = new FastScanner(new File("C-small-2-attempt1.in")); 
            out = new PrintWriter(new File("C-small-2-attempt1.out")); 

            solve(); 

            out.close(); 
        } catch (IOException e) { 
            e.printStackTrace(); 
        } 
    } 

