class TaskC {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
            int count;
            int[] at;
            int[] size;
            int[] start;

            long answer;

            public void read(InputReader in) {
                count = in.readInt();
                at = new int[count];
                size = new int[count];
                start = new int[count];
                IOUtils.readIntArrays(in, at, size, start);
            }

            public void solve() {
                answer = ArrayUtils.sumArray(size);
                Set<Long> finishTimes = new EHashSet<>();
                for (int i = 0; i < count; i++) {
                    for (int j = start[i]; j < start[i] + size[i]; j++) {
                        long weFinish = (360L - at[i]) * j;
                        finishTimes.add(weFinish);
                    }
                }
                long[] times = new long[finishTimes.size()];
                int ind = 0;
                for (long i : finishTimes) {
                    times[ind++] = i;
                }
                Arrays.sort(times);
                SumIntervalTree tree = new SumIntervalTree(times.length);
                for (int i = 0; i < count; i++) {
                    for (int j = start[i]; j < start[i] + size[i]; j++) {
                        long weFinish = (360L - at[i]) * j;
                        for (long current = weFinish + 360L * j; ; ) {
                            int at = Arrays.binarySearch(times, current);
                            if (at < 0) {
                                at = -at - 1;
                            }
                            if (at >= times.length) {
                                break;
                            }
                            if (tree.query(at, at) >= answer) {
                                break;
                            }
                            long here = (times[at] - current) / (360L * j) + 1;
                            tree.update(at, times.length - 1, here);
                            current += 360L * j * here;
                        }
                    }
                }
                for (int i = 0; i < count; i++) {
                    for (int j = start[i]; j < start[i] + size[i]; j++) {
                        long weFinish = (360L - at[i]) * j;
                        int at = Arrays.binarySearch(times, weFinish);
                        tree.update(0, at - 1, 1);
                    }
                }
                for (int i = 0; i < times.length; i++) {
                    answer = Math.min(answer, tree.query(i, i));
                }
            }

            public void write(OutputWriter out, int testNumber) {
                out.printLine("Case #" + testNumber + ":", answer);
            }
        }, 4);
    }
}

class InputReader {

 private InputStream stream;
 private byte[] buf = new byte[1024];
 private int curChar;
 private int numChars;
 private SpaceCharFilter filter;

 public InputReader(InputStream stream) {
  this.stream = stream;
 }

 public int read() {
  if (numChars == -1)
   throw new InputMismatchException();
  if (curChar >= numChars) {
   curChar = 0;
   try {
    numChars = stream.read(buf);
   } catch (IOException e) {
    throw new InputMismatchException();
   }
   if (numChars <= 0)
    return -1;
  }
  return buf[curChar++];
 }

 public int readInt() {
  int c = read();
  while (isSpaceChar(c))
   c = read();
  int sgn = 1;
  if (c == \'-\') {
   sgn = -1;
   c = read();
  }
  int res = 0;
  do {
   if (c < \'0\' || c > \'9\')
    throw new InputMismatchException();
   res *= 10;
   res += c - \'0\';
   c = read();
  } while (!isSpaceChar(c));
  return res * sgn;
 }

 public boolean isSpaceChar(int c) {
  if (filter != null)
   return filter.isSpaceChar(c);
  return isWhitespace(c);
 }

 public static boolean isWhitespace(int c) {
  return c == \' \' || c == \'\
\' || c == \'\ \' || c == \'\ \' || c == -1;
 }

 public interface SpaceCharFilter {
  public boolean isSpaceChar(int ch);
 }
}

