        for (int i = 1; i < n; ++i) {
            int was = m[i-1];
            int cur = m[i];
            if (was < rate) {
                eaten += was;
                was = 0;
            } else {
                was -= rate;
                eaten += rate;
            }
            if (was > cur) {
                return Integer.MAX_VALUE;
            }
        }
        return eaten;
    }
