import sys


def compute(N, m):
    nmin = 0
    nmax = 0
    maxdelta = 0
    for i in xrange(1, N):
        if m[i] < m[i - 1]:
            delta = m[i - 1] - m[i]
            nmin += delta
            if delta > maxdelta:
                maxdelta = delta
    for i in xrange(1, N):
        nmax += min(maxdelta, m[i - 1])
    return "%s %s" % (nmin, nmax)


def parse():
