  public static final String NAME = "A-large"; 

  private static void main2() throws IOException { 
    int N = in.nextInt(); 
    int[] m = new int[N]; 
    for (int i = 0; i < N; i++) { 
      m[i] = in.nextInt(); 
    } 
    int ans1 = 0; 
    for (int i = 1; i < N; i++) { 
      ans1 += Math.max(0, m[i-1] - m[i]); 
    } 
    int maxchange = 0; 
    for (int i = 1; i < N; i++) { 
      maxchange = Math.max(maxchange, m[i-1] - m[i]); 
    } 

    int ans2 = 0; 
    for (int i = 1; i < N; i++) { 
      ans2 += Math.min(m[i-1], maxchange); 
    } 

    out.println(ans1+" "+ans2); 
  } 

