public class A { 

 Scanner scan; 
 public A(Scanner s) { 
  this.scan = s; 
 } 

 int w; 
 int[]M; 
 int mv(int c) { 
  if(c==w)return w; 
  if(c<w)return 0; 
  if(M[c]!=-1)return M[c]; 
  int r = c; 
  for(int i=0;i<c;i++) { 
   int h = w+1; 
   int ms = mv(i)+mv(c-i-1)+1; 
   int b = max(ms,h); 
   r = min(r, b); 
  } 
  return M[c]=r; 
