class TaskA extends GCJSolution {

  public void solve(int testNumber) {
    int r = in.nextInt();
    int c = in.nextInt();
    int w = in.nextInt();

    int ans = 0;

    int perLine = c / w;
    ans += perLine * (r - 1);

    ans += perLine - 1;
    int x = c - (perLine - 1) * w;
    if (x == w) {
      ans += w;
    } else {
      ans += w + 1;
    }

    out.println(ans);
  }
}

