    string a, b; cin >> a >> b; 
    int result = inf; 
    setmin(result, solve(a, b)); 
    reverse(whole(a)); 
    reverse(whole(b)); 
    setmin(result, solve(a, b)); 
    cout << result << endl; 
    return 0; 
