        bset.set(1); 
        bset.set(tmp); 
        LinkedList<Integer> ans = new LinkedList<>(); 
        ans.add(1); 
        ans.add(tmp); 
        boolean send = false; 
        boolean eend = false; 
        while (!send || !eend) { 
            if (!send) { 
                send = true; 
                int s = ans.getFirst(); 
                for (Integer sp : nodes[s - 1].path) { 
                    if (!bset.get(sp)) { 
                        bset.set(sp); 
                        ans.addFirst(sp); 
                        send = false; 
                        break; 
                    } 
                } 
            } 
            if (!eend) { 
                eend = true; 
                int e = ans.getLast(); 
                for (Integer ep : nodes[e - 1].path) { 
                    if (!bset.get(ep)) { 
                        bset.set(ep); 
                        ans.addLast(ep); 
                        eend = false; 
                        break; 
                    } 
                } 
            } 
        } 

        StringBuilder sb = new StringBuilder(); 
