    private long F(long S, long X) 
    { 
        if (S == 0) return 1; 
        if (dic.ContainsKey(S) && dic[S].ContainsKey(X)) return dic[S][X]; 
        long res = 0; 
        res += F(S / 2, X / 2); 
        res += F((S - 1) / 2, (X - 1) / 2); 
        if (S >= 2) res += F((S - 2) / 2, X / 2); 
        res %= Mod; 
        Add(S, X, res); 
        return res; 
    } 

    void Add(long S, long X, long val) 
    { 
        if (!dic.ContainsKey(S)) dic[S] = new Dictionary<long, long>(); 
        dic[S][X] = val; 
    } 
