int convert_10_base(int number, int base, int *array) { 
 int temp = 1; 
 int index = 0; 
 while (1) { 
  if (temp * base > number) break; 
  temp *= base; 
 } 
 while (1) { 
  array[index] = number / temp; 
  number %= temp; 
  index ++; 
  temp /= base; 
  if (temp == 0) break; 
 } 
 return index; 
} 
void find_happy_numbers(int base) { 
 int number[20]; 
 int len, i, j, sum; 
 int first, first_flag; 
 for (i = 2; i <= MAX_NO; i++) { 
  sum = i; 
  while (1) { 
   len = convert_10_base(sum, base, number); 
   sum = 0; 
   for (j = 0; j < len; j++) { 
    sum += number[j] * number[j]; 
   } 
   if (visit[sum] == i) { 
    break; 
   } 
   visit[sum] = i; 
   first_flag = 0; 
   if (sum == 1) { 
    happy_numbers[base][i] = 1; 
    break; 
   } 
  } 
 } 
} 
