    } 

    public static void add(Node a, int L, int R, int V) 
    { 
        if(a == null || L >= R || L >= count(a) || R <= 0)return; 
        if(L <= 0 && R >= count(a)){ 
            a.v += V; 
            a.add += V; 
        }else{ 
            add(a.left, L, R, V); 
            add(a.right, L-count(a.left)-1, R-count(a.left)-1, V); 
            if(L <= count(a.left) && count(a.left) < R)a.v += V; 
        } 
        update(a); 
    } 

    public static void fall(Node a) 
    { 
        if(a == null)return; 
        if(a.left != null){ 
            a.left.add += a.add; 
            a.left.v += a.add; 
            update(a.left); 
        } 
        if(a.right != null){ 
            a.right.add += a.add; 
            a.right.v += a.add; 
            update(a.right); 
        } 
        a.add = 0; 
        update(a); 
    } 

    public static Node merge(Node a, Node b) 
    { 
        if(b == null)return a; 
        if(a == null)return b; 
        if(a.priority > b.priority){ 
            fall(a); 
            setParent(a.right, null); 
            setParent(b, null); 
            a.right = merge(a.right, b); 
            setParent(a.right, a); 
            return update(a); 
        }else{ 
            fall(b); 
            setParent(a, null); 
            setParent(b.left, null); 
            b.left = merge(a, b.left); 
            setParent(b.left, b); 
            return update(b); 
        } 
    } 

