                setParent(a.right, a); 
            } 
            return update(a); 
        }else{ 
            Node[] ch = split(a, K); 
            b.left = ch[0]; b.right = ch[1]; 
            setParent(b.left, b); 
            setParent(b.right, b); 
            return update(b); 
        } 
    } 

    // delete K-th 
    public static Node erase(Node a, int K) 
    { 
        if(a == null)return null; 
        if(K < count(a.left)){ 
            a.left = erase(a.left, K); 
            setParent(a.left, a); 
            return update(a); 
        }else if(K == count(a.left)){ 
