  static class TaskD { 

    static final int mod = 1000 * 1000 * 1000 + 7; 

    public void solve(int testNumber, InputReader in, OutputWriter out) { 
      int n = in.nextInt(); 
      int m = in.nextInt(); 
      int[] dn = calc(n, m); 
      int[] dn1 = calc(n - 1, m); 
      int res = 0; 
      for (int x : dn) { 
        res = (res + x) % mod; 
      } 
      for (int x : dn1) { 
        res = (res - x) % mod; 
      } 
      res = (res % mod + mod) % mod; 
      out.printLine(res); 
    } 

    private int[] calc(int n, int m) { 
      int[][] d = new int[2][n + 1]; 
      for (int i = 0; i <= n; ++i) { 
        d[0][i] = 1; 
      } 
      for (int i = 0; i < m; ++i) { 
        int[] cur = d[i % 2]; 
        int[] next = d[(i + 1) % 2]; 
        Arrays.fill(next, 0); 
        for (int j = 0; j <= n; ++j) { 
          for (int c1 = 0; c1 < 2; ++c1) { 
            int t0 = j, t1 = n - j; 
            if (c1 == 0) { 
              --t0; 
            } else { 
              --t1; 
            } 
            if (t0 < 0 || t1 < 0) { 
              continue; 
            } 
            for (int c2 = 0; c2 < 2; ++c2) { 
              int tt0 = t0, tt1 = t1; 
