              tt1 += 1; 
              if (tt0 < 0 || tt1 < 0 || tt0 + tt1 != n) { 
                throw new RuntimeException(); 
              } 
              next[tt0] += cur[j]; 
              next[tt0] %= mod; 
            } 
          } 
        } 
      } 
      return d[m % 2]; 
    } 

