                    isng = true; 
                    break; 
                } 
            } 
            if (isng) { 
                ng = med; 
            } else { 
                ok = med; 
            } 
        } 
        if (ok == cn) { 
            return maxB+10; 
        } 
        return tmp[ok] + (now == 0 ? 0 : 1); 
    } 

    static int dfsA(int now, int par, int flg) { 
        int cn = 0; 
        for (int to : graph[now]) { 
            if (to == par) { 
                continue; 
