            deg[b]++; 
            edges[i] = new int[]{a, b}; 
        } 
        for (int i = 0 ; i < n ; i++) { 
            graph[i] = new int[deg[i]]; 
        } 
        for (int i = 0 ; i < m ; i++) { 
            int a = edges[i][0]; 
            int b = edges[i][1]; 
            graph[a][--deg[a]] = b; 
            graph[b][--deg[b]] = a; 
        } 
