        private byte[] buf = new byte[BUFFER_LENGTH]; 
        private int curChar; 
        private int numChars; 

        public InputReader(InputStream stream) { 
            this.stream = stream; 
        } 

        private int next() { 
            if (numChars == -1) { 
                throw new InputMismatchException(); 
            } 
            if (curChar >= numChars) { 
                curChar = 0; 
                try { 
                    numChars = stream.read(buf); 
                } catch (IOException e) { 
                    throw new InputMismatchException(); 
                } 
                if (numChars <= 0) 
                    return -1; 
            } 
            return buf[curChar++]; 
        } 

        public char nextChar() { 
            return (char) skipWhileSpace(); 
        } 

        public String nextToken() { 
            int c = skipWhileSpace(); 
            StringBuilder res = new StringBuilder(); 
            do { 
                res.append((char) c); 
                c = next(); 
            } while (!isSpaceChar(c)); 
            return res.toString(); 
        } 

        public int nextInt() { 
            return (int) nextLong(); 
        } 

        public long nextLong() { 
            int c = skipWhileSpace(); 
            long sgn = 1; 
            if (c == \'-\') { 
                sgn = -1; 
                c = next(); 
            } 
            long res = 0; 
            do { 
                if (c < \'0\' || c > \'9\') { 
                    throw new InputMismatchException(); 
                } 
                res *= 10; 
                res += c - \'0\'; 
                c = next(); 
            } while (!isSpaceChar(c)); 
            return res * sgn; 
        } 

        public double nextDouble() { 
            return Double.valueOf(nextToken()); 
        } 

        int skipWhileSpace() { 
            int c = next(); 
            while (isSpaceChar(c)) { 
                c = next(); 
            } 
            return c; 
        } 

        boolean isSpaceChar(int c) { 
            return c == \' \' || c == \'\
\' || c == \'\ \' || c == \'\ \' || c == -1; 
        } 
