class mymath 
{ 
    int Mod = 1000000007; 
    public void setMod(int m) { Mod = m; } 
    public bool isprime(long a) 
    { 
        if (a < 2) return false; 
        for (long i = 2; i * i <= a; i++) if (a % i == 0) return false; 
        return true; 
    } 
    public bool[] sieve(int n) 
    { 
        var p = new bool[n + 1]; 
        for (int i = 2; i <= n; i++) p[i] = true; 
        for (int i = 2; i * i <= n; i++) if (p[i]) for (int j = i * i; j <= n; j += i) p[j] = false; 
        return p; 
    } 
    public List<int> getprimes(int n) 
    { 
        var prs = new List<int>(); 
        var p = sieve(n); 
        for (int i = 2; i <= n; i++) if (p[i]) prs.Add(i); 
        return prs; 
    } 
    public long[][] E(int n) 
    { 
        var ret = new long[n][]; 
        for (int i = 0; i < n; i++) 
        { 
            ret[i] = new long[n]; 
            ret[i][i] = 1; 
        } 
        return ret; 
    } 
    public long[][] pow(long[][] A, long n) 
    { 
        if (n == 0) return E(A.Length); 
        var t = pow(A, n / 2); 
        if ((n & 1) == 0) return mul(t, t); 
        return mul(mul(t, t), A); 
    } 
    public long dot(long[] x, long[] y) 
    { 
        int n = x.Length; 
        long ret = 0; 
        for (int i = 0; i < n; i++) ret = (ret + x[i] * y[i]) % Mod; 
        return ret; 
    } 
    public long[][] trans(long[][] A) 
    { 
        int n = A[0].Length, m = A.Length; 
        var ret = new long[n][]; 
        for (int i = 0; i < n; i++) 
        { 
            ret[i] = new long[m]; 
            for (int j = 0; j < m; j++) ret[i][j] = A[j][i]; 
        } 
        return ret; 
    } 
    public long[] mul(long[][] A, long[] x) 
    { 
        int n = A.Length; 
        var ret = new long[n]; 
        for (int i = 0; i < n; i++) ret[i] = dot(x, A[i]); 
        return ret; 
    } 
    public long[][] mul(long[][] A, long[][] B) 
    { 
        int n = A.Length; 
        var Bt = trans(B); 
        var ret = new long[n][]; 
        for (int i = 0; i < n; i++) ret[i] = mul(Bt, A[i]); 
        return ret; 
    } 
    public long[] add(long[] x, long[] y) 
    { 
        int n = x.Length; 
        var ret = new long[n]; 
        for (int i = 0; i < n; i++) ret[i] = (x[i] + y[i]) % Mod; 
        return ret; 
    } 
    public long[][] add(long[][] A, long[][] B) 
    { 
        int n = A.Length; 
        var ret = new long[n][]; 
        for (int i = 0; i < n; i++) ret[i] = add(A[i], B[i]); 
        return ret; 
    } 
    public long pow(long a, long b) 
    { 
        if (a >= Mod) return pow(a % Mod, b); 
        if (a == 0) return 0; 
        if (b == 0) return 1; 
        var t = pow(a, b / 2); 
        if ((b & 1) == 0) return t * t % Mod; 
        return t * t % Mod * a % Mod; 
    } 
    public long inv(long a) { return pow(a, Mod - 2); } 
    public long gcd(long a, long b) 
    { 
        while (b > 0) { var t = a % b; a = b; b = t; } 
        return a; 
    } 
    public long lcm(long a, long b) { return a * (b / gcd(a, b)); } 
    public long comb(int n, int r) 
    { 
        if (n < 0 || r < 0 || r > n) return 0; 
        if (n - r < r) r = n - r; 
        if (r == 0) return 1; 
        if (r == 1) return n; 
        var numer = new int[r]; 
        var denom = new int[r]; 
        for (int k = 0; k < r; k++) 
        { 
            numer[k] = n - r + k + 1; 
            denom[k] = k + 1; 
        } 
        for (int p = 2; p <= r; p++) 
        { 
            int piv = denom[p - 1]; 
            if (piv > 1) 
            { 
                int ofst = (n - r) % p; 
                for (int k = p - 1; k < r; k += p) 
                { 
                    numer[k - ofst] /= piv; 
                    denom[k] /= piv; 
                } 
            } 
        } 
        long ret = 1; 
        for (int k = 0; k < r; k++) if (numer[k] > 1) ret = ret * numer[k] % Mod; 
        return ret; 
    } 
