 int[] DijkstraFrom(int from) 
 { 
  var d = new int[V]; 
  for (var i = 0; i < V; i++) d[i] = Inf; 
  var queue = new PQ(); 
  d[from] = 0; 
  queue.Enqueue(new P(from, 0)); 
  while (queue.Count > 0) 
  { 
   var p = queue.Dequeue(); 
   int u = p.First, tmp = d[u] + (dead.Contains(u) ? 1 : 0); 
   if (d[u] < p.Second) continue; 
   var k = es[u].Count; 
   for (var i = 0; i < k; i++) 
   { 
    int v = es[u][i]; 
    if (d[v] > tmp) queue.Enqueue(new P(v, d[v] = tmp)); 
   } 
  } 
  return d; 
 } 
