class PQ 
{ 
 List<P> list = new List<P>(); 
 public int Count = 0; 
 public void Enqueue(P x) 
 { 
  var k = x.Second; 
  var pos = Count++; 
  list.Add(x); 
  while (pos > 0) 
  { 
   var p = (pos - 1) / 2; 
   if (list[p].Second <= k) break; 
   list[pos] = list[p]; 
   pos = p; 
  } 
  list[pos] = x; 
 } 
 public P Dequeue() 
 { 
  var value = list[0]; 
  var x = list[--Count]; 
  var k = x.Second; 
  list.RemoveAt(Count); 
  if (Count == 0) return value; 
  var pos = 0; 
  while (pos * 2 + 1 < Count) 
  { 
   var a = 2 * pos + 1; 
   var b = 2 * pos + 2; 
   if (b < Count && list[b].Second < list[a].Second) a = b; 
   if (list[a].Second >= k) break; 
   list[pos] = list[a]; 
   pos = a; 
  } 
  list[pos] = x; 
  return value; 
 } 
} 
class P 
{ 
 public int First; 
 public int Second; 
 public P(int s = 0, int t = 0) 
 { 
  First = s; 
  Second = t; 
 } 
