using System; 
using System.Text; 
using System.Collections.Generic; 
class Solve{ 
    public Solve(){} 
    StringBuilder sb; 
    public static int Main(){ 
        new Solve().Run(); 
        return 0; 
    } 
    void Run(){ 
        sb = new StringBuilder(); 
        Calc(); 
        Console.Write(sb.ToString()); 
    } 
    void Calc(){ 
        string[] str = Console.ReadLine().Split(\' \'); 
        int N = int.Parse(str[0]); 
        int K = int.Parse(str[1]); 
        if(K == 1){ 
            sb.Append("1\
"); 
            return; 
        } 
        Fact F = new Fact(N*K); 
        long[,] dp = new long[N+1,N+1]; 
        for(int i=0;i<N+1;i++){ 
            dp[i,0] = 1; 
            for(int j=1;j<=i;j++){ 
                int L = N*K - i - j*(K-1) + K-1; 
                dp[i,j] = ((dp[i,j-1]*F.GetConv(L-1,K-2)%Define.mod)+dp[i-1,j])%Define.mod;  
            } 
        } 
        sb.Append((dp[N,N]*F.GetFact(N)%Define.mod)+"\
"); 
    } 
} 
class Fact{ 
    public long[] f; 
    public long[] rf; 
    public Fact(int N){ 
        f = new long[N+1]; 
        rf = new long[N+1]; 
        for(int i=0;i<N+1;i++){ 
            if(i == 0){ 
                f[i] = 1; 
            } 
            else{ 
                f[i] = (f[i-1]*i)%Define.mod; 
            } 
        } 
        for(int i=N;i>=0;i--){ 
            if(i == N){ 
                rf[i] = pow(f[N],Define.mod-2); 
            } 
            else{ 
                rf[i] = rf[i+1]*(i+1)%Define.mod; 
            } 
        } 
    } 
    public long pow(long N,long K){ 
        if(K == 0){ 
            return 1; 
        } 
        else if(K % 2 == 0){ 
            long t = pow(N,K/2); 
            return t*t%Define.mod; 
        } 
        else{ 
            return N*pow(N,K-1)%Define.mod; 
        } 
    } 
    public long GetFact(int N){ 
        return f[N]; 
    } 
    public long GetConv(int N,int R){ 
        return ((f[N]*rf[R])%Define.mod*rf[N-R])%Define.mod; 
    } 
} 
public static class Define{ 
    public const long mod = 1000000007; 
}'

