  memset(vis,0,sizeof(vis)); 
  int h,n,m; 
  scanf("%d%d%d",&h,&n,&m); 

  int c[n][m],f[n][m]; 
  for(int i=0;i<n;++i) 
    for(int j=0;j<m;++j) 
      scanf("%d",c[i]+j); 
  for(int i=0;i<n;++i)   
    for(int j=0;j<m;++j) 
      scanf("%d",f[i]+j); 

  node arr[n*m+2000]; 
  int s=0; 
  arr[s++]=(node){0,0,0}; 
  while(s){ 
    qsort(arr,s,sizeof(node),compare); 
    node p=arr[0]; 
    arr[0]=arr[--s]; 
    if(vis[p.x][p.y])continue; 
    vis[p.x][p.y]=1; 
    if(p.x==n-1 && p.y==m-1) 
      return p.time; 

    for(int i=0;i<4;++i){ 
      int nx=p.x+dx[i],ny=p.y+dy[i]; 
      if(0>nx || 0>ny || 
         nx>=n || ny>=m)continue; 
      if(c[nx][ny]-f[nx][ny]<50)continue; 
      if(c[nx][ny]-f[p.x][p.y]<50)continue; 
      if(c[p.x][p.y]-f[nx][ny]<50)continue; 
