      double ct=(50-c[nx][ny]+h); 
      if(ct<=p.time){ 
        if((h-p.time)-f[p.x][p.y]>=20) 
          arr[s++]=(node){nx,ny,p.time+10}; 
        else 
          arr[s++]=(node){nx,ny,p.time+100}; 
      }else{ 
        if((h-ct)-f[p.x][p.y]>=20) 
          arr[s++]=(node){nx,ny,ct+10}; 
        else 
          arr[s++]=(node){nx,ny,ct+100}; 
      } 
    } 
  } 
} 

