#define MOD 100003 

int arrNo[MAXN+1][MAXN+1]; 
int combArr[MAXN+1][MAXN+1]; 
int inv[MOD]; 

void allInverses(); 
int comb(int a, int b); 
int noWays(int n, int s); 

void doTestCase(){ 
 int n; 
