      int ptr = 0; 
      long min = Long.MAX_VALUE / 2; 
      for (int i = 1; i <= n; ++i) { 
        while (2 * (x[i] - x[ptr + 1]) > t) 
          ++ptr; 
        state[1][i] = ptr; 
        for (int j = (int) state[1][i - 1]; j < (int) state[1][i]; ++j) 
          min = Math.min(min, state[0][j] - 2 * x[j + 1]); 
        state[0][i] = Math.min(min + 2 * x[i], state[0][(int) state[1][i]] + t); 
      } 
      long ans = state[0][n] + e; 
      out.println(ans); 
