public class Main { 
  private static void solve() { 
    int n = ni(); 
    int k = ni(); 

    int[] par = new int[n]; 
    for (int i = 0; i < n; i ++) { 
      par[i] = ni() - 1; 
    } 
    int rootTo = par[0]; 
    par[0] = -1; 
    int[][] g = parentToG(par); 

    int[] ret = dfs(0, -1, g, k); 

    int result = ret[1] + (rootTo != 0 ? 1 : 0); 
    System.out.println(result); 

  } 

  private static int[] dfs(int now, int pre, int[][] g, int k) { 
    int[] ret = {0, 0}; 
    for (int next : g[now]) { 
      if (next == pre) continue; 

      int[] v = dfs(next, now, g, k); 
      ret[0] = Math.max(ret[0], v[0] + 1); 
      ret[1] += v[1]; 
    } 
    if (ret[0] == k - 1) { 
      if (pre > 0) { 
        ret[0] = -1; 
        ret[1] ++; 
      } 
    } 
    return ret; 
  } 

  public static int[][] parentToG(int[] par) 
  { 
      int n = par.length; 
      int[] ct = new int[n]; 
      for(int i = 0;i < n;i++){ 
          if(par[i] >= 0){ 
              ct[i]++; 
              ct[par[i]]++; 
          } 
      } 
      int[][] g = new int[n][]; 
      for(int i = 0;i < n;i++){ 
          g[i] = new int[ct[i]]; 
      } 
      for(int i = 0;i < n;i++){ 
          if(par[i] >= 0){ 
              g[par[i]][--ct[par[i]]] = i; 
              g[i][--ct[i]] = par[i]; 
          } 
      } 
      return g; 
  } 


