class Solver { 
  struct Edge { 
    int to, ne, w; 
  }; 

  vi firs; 
  vector<Edge> es; 
  int en; 
  vi was; 
  int wver; 

  bool dfs(int v) { 
    if (v == en) return true; 
    if (was[v] >= wver) return false; 
    was[v] = wver; 
    for (int i = firs[v]; i >= 0; i = es[i].ne) if (es[i].w > 0) { 
      if (dfs(es[i].to)) { 
        es[i].w--; 
        es[i ^ 1].w++; 
        return true; 
      } 
    } 
    return false; 
  } 
public: 
  Solver(int n) : firs(n, -1), es() {} 
  void adde(int a, int b, int w) { 
    es.pb({b, firs[a], w}); firs[a] = sz(es) - 1; 
    es.pb({a, firs[b], 0}); firs[b] = sz(es) - 1; 
  } 
  int solve(int st, int _en) { 
    en = _en; 
    was = vi(sz(firs), 0); 
    wver = 0; 
    int fl = 0; 
    for (;;) { 
      wver++; 
      if (!dfs(st)) break; 
      fl++; 
    } 
    return fl; 
  } 
}; 

const int inf = int(1e9); 
const int FINF = 1000; 

void solve() { 
  int n, m, k; 
