  vvi es(n); 
  vvi g(n, vi(n, inf)); 
  forn (i, m) { 
    int a, b; 
    scanf("%d%d", &a, &b); 
    es[a].pb(b); 
    es[b].pb(a); 
    g[a][b] = g[b][a] = 1; 
  } 
  assert(k >= 1); 

  forn (i, n) g[i][i] = 0; 
  forn (i, n) 
  forn (j, n) 
  forn (k, n) 
    g[j][k] = min(g[j][k], g[j][i] + g[i][k]); 

  Solver s(2 * n); 
  forn (i, n) { 
    s.adde(2 * i, 2 * i + 1, 1); 
    for (int b : es[i]) 
      if (g[0][i] + 1 == g[0][b]) { 
        s.adde(2 * i + 1, 2 * b, FINF); 
      } 
  } 
