using namespace std; 

int N, M, inf=1e9; 
typedef pair<int, int> P; 
typedef pair<int, P> PP; 
map <P, vector<PP>> mp; 
map <P, int> cost; 

void dijkstra(P start){ 
    priority_queue < PP, vector<PP>, greater<PP> > q; 
    for (auto itr = mp.begin(); itr != mp.end(); itr++) cost[itr->first] = inf; 
    cost[start] = 0; 
    q.push(PP(0, start)); 
    while (q.size()) { 
        P current_station = q.top().second; 
        q.pop(); 
        for (PP next : mp[current_station]) { 
            P next_station = next.second; 
            int c = next.first; 
            if (cost[next_station] > cost[current_station] + c) { 
                cost[next_station] = cost[current_station] + c; 
                q.push(PP(cost[next_station], next_station)); 
            } 
        } 
    } 
} 

