 for(int i = 1, a, b, c; i <= m; i++)
 {
  scanf("%d%d%d", &a, &b, &c);
  --a, --b;
  G[a][b] = G[b][a] = c;
 }

 fs = (1 << n) - 1;

 for(int S = 1; S <= fs; S++)
  for(int i = 0; i < n; i++)
  {
   if((S >> i) & 1) continue;

   for(int j = 0; j < n; j++)
    if((S >> j) & 1) g[S][i] += G[i][j];
  }

 memset(f, inf, sizeof(f));

 f[1][0] = 0;
 for(int S = 1; S <= fs; S++)
  for(int i = 0; i < n; i++)
   if((S >> i) & 1)
   {
    for(int s = (S - 1) & S; s; s = (s - 1) & S)
     if((s >> i) & 1)
     {
      int val = 0;

      for(int j = 0; j < n; j++)
       if(i != j && ((s >> j) & 1))
        val += g[S ^ s][j];

