    static int[] a; 
    static int[][] gcd; 
    static UnionFind uf; 
    static List<Integer>[] graph; 
    static boolean[] visited; 

    static int[] dfs(int now) { 
        int cn = graph[now].size(); 

        int[][] ln = new int[cn][]; 
        for (int i = 0; i < cn ; i++) { 
            ln[i] = dfs(graph[now].get(i)); 
        } 
        return merge(now >= a.length ? 0 : a[now], ln); 
    } 

    static int[] merge(int x, int[][] cn) { 
        int l = 1; 
        int gn = cn.length; 
        for (int i = 0; i < gn ; i++) { 
            l += cn[i].length; 
        } 
        int[] d = new int[l]; 
        d[0] = x; 

        int[] gi = new int[gn]; 
        for (int i = 1 ; i < l ; i++) { 
            int ma = 0; 
            int max = 0; 
            for (int j = 0; j < gn ; j++) { 
                if (gi[j] < cn[j].length && max < cn[j][gi[j]]) { 
                    max = cn[j][gi[j]]; 
                    ma = j; 
                } 
            } 
            d[i] = max; 
            gi[ma]++; 
        } 
        return d; 
    } 

    static void makeTree(int idx) { 
        visited[idx] = true; 
        for (int i = 0 ; i < a.length ; i++) { 
            if (!visited[i] && gcd[idx][i] >= 2) { 
                graph[idx].add(i); 
                makeTree(i); 
            } 
        } 
    } 

    public static long gcd(long a, long b) { 
        return b == 0 ? a : gcd(b, a%b); 
    } 

    static class UnionFind { 
        int[] rank; 
        int[] parent; 
        int[] cnt; 

        public UnionFind(int n) { 
            rank = new int[n]; 
            parent = new int[n]; 
            cnt = new int[n]; 
            for (int i = 0; i < n; i++) { 
                parent[i] = i; 
                cnt[i] = 1; 
            } 
        } 

        public int find(int a) { 
            if (parent[a] == a) { 
                return a; 
            } 
            parent[a] = find(parent[a]); 
            return parent[a]; 
        } 

        public void unite(int a, int b) { 
            a = find(a); 
            b = find(b); 
            if (a == b) { 
                return; 
            } 
            if (rank[a] < rank[b]) { 
                parent[a] = b; 
                cnt[b] += cnt[a]; 
                cnt[a] = cnt[b]; 
            } else { 
                parent[b] = a; 
                cnt[a] += cnt[b]; 
                cnt[b] = cnt[a]; 
                if (rank[a] == rank[b]) { 
                    rank[a]++; 
                } 
            } 
        } 

        public int groupCount(int a) { 
            return cnt[find(a)]; 
        } 

        private boolean issame(int a, int b) { 
            return find(a) == find(b); 
        } 
    } 


