                for (int i = 0; i < n - 2; i += 2) { 
                    if (b[i] < x || b[i + 1] < b[i]) { 
                        b[i + 2] += b[i] - b[i + 1]; 
                    } 
                } 

                if (b[n - 1] >= x) { 
                    min = x; 
                } else { 
                    max = x; 
                } 
            } 

            int sugim = Math.max(sum[0], sum[1] + min); 
            int sigma = sum[0] + sum[1] - sugim; 
            out.println(sugim + " " + sigma); 
        } 

    } 

