            int A = int.Parse(buf[i]); 
            if (d.ContainsKey(A)) 
            { 
                d[A] = d[A] + 1; 
            } 
            else 
            { 
                d.Add(A, 1); 
            } 
        } 

        int j = 0; 
        int count = 0; 
        var sorted = d.OrderBy((x) => x.Value); 
        foreach (var x in sorted) 
        { 
            if (d.Count - k < ++j) 
            { 
                break; 
            } 
            count += x.Value; 

        } 
        Console.WriteLine(count); 
    } 

