                v1s[i] = new Vertex(); 
                v2s[i] = new Vertex(); 
                all.add(v1s[i]); 
                all.add(v2s[i]); 
            } 
            for (int i = 0; i < m; ++i) { 
                int ia = in.nextInt() - 1; 
                int ib = in.nextInt() - 1; 
                long c = in.nextLong(); 
                v1s[ia].adj.add(new Edge(v2s[ib], c)); 
                v1s[ib].adj.add(new Edge(v2s[ia], c)); 
                v2s[ia].adj.add(new Edge(v1s[ib], c)); 
                v2s[ib].adj.add(new Edge(v1s[ia], c)); 
            } 
            { 
                p2 = new long[(int) (mod + 10)]; 
